import{n as e,r as t}from"./rolldown-runtime-CNOWq4Kh.js";var n=t({default:()=>r}),r;function i(){return(i=e((()=>{r={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Controls de l'entorn d'execució d'ACP per activar l'enviament, seleccionar rerefons, restringir els agents de destinació permesos i seleccionar el comportament de projecció dels torns en transmissió contínua.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Agents permesos d'ACP`},help:{"v1-f2mw0d-3a":`Llista d'identificadors d'agents de destinació d'ACP permesos per a les sessions de l'entorn d'execució d'ACP. Si és buida, no s'aplica cap restricció addicional de llista de permesos.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Rerefons d'ACP`},help:{"v1-1s1l6bz-2v":`Identificador del rerefons predeterminat de l'entorn d'execució d'ACP (per exemple: acpx). Ha de coincidir amb un rerefons de connector de l'entorn d'execució d'ACP registrat.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Agent predeterminat d'ACP`},help:{"v1-7donnu-2c":`Identificador de l'agent de destinació alternatiu d'ACP que s'utilitza quan les creacions d'ACP no especifiquen una destinació explícita.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Enviament d'ACP activat`},help:{"v1-1ug9t9m-3w":`Control d'enviament independent per als torns de sessió d'ACP (valor predeterminat: true). Establiu-lo a false per mantenir disponibles les ordres d'ACP mentre es bloqueja l'execució dels torns d'ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP activat`},help:{"v1-1uonl1v-2a":`Control global de la funcionalitat ACP. Manteniu-lo desactivat tret que l'entorn d'execució i la política d'ACP estiguin configurats.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Rerefons alternatius d'ACP`},help:{"v1-1wvdifq-5m":`Llista ordenada d'identificadors de rerefons alternatius d'ACP que es proven quan el rerefons principal falla amb UNAVAILABLE (per exemple: límit de peticions / quota esgotada). Cada entrada ha de coincidir amb un rerefons de connector de l'entorn d'execució d'ACP registrat.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Ordre d'instal·lació de l'entorn d'execució d'ACP`},help:{"v1-1jjuv9m-39":"Ordre opcional d'instal·lació o configuració per a l'operador que mostren `/acp install` i `/acp doctor` quan falta la connexió amb el backend d'ACP."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Flux d'ACP`},help:{"v1-1bka5p-2v":`Controls de projecció del flux d'ACP per a la mida dels fragments, la visibilitat de les metadades i el comportament de lliurament sense duplicats.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Mode de lliurament del flux d'ACP`},help:{"v1-19gdmx1-3s":`Estil de lliurament d'ACP: live transmet la sortida projectada de manera incremental; final_only emmagatzema temporalment tota la sortida projectada d'ACP fins als esdeveniments de final de torn.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Supressió de repeticions del flux d'ACP`},help:{"v1-manh32-3d":`Quan és true (valor predeterminat), suprimeix les línies repetides de projecció d'estat o d'eines d'ACP dins d'un torn, sense modificar els esdeveniments d'ACP en brut.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Visibilitat de les etiquetes del flux d'ACP`},help:{"v1-1ybhx22-34":`Substitucions de visibilitat per sessionUpdate per a la projecció d'ACP (per exemple, usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agents`},help:{"v1-2rc4v8-55":`Arrel de la configuració d'execució dels agents. Els nodes germans de l'arrel gestionen la infraestructura i els valors predeterminats comuns a tots els agents; agents.defaults gestiona el comportament del bucle dels agents; les entrades dels agents poden substituir uns o altres quan s'admeti.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Valors predeterminats dels agents`},help:{"v1-1af7k5b-5a":`Configuració predeterminada compartida que hereten els agents, tret que se substitueixi en cada entrada d'agents.entries. Feu servir els valors predeterminats per garantir un comportament de base coherent i reduir la configuració duplicada per agent.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Destinació de l'herència d'autenticació`},help:{"v1-2d16wl-2x":`Propietari de compatibilitat de l'actualització per al magatzem de credencials heretat fins que les credencials es reubiquin per agent.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Propietari de l'herència d'autenticació`},help:{"v1-1a1s7nm-4s":`Agent el magatzem de credencials antic del qual continua sent la font d'herència després de retirar el marcador de valor per defecte. S'escriu automàticament durant l'actualització quan el propietari anterior no era main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Màxim de caràcters d'inicialització`},help:{"v1-drlo3i-37":`Nombre màxim de caràcters de cada fitxer d'inicialització de l'espai de treball injectat a la instrucció del sistema abans de truncar-lo (per defecte: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Màxim total de caràcters d'inicialització`},help:{"v1-1evwsjb-2c":`Nombre màxim total de caràcters entre tots els fitxers d'inicialització de l'espai de treball injectats (per defecte: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Compactació`},help:{"v1-1qxdwz8-5p":`Comportament de compactació quan el context s'apropa als límits de tokens, incloent-hi l'estratègia i el comportament de desament de memòria previ a la compactació. Feu-lo servir quan les sessions de llarga durada necessitin una continuïtat estable amb finestres de context reduïdes.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Compactació automàtica integrada`},help:{"v1-1et7vwu-5l":`Activa la compactació automàtica proactiva integrada (per defecte: true). Establiu-ho a false per aturar la compactació integrada basada en llindars i conservar la recuperació per desbordament d'OpenClaw, la compactació prèvia a l'execució i l'ordre manual /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Política d'identificadors de compactació`},help:{"v1-hby01l-4l":`Política de preservació d'identificadors per als resums de compactació: "strict" anteposa les directrius integrades de conservació d'identificadors opacs (per defecte), mentre que "off" desactiva aquest prefix.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Tokens recents que es conserven en la compactació`},help:{"v1-tgysub-5h":`Pressupost mínim de tokens que es conserven de la finestra de conversa més recent durant la compactació. Feu servir valors més alts per protegir la continuïtat del context immediat i valors més baixos per conservar més historial antic.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-476m1y-11":`Llindar de mida del xat actiu per a la compactació`},help:{"v1-7p9ney-ah":`Llindar en bytes per a la compactació local prèvia en l'entorn d'execució integrat (bytes o cadenes com ara "20mb"). En el cas de Codex app-server, limita, en canvi, l'historial inicial dels fils nous: un únic intent de resum per part de l'amfitrió només quan s'ometria historial sense resumir, mai en torns ordinaris ni després d'un /compact natiu. Establiu-lo a 0 o deixeu-lo sense definir per desactivar-lo. Els límits de seguretat natius de mida del registre d'execució i de tokens no canvien.`}},"agents%2Edefaults%2Ecompaction%2EmaxSummaryChars":{label:{"v1-18p81ru-x":`Màxim de caràcters del resum de compactació`},help:{"v1-em0nj5-8b":`Nombre màxim de caràcters d'un resum de compactació persistent del costat del client (valor per defecte: 16000; interval: 1000–200000). Els resums més llargs conserven més context generat, però augmenten el cost de tornar-lo a processar en sol·licituds posteriors. El límit de tòkens del model actiu pot requerir un resum més curt. No controla la compactació nativa del proveïdor.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Desament de memòria abans de la compactació`},help:{"v1-1xbzc1i-6t":`Configuració del desament de memòria previ a la compactació, que executa una escriptura de memòria mitjançant un agent amb el model de la sessió activa i la seva cadena habitual d'alternatives abans d'una compactació intensa. Manteniu-lo activat per a sessions llargues perquè el context rellevant es desi de manera persistent abans d'una retallada agressiva.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Desament de memòria abans de la compactació activat`},help:{"v1-9xllgp-5o":`Activa el desament de memòria previ a la compactació abans que l'entorn d'execució redueixi l'historial de manera més intensa quan s'acosta als límits de tokens. Manteniu-lo activat tret que vulgueu desactivar expressament els efectes secundaris sobre la memòria en entorns amb recursos limitats.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-1mr3mj1-17":`Llindar de mida del xat per al buidatge de memòria abans de la compactació`},help:{"v1-pihai2-8y":`Força el buidatge de memòria abans de la compactació quan l'historial del xat visible per al model arriba a aquest llindar (en bytes o amb cadenes com ara "2mb"). Després de la compactació, això inclou el tram final conservat i els torns posteriors, en lloc de l'historial descartat. Feu-lo servir per evitar bloquejos en sessions llargues, fins i tot quan els comptadors de tokens no estan actualitzats; establiu-lo a 0 per desactivar-lo.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Llindar flexible del desament de memòria de compactació`},help:{"v1-1dqo2l1-5c":`Marge fins a la compactació (en tokens) que activa l'execució del desament de memòria previ a la compactació. Feu servir llindars més anticipats per garantir una persistència més segura, o llindars més ajustats per reduir la freqüència de desament.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Comprovació prèvia de compactació a mig torn`},help:{"v1-12ud1gw-6c":`Llindar opcional de pressió estimada entre rondes d'eines que utilitza la reserva de compactació. El manteniment del llindar mesurat pel proveïdor i el control d'admissió estricte de la finestra de context s'executen de manera independent i reutilitzen la recuperació mitjançant truncament segur o compactació.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Comprovació prèvia de compactació a mig torn activada`},help:{"v1-1or5cwa-57":`Activa el llindar opcional de pressió estimada entre rondes d'eines. Valor per defecte: false. El manteniment del llindar mesurat i la comprovació estricta de la finestra de context continuen actius quan aquesta opció està desactivada.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Mode de compactació`},help:{"v1-1unahwc-76":`Mode d'estratègia de compactació: "safeguard" (el valor efectiu per defecte si no s'especifica) aplica proteccions per preservar el context recent, mentre que "default" utilitza un resum bàsic sense aquestes proteccions. Defineix "default" només si el resum amb proteccions causa problemes amb el teu proveïdor.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Model alternatiu per a la compactació`},help:{"v1-cfeys9-6q":`Proveïdor/model opcional o àlies configurat sense prefix que s'utilitza només per generar resums de compactació. Els àlies sense prefix es resolen abans de l'enviament; un ID de model literal configurat té prioritat si coincideix amb un àlies. Deixa-ho sense definir per continuar utilitzant el model principal de l'agent.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Notificació de compactació a l'usuari`},help:{"v1-lvymm8-bv":`Quan està activat, envia avisos breus de manteniment del context a l'usuari: quan la compactació comença i acaba (per exemple, '🧹 S'està compactant el context...' i '🧹 Compactació completada'), i quan s'esgoten els intents de desar la memòria abans de la compactació i la resposta continua en un estat degradat (per exemple, '⚠️ El manteniment de la memòria ha fallat temporalment; es continua amb la resposta.'). Està desactivat per defecte perquè el manteniment del context sigui silenciós i no intrusiu.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Seccions de context posteriors a la compactació`},help:{"v1-1n0ln2u-5f":`Noms de les seccions H2/H3 d'AGENTS.md que es reinjecten després de la compactació si s'activa aquesta opció. Deixeu-ho sense definir o establiu [] per desactivar la reinjecció. Establiu explícitament ["Session Startup", "Red Lines"] per activar la parella predeterminada anterior.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Sincronització de l'índex després de la compactació`},help:{"v1-ekpjeq-6l":`Controla el mode de reindexació de la memòria de la sessió després de la compactació: "off", "async" o "await" (per defecte: "async"). Feu servir "await" per garantir la màxima actualització, "async" per reduir la latència de compactació i "off" només quan la sincronització de la memòria de la sessió es gestioni per una altra via.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Proveïdor de compactació`},help:{"v1-2zoy3b-7v":`Identificador d'un connector de proveïdor de compactació registrat que s'utilitza per generar resums. Quan s'estableix i el proveïdor està registrat, es crida el seu mètode summarize() en lloc de la sol·licitud de resum integrada. Si el proveïdor falla, es recorre a la funcionalitat integrada. Deixeu-ho sense definir per utilitzar la generació de resums integrada per defecte.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Control de qualitat de la compactació`},help:{"v1-u9ognp-4k":`Configuració dels reintents d'auditoria de qualitat dels resums de compactació en mode safeguard. El mode safeguard activa aquesta funció per defecte; establiu enabled: false per ometre les auditories i la regeneració dels resums.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Control de qualitat de la compactació activat`},help:{"v1-1xk2vt3-36":`Activa les auditories de qualitat dels resums i els reintents de regeneració per a la compactació en mode safeguard. Valor per defecte: true en mode safeguard.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Nombre màxim de reintents del control de qualitat de la compactació`},help:{"v1-n7l46y-3y":`Nombre màxim de reintents de regeneració després que falli una auditoria de qualitat del resum de salvaguarda. Feu servir valors baixos per limitar la latència addicional i el cost en tokens.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Torns recents que cal conservar durant la compactació`},help:{"v1-y34ihi-5k":`Nombre de torns més recents de l'usuari i de l'assistent que es conserven literalment fora del resum de salvaguarda (per defecte: 3). Augmenteu aquest valor per conservar el context exacte del diàleg recent o reduïu-lo per maximitzar l'estalvi de la compactació.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Nivell de raonament de la compactació`},help:{"v1-1vafgaw-g1":`Nivell de raonament que s'utilitza només per als resums de compactació integrats d'OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" o "inherit". Per defecte, s'utilitza la preferència de compactació del proveïdor o, si no n'hi ha cap, "low"; Ollama local natiu prefereix "off". Establiu "inherit" per reutilitzar el nivell de la sessió. La configuració explícita té prioritat sobre els valors per defecte del proveïdor, i el nivell seleccionat s'ajusta als límits del model i de l'entorn d'execució de compactació reals. La compactació nativa de Codex app-server ignora aquesta configuració perquè la seva sol·licitud de compactació no permet sobreescriure el nivell de raonament per operació, i OpenClaw registra un advertiment.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Temps d'espera de la compactació (segons)`},help:{"v1-p0ymcy-c4":`Segons que una sol·licitud al model de compactació integrat pot passar sense progrés (per defecte: 180). Cada inici de sol·licitud i cada token de sortida transmès renoven el període, de manera que una sol·licitud lenta que continua transmetent no s'interromp; la compactació completa s'atura després de 10 períodes. La compactació gestionada per un connector disposa d'un període, tret que el motor declari explícitament onProgress a info.acceptedHostParams i informi del progrés; s'hi aplica el mateix límit de 10 períodes.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Injecció de context`},help:{"v1-u18x0-7u":`Controla la injecció de fitxers d'inicialització de l'espai de treball a l'entorn d'execució integrat: "always" utilitza la injecció normal (per defecte), "continuation-skip" omet els torns de continuació elegibles després d'un torn registrat amb inicialització completa, i "never" desactiva la injecció. No controla la preparació d'instruccions mitjançant la CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Límits de context per defecte`},help:{"v1-1coeez8-5d":`Valors per defecte de la quota de context per agent, específics per a determinats fragments de gran volum i blocs d'instruccions injectats. Utilitzeu-los per ajustar les mides limitades de lectura i injecció sense tornar a habilitar cap via de crida sense límits.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Màxim de caràcters per defecte de memory_get`},help:{"v1-1qb40qv-4v":`Nombre màxim de caràcters que memory_get retorna per defecte abans d'afegir-hi les metadades de truncament i l'avís de continuació. Augmenteu-lo per aproximar-vos als fragments més grans d'abans, però manteniu-ne el límit.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Màxim de caràcters per defecte després de la compactació`},help:{"v1-64qo8g-5r":`Nombre màxim de caràcters d'AGENTS.md conservats per defecte en la injecció d'actualització del context després de la compactació. Reduïu aquest valor per abaratir la recuperació després de la compactació, o augmenteu-lo per als agents que depenen d'instruccions d'inici més llargues.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Directori de treball`},help:{"v1-1y8wlxn-6a":`Directori de treball per a les execucions de resposta de l'agent, separat dels fitxers d'inicialització de l'espai de treball i de memòria. El cwd específic de l'agent i el cwd establert en crear la sessió tenen prioritat. Admet ~ i camins relatius; un cwd diferent requereix una execució fora de l'entorn aïllat.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Model de decisió`},help:{"v1-7nd7ze-64":`Proveïdor/model opcional per a seleccions tipades, puntuacions i probabilitats booleanes. Si no es defineix o es deixa buit, es desactiven les crides de decisió. Els connectors compatibles envien a aquest proveïdor un conjunt limitat d'evidències de la tasca; els models de xat i d'utilitat no canvien.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`OpenClaw integrat`},help:{"v1-1keek32-3k":`Controls de reforç de la seguretat de l'executor d'OpenClaw integrat que determinen com es confia en la configuració local dels agents de l'espai de treball i com s'aplica a les sessions d'OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Commutació per error de la política de ciberseguretat`},help:{"v1-pl298d-4c":`Escalat automàtic a Daybreak amb el mateix model davant de denegacions de la política de ciberseguretat d'OpenAI que es poden reintentar de manera segura en l'entorn d'execució integrat, subjecte a les comprovacions d'accés i de polítiques existents.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Temps d'espera de la commutació per error de la política de ciberseguretat`},help:{"v1-1hhmb1o-2l":`Temps durant el qual s'omet l'accés no disponible a Daybreak per al model actiu en la sessió actual.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Mode de commutació per error de la política de ciberseguretat`},help:{"v1-rzsd2b-2h":`Activa l'escalat automàtic ("auto", per defecte) o manté els rebutjos del proveïdor com a definitius ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Contracte d'execució de l'OpenClaw integrat`},help:{"v1-1fch2ig-66":`Contracte d'execució de l'OpenClaw integrat: "default" manté el comportament estàndard de l'executor, mentre que "strict-agentic" activa el seguiment estructurat de plans i la recuperació no visible de torns per a les execucions compatibles de la família GPT-5 d'OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Política de configuració del projecte de l'OpenClaw integrat`},help:{"v1-fdyy04-65":`Com gestiona l'OpenClaw integrat el fitxer \`.openclaw/settings.json\` local de l'espai de treball: "sanitize" (per defecte) elimina shellPath/shellCommandPrefix, "ignore" desactiva completament la configuració del projecte i "trusted" aplica la configuració del projecte sense modificar-la.`}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Indicadors experimentals de l'agent`},help:{"v1-cvv5cl-2w":`Indicadors experimentals dels valors per defecte de l'agent. Mantén-los desactivats tret que estiguis provant expressament una funcionalitat preliminar.`}},"agents%2Edefaults%2Eexperimental%2EdecisionAssistance":{label:{"v1-1tepbyi-y":`Assistència per a la presa de decisions (experimental)`},help:{"v1-1fmo3r9-ew":`Activació global de l'assistència experimental del model de decisió configurat de l'agent responsable (valor predeterminat: false; requereix true explícitament). El valor efectiu de decisionModel es pot heretar dels valors predeterminats globals o seleccionar per agent; un valor buit per agent desactiva l'assistència. Els usos admesos poden enviar dades seleccionades a aquest proveïdor i generar càrrecs del proveïdor. Consulteu la documentació de l'assistència de decisió per obtenir informació sobre els usos admesos, la configuració i el tractament de les dades. Aquesta opció no condiciona les crides explícites a decision_evaluate, no selecciona proveïdors ni autoritza accions.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Activa el mode lleuger del model local (experimental)`},help:{"v1-gj06u6-7b":`Opció avançada de resolució de problemes que restringeix eines opcionals com ara browser, automations i message. Desactivada per defecte; els entorns d'execució locals compatibles utilitzen la cerca automàtica d'eines sense aquesta restricció. Es mantenen les autoritzacions explícites d'eines i les eines de lliurament obligatòries.`}},"agents%2Edefaults%2Eexperimental%2EusageRankedToolIndex":{label:{"v1-ndslef-12":`Índex d'eines ordenat segons l'ús (experimental)`},help:{"v1-1jpzjov-bq":`Activa voluntàriament els índexs d'indicacions de Code Mode, Tool Search i del directori d'eines MCP, ordenats segons l'ús, a l'entorn d'execució integrat d'OpenClaw (per defecte: false). Durant 90 dies, només emmagatzema identificadors d'eines, puntuacions amb decaïment i marques de temps a l'emmagatzematge de l'agent propietat de l'operador; exclou les sessions d'incògnit. Les classificacions es mantenen fixes fins a un límit de prefix d'indicació. No modifica els permisos de les eines ni Codex. Inspecciona les dades, importa l'ús anterior o restableix-les amb openclaw tools usage.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Mode ràpid predeterminat de l'agent`},help:{"v1-6q8gx8-3c":`Política predeterminada del mode ràpid per al bucle de l'agent ("auto", "ultrafast", true o false). Les entrades individuals dels agents la sobreescriuen.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Retard humà màxim (ms)`},help:{"v1-vnmvli-1m":`Retard màxim en ms per al valor personalitzat de humanDelay (valor predeterminat: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Retard humà mínim (ms)`},help:{"v1-5nrtr5-1l":`Retard mínim en ms per al valor personalitzat de humanDelay (valor predeterminat: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Mode de retard humà`},help:{"v1-k7hyg3-1n":`Tipus de retard per a les respostes en blocs ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Dimensió màxima de la imatge (px)`},help:{"v1-1j31o2j-2s":`Longitud màxima del costat de les imatges en píxels en sanejar les dades d'imatge del xat i dels resultats de les eines (valor per defecte: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Models d'imatge alternatius`},help:{"v1-1kgx5i9-1b":`Models d'imatge alternatius ordenats (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Model d'imatge`},help:{"v1-dstqyh-2c":`Model d'imatge opcional (provider/model) que s'utilitza quan el model principal no admet imatges d'entrada.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Qualitat de la imatge`},help:{"v1-1uyxc5s-6u":`Preferència de compressió dels continguts multimèdia de l'eina d'imatges: "auto" s'adapta als límits del proveïdor/model i al nombre d'imatges, "efficient" estalvia tokens i bytes, "balanced" manté l'equilibri actual i "high" conserva més detalls de les captures de pantalla i les imatges de documents.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Models alternatius de generació d'imatges`},help:{"v1-oljfk4-1m":`Models alternatius de generació d'imatges ordenats (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Model de generació d'imatges`},help:{"v1-g4yw0h-2o":`Model opcional de generació d'imatges (provider/model) que utilitza la funcionalitat compartida de generació d'imatges.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Temps d'espera màxim de generació d'imatges (ms)`},help:{"v1-9yesfj-31":`Temps d'espera predeterminat de les sol·licituds al proveïdor, en mil·lisegons, per a les crides a image_generate. El valor timeoutMs de cada crida té prioritat sobre aquest valor.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Models alternatius de generació de música`},help:{"v1-wyg9xe-1m":`Models alternatius de generació de música, en ordre (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Model de generació de música`},help:{"v1-xs1e2h-2o":`Model opcional de generació de música (provider/model) utilitzat per la funcionalitat compartida de generació de música.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Models alternatius de generació de vídeo`},help:{"v1-wpbf1e-1m":`Models alternatius de generació de vídeo, en ordre (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Model de generació de vídeo`},help:{"v1-hfmlbl-2o":`Model opcional de generació de vídeo (provider/model) utilitzat per la funcionalitat compartida de generació de vídeo.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Temps d'espera de generació de vídeo (ms)`},help:{"v1-1bqj80s-4i":`Temps d'espera predeterminat de les sol·licituds al proveïdor, en mil·lisegons, per a les crides a video_generate. El valor timeoutMs de cada crida té prioritat sobre aquest valor, i aquest valor té prioritat sobre els valors predeterminats definits pel proveïdor.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Models alternatius`},help:{"v1-t4djq2-24":`Models alternatius, en ordre (provider/model). S'utilitzen quan falla el model principal.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Model principal`},help:{"v1-1i8a1v4-v":`Model principal (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Política de models`},help:{"v1-z0txb7-2e":`Política explícita per a les substitucions de models. Ometeu-la o deixeu allow buit per permetre qualsevol model.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Models permesos`},help:{"v1-1vy0b57-5c":`Referències de model permeses per substituir el model predeterminat. Accepta àlies, referències completes "provider/model" i prefixos amb comodins al final, com ara "openai/*", "clawrouter/anthropic/*" o "openai/gpt-*". Si és buit, permet qualsevol model.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Models`},help:{"v1-13cvq23-4i":`Catàleg de models configurats i configuració de cada model. Les entrades proporcionen àlies, paràmetres, metadades de l'entorn d'execució i substitucions del mode de codi; no restringeixen les substitucions de models.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Entorn d'execució del model de l'agent predeterminat`},help:{"v1-6km9kx-41":`Política opcional d'entorn d'execució per model per a l'agent predeterminat. Feu-la servir per definir excepcions d'entorn d'execució específiques de cada model en lloc d'establir un entorn d'execució per a tot l'agent.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`ID de l'entorn d'execució del model de l'agent predeterminat`},help:{"v1-1co96w7-4a":`Identificador de l'entorn d'execució del model de l'agent predeterminat: "openclaw", "auto", un identificador registrat d'adaptador d'execució d'un connector com ara "codex", o un àlies de rerefons CLI compatible com ara "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Mode de codi`},help:{"v1-rsdl5o-6x":`Mode de codi d'OpenClaw per a aquest proveïdor/model concret: Activat en força l'activació, Desactivat el desactiva i Per defecte hereta tools.codeMode.enabled. La configuració d'activació específica de l'agent té prioritat. Això no canvia l'entorn d'execució seleccionat ni el mode de codi natiu de Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Àmbit de selecció del model`},help:{"v1-sj8owq-bl":`Àmbit per a les ordres del xat i les actualitzacions del model de sessió de la Passarel·la sense un àmbit explícit: "session" (per defecte) només canvia la sessió actual, "agent" també actualitza el model principal d'aquest agent i "global" també actualitza el model alternatiu compartit agents.defaults.model. Els indicadors d'àmbit explícits tenen prioritat; modificar els valors predeterminats configurats requereix permisos de propietari o administrador. Els selectors de retorn de crida de Telegram i la TUI local integrada continuen limitats a la sessió.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Mida màxima del PDF (MB)`},help:{"v1-1uig1dr-1u":`Mida màxima del fitxer PDF en megabytes per a l'eina de PDF (per defecte: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Nombre màxim de pàgines del PDF`},help:{"v1-11na7hp-1y":`Nombre màxim de pàgines de PDF que pot processar l'eina de PDF (per defecte: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Models alternatius per a PDF`},help:{"v1-89ebd8-19":`Models alternatius per a PDF ordenats per prioritat (proveïdor/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Model per a PDF`},help:{"v1-2ktkxt-2y":`Model opcional per a PDF (proveïdor/model) per a l'eina d'anàlisi de PDF. Per defecte, utilitza imageModel i, si no està definit, el model de la sessió.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Arrel del repositori`},help:{"v1-j3sh74-2h":`Arrel opcional del repositori que es mostra a la línia d'execució de la instrucció del sistema (substitueix la detecció automàtica).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Interval de ports d'origen CDP del Navegador de l'entorn aïllat`},help:{"v1-1jkowdc-2b":`Llista opcional de CIDR permesos per al trànsit CDP entrant al límit del contenidor (per exemple, 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Xarxa del Navegador de l'entorn aïllat`},help:{"v1-8m74ud-5w":`Xarxa Docker per als contenidors del navegador de l'entorn aïllat (per defecte: openclaw-sandbox-browser). Utilitzeu la xarxa dedicada predeterminada o una xarxa pont personalitzada; "none" no és compatible perquè el control del navegador requereix ports CDP publicats.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Permet unir-se a l'espai de noms d'un contenidor Docker de l'entorn aïllat`},help:{"v1-qm39de-4c":`Excepció d'emergència PERILLOSA que permet el mode de xarxa Docker container:<id> a l'entorn aïllat. Això uneix el contenidor a l'espai de noms d'un altre contenidor i debilita l'aïllament de l'entorn.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`GPU de Docker de l'entorn aïllat`},help:{"v1-jj0yhw-4k":`Valor opcional d'accés directe a la GPU de Docker que es passa a --gpus, per exemple, "all" o "device=GPU-uuid". Requereix un entorn d'execució compatible a l'amfitrió, com ara NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Destinació del magatzem de sessions heretat`},help:{"v1-1xkej6i-2g":`Propietari de compatibilitat d'actualització per a les files retirades de l'agent principal i els magatzems de sessions heretats fixos.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Propietari del magatzem de sessions heretat`},help:{"v1-ommm7e-5w":`Agent propietari de les files retirades de l'agent principal o de les files sense àmbit en un magatzem de sessions heretat fix després de la retirada del marcador per defecte. S'escriu automàticament durant l'actualització quan el propietari anterior no era l'agent principal ni l'únic agent.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Habilitats`},help:{"v1-1pbsu94-75":`Llista opcional d'habilitats permeses per defecte que hereten els agents que ometen agents.entries.*.skills. Ometeu-la per no restringir les habilitats, establiu [] perquè els agents que l'hereten no tinguin cap habilitat i recordeu que un valor explícit d'agents.entries.*.skills substitueix aquest valor per defecte en lloc de combinar-s'hi.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Omet la creació dels fitxers d'inicialització de l'Espai de treball`},help:{"v1-kbstgw-5v":`Omet la creació automàtica dels fitxers d'inicialització de l'espai de treball, però no la injecció dels fitxers existents. Per a l'entorn d'execució integrat, establiu agents.defaults.contextInjection a "never" per desactivar la injecció, tret que s'anul·li aquest valor per a un agent concret.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Fitxers d'inicialització opcionals omesos`},help:{"v1-1j2z4yj-4c":`Fitxers d'inicialització opcionals que no s'han de crear als espais de treball dels agents. Valors vàlids: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md s'accepta, però no té cap efecte).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Context d'inici`},help:{"v1-1ugsihy-5o":`Preàmbul del primer torn gestionat per l'entorn d'execució per a "/new" i "/reset" sense arguments. Feu-lo servir per controlar si els fitxers de memòria diària recents es precarreguen a la primera indicació en lloc de demanar al model que decideixi què ha de llegir.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Quan s'aplica el context d'inici`},help:{"v1-wav4a5-36":`Tria quines ordres de reinicialització sense arguments reben el context d'inici: incloeu-hi "new", "reset" o totes dues (per defecte: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Dies de memòria diària del context d'inici`},help:{"v1-4i5xcm-3p":`Nombre de fitxers de memòria datats que es carregaran comptant enrere des d'avui en el fus horari configurat de l'usuari (per defecte: 2, per a avui i ahir).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Activa el context d'inici`},help:{"v1-1d5vz2u-4i":`Activa el preàmbul de context d'inici per a les reinicialitzacions de sessió sense arguments (per defecte: true). Desactiveu aquesta opció per tornar al comportament basat només en la indicació, sense memòria diària carregada en temps d'execució.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Màxim de bytes per fitxer del context d'inici`},help:{"v1-11cbian-41":`Nombre màxim de bytes permesos per fitxer de memòria diària en construir el context d'inici (per defecte: 16384). S'ometen els fitxers que superen aquest límit de lectura segura.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Màxim de caràcters per fitxer del context d'inici`},help:{"v1-10z53s-2u":`Nombre màxim de caràcters conservats de cada fitxer de memòria diària carregat al preàmbul d'inici (per defecte: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Màxim total de caràcters del context d'inici`},help:{"v1-sf676u-54":`Nombre màxim total de caràcters conservats entre tots els fitxers de memòria diària carregats al preàmbul d'inici (per defecte: 2800). El contingut dels fitxers addicionals es retalla del preàmbul un cop s'arriba a aquest límit.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Mode de delegació a subagents`},help:{"v1-pqewbk-5o":`Intensitat de la delegació a subagents basada només en instruccions. El valor per defecte és "prefer" a la sessió principal de cada agent i "suggest" a la resta; "prefer" indica fermament a l'agent que delegui la feina no trivial mitjançant sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Destinació de l'agent del sistema`},help:{"v1-1wwimo9-34":`Configuració de destinació per a la inferència en segon pla de l'agent del sistema d'OpenClaw i de Custodian, així com per a determinades lectures de l'operador sense àmbit definit.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Propietari de l'agent del sistema`},help:{"v1-15rvt92-8c":`Agent que proporciona el model i les credencials per a les consultes en segon pla de l'agent del sistema i de Custodian. També s'utilitza quan models.list, models.authStatus, skills.status, doctor.memory.status o una ordre CLI infer que resol el model o l'estat d'autenticació d'un agent omet agentId o --agent; l'agentId explícit de la sol·licitud sempre té prioritat.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Interval d'escriptura (segons)`},help:{"v1-1y701ox-42":`Controla la cadència, en segons, amb què es manté actiu l'indicador d'escriptura de cada agent. Augmenteu aquest valor per reduir la freqüència d'actualització a tots els canals que admeten indicadors d'escriptura.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Mode d'escriptura`},help:{"v1-m2hvpw-3m":`Controla quan s'activa l'indicador d'escriptura dels agents: "never", "instant", "thinking" o "message". El valor typingMode de cada agent té prioritat sobre aquest valor per defecte.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Model auxiliar`},help:{"v1-1cfea4z-cl":`Model opcional de cost reduït (provider/model, àlies o { primary, fallbacks }) per a tasques internes breus, com ara la generació de títols i la narració del progrés. Els models alternatius auxiliars utilitzen la mateixa política de reintents, resolució d'àlies i selecció de models que els models alternatius configurats, independentment de model.fallbacks. Si no es defineix, s'utilitza el model petit declarat pel proveïdor principal, si està disponible (en cas contrari, el model principal); definiu-lo com una cadena buida per desactivar l'encaminament auxiliar.`}},"agents%2Edefaults%2EutilityModel%2Efallbacks":{label:{"v1-rlvlnh-n":`Models alternatius auxiliars`},help:{"v1-12k3amd-2v":`Models alternatius auxiliars ordenats (provider/model o àlies), independents de la llista de models alternatius del model principal.`}},"agents%2Edefaults%2EutilityModel%2Eprimary":{label:{"v1-1rpgua8-l":`Model auxiliar principal`},help:{"v1-11k8uor-1c":`Model auxiliar principal (provider/model o àlies).`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Models de veu alternatius`},help:{"v1-faazv4-1b":`Models de veu alternatius ordenats (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Model de veu`},help:{"v1-1yeh3h4-2t":`Model de veu opcional (provider/model) utilitzat per les funcions de parla, transcripció i veu en temps real.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Temps d'espera de veu (ms)`},help:{"v1-1sbergs-32":`Temps d'espera predeterminat de les sol·licituds al proveïdor, en mil·lisegons, per a les operacions del model de veu quan el component que fa la crida admet temps d'espera.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Espai de treball`},help:{"v1-1u5ipll-5t":`Espai de treball predeterminat de l'agent per als fitxers d'inicialització i de memòria. També s'utilitza com a directori de treball quan agents.defaults.cwd no està definit. Definiu-lo explícitament quan executeu des d'embolcalls perquè la resolució de camins sigui coherent.`}},"agents%2Edefaults%2EworkspaceFileMode":{label:{"v1-13trwkt-k":`Mode dels fitxers de memòria nous`},help:{"v1-11pw0mp-9b":`Permisos dels fitxers nous DREAMS.md, MEMORY.md i dels informes de memory/dreaming de memory-core: "0600", "0620", "0640" o "0660". Si no es defineix, es manté exactament 0600; els modes configurats respecten la umask de l'amfitrió que escriu els fitxers. Els fitxers existents, la memòria diària, el corpus de sessions i l'estat privat no es modifiquen. Els permisos per travessar directoris i les ACL predeterminades s'han de configurar per separat.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Llista d'agents`},help:{"v1-1e0blk1-5i":`Llista explícita dels agents configurats amb identificadors i personalitzacions opcionals del model, les eines, la identitat i l'espai de treball. Manteniu els identificadors estables al llarg del temps perquè les vinculacions, les aprovacions i l'encaminament de sessions siguin coherents.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Entorn d'execució antic de l'agent`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`Identificador de l'entorn d'execució antic de l'agent`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Màxim de caràcters d'inicialització de l'agent`},help:{"v1-rsf1es-4j":`Valor específic per agent que substitueix el màxim de caràcters de cada fitxer d'inicialització de l'espai de treball injectat a les instruccions de sistema d'aquest agent. Ometeu-lo per heretar agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Màxim total de caràcters d'inicialització de l'agent`},help:{"v1-1bal68p-4y":`Sobreescriptura per agent del nombre màxim total de caràcters de tots els fitxers d'inicialització de l'espai de treball injectats a la instrucció de sistema d'aquest agent. Ometeu-la per heretar agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2Ecompaction":{label:{"v1-1kqcx8z-g":`Compactació de l'agent`},help:{"v1-ioyi1g-2o":`Valors específics per agent que substitueixen la configuració de compactació del costat del client. Els paràmetres omesos s'hereten d'agents.defaults.compaction.`}},"agents%2Eentries%2E*%2Ecompaction%2EmaxSummaryChars":{label:{"v1-1vend8r-13":`Màxim de caràcters del resum de compactació de l'agent`},help:{"v1-1fwu60v-58":`Límit de caràcters del resum persistent del costat del client per agent (1000–200000), que substitueix agents.defaults.compaction.maxSummaryChars. El límit de tòkens del model actiu pot requerir un resum més curt.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Injecció de context de l'agent`},help:{"v1-1j68ys8-50":`Sobreescriptura per agent de la injecció de fitxers d'inicialització de l'espai de treball a l'entorn d'execució integrat. Ometeu-la per heretar agents.defaults.contextInjection. No controla la preparació d'instruccions mitjançant la CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Límits de context de l'agent`},help:{"v1-f1qxq8-3c":`Sobreescriptures opcionals per agent dels paràmetres específics del pressupost de context. Els camps omesos hereten agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Màxim de caràcters de memory_get de l'agent`},help:{"v1-12hlmsv-1v":`Sobreescriptura per agent del pressupost màxim de caràcters predeterminat de memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Màxim de caràcters de l'agent després de la compactació`},help:{"v1-15s0npd-1w":`Sobreescriptura per agent del pressupost de l'extracte d'AGENTS.md després de la compactació.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Directori de treball de l'agent`},help:{"v1-mv43ak-6a":`Directori de treball per a les execucions de resposta d'aquest agent. Sobreescriu agents.defaults.cwd, però no el cwd establert en crear la sessió; els fitxers d'inicialització i de memòria es mantenen a l'espai de treball. Admet ~ i camins relatius; un cwd diferent requereix una execució fora de l'entorn aïllat.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Model de decisió de l'agent`},help:{"v1-1mih8bf-3j":`Model de decisió per agent. Si no es defineix, hereta agents.defaults.decisionModel; una cadena buida desactiva les crides de decisió per a aquest agent.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`OpenClaw integrat de l’agent`},help:{"v1-uoomza-4b":`Ajustos opcionals per agent que substitueixen els valors de l’OpenClaw integrat. Feu-los servir per activar un comportament d’execució més estricte de GPT-5 per a agents concrets sense canviar el valor predeterminat global.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Contracte d’execució de l’OpenClaw integrat de l’agent`},help:{"v1-1d1jaoi-7k":`Ajust opcional per agent que substitueix el contracte d’execució de l’OpenClaw integrat. Establiu "strict-agentic" per activar el seguiment estructurat del pla i la recuperació no visible de torns per a aquest agent en execucions compatibles de la família GPT-5 d’OpenAI/OpenAI Codex, o "default" per heretar el comportament estàndard del motor d’execució.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Opcions experimentals de l’agent`},help:{"v1-1r06jov-2a":`Opcions experimentals per agent. Els camps omesos hereten agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Mode lleuger de model local de l’agent`},help:{"v1-5o3tgx-58":`Ajust per agent del mode lleuger de model local per resoldre problemes. Activeu-lo només quan restringir les eines opcionals resolgui una fallada demostrada del model, sense reduir les eines de tots els agents.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Valor predeterminat del mode ràpid de l’agent`},help:{"v1-ev6028-41":`Valor predeterminat opcional per agent per al mode ràpid ("auto", "ultrafast", true o false). S’aplica quan no s’ha definit cap ajust de mode ràpid per missatge o sessió que el substitueixi.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Avatar d'identitat`},help:{"v1-pzp9gr-1t":`Avatar de l'agent (camí relatiu a l'espai de treball, URL http(s) o URI de dades).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Política de models de l'agent`},help:{"v1-17d5je8-2r":`Política de substitució de models per agent. Una llista explícita de models permesos substitueix la política predeterminada d'aquest agent.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Models permesos de l'agent`},help:{"v1-1enipb-5w":`Referències de model permeses per substituir el model predeterminat d'aquest agent. Accepta àlies, referències completes "provider/model" i prefixos amb comodins al final, com ara "provider/*", "provider/namespace/*" o "provider/family-*"; si és buit, permet qualsevol model.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Substitucions de models de l'agent`},help:{"v1-nld1vq-1v":`Substitucions del catàleg de models per agent, amb identificadors complets provider/model com a claus.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Entorn d'execució del model de l'agent`},help:{"v1-7b59y-3s":`Política opcional de l'entorn d'execució per model per a aquest agent. Feu-la servir per a excepcions de models específiques de l'agent en lloc d'establir un entorn d'execució per a tot l'agent.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`ID de l'entorn d'execució del model de l'agent`},help:{"v1-1ckfc39-46":`Identificador de l'entorn d'execució del model per agent: "openclaw", "auto", un identificador registrat d'adaptador de connector, com ara "codex", o un àlies de backend CLI compatible, com ara "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Mode de codi`},help:{"v1-91zu7f-7m":`Mode de codi d'OpenClaw per a aquest agent i aquest proveïdor/model concret: Activat en força l'activació, Desactivat el desactiva i Per defecte hereta la configuració d'activació de l'agent, després la sobreescriptura compartida del model i, finalment, tools.codeMode.enabled. Això no canvia l'entorn d'execució seleccionat ni el mode de codi natiu de Codex.`}},"agents%2Eentries%2E*%2EnativeRuntimeConsent":{label:{"v1-r2vkr2-11":`Permisos recordats de l'entorn d'execució natiu`},help:{"v1-1uktqfm-79":`Identificadors dels sistemes d'execució autoritzats a utilitzar els seus permisos natius per a aquest agent. Els xats nous utilitzen accés complet amb l'entorn aïllat desactivat. Elimineu un identificador per revocar immediatament el consentiment recordat; el consentiment explícit de cada xat no canvia. Els límits obligatoris de l'entorn aïllat i de l'espai de treball continuen aplicant-se.`}},"agents%2Eentries%2E*%2EnewSessionPermissionMode":{help:{"v1-15v8f6l-5p":`Mode de permisos desat en les sessions noves d'operador assistides i amb perfil quan no es proporciona cap mode explícit. No modifica les sessions existents, bifurcades, delegades o autònomes. El mode complet continua requerint operator.admin.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Raonament per defecte de l'agent`},help:{"v1-13ly0xf-3m":`Visibilitat del raonament per defecte opcional per agent (on|off|stream). S'aplica quan no s'ha establert cap sobreescriptura del raonament per missatge o sessió.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Entorn d'execució de l'agent`},help:{"v1-avjgkf-3l":`Descriptor opcional de l'entorn d'execució d'aquest agent. Utilitzeu embedded per a l'execució per defecte d'OpenClaw o acp per als valors per defecte d'un sistema d'execució ACP extern.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Entorn d'execució ACP de l'agent`},help:{"v1-91zvdk-3i":`Valors per defecte de l'entorn d'execució ACP d'aquest agent quan runtime.type=acp. Les sobreescriptures d'ACP a nivell de vinculació continuen tenint prioritat en cada conversa.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agent del sistema d'execució ACP de l'agent`},help:{"v1-1pm98vp-37":`Identificador opcional de l'agent del sistema d'execució ACP que s'utilitzarà per a aquest agent d'OpenClaw (per exemple, codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Motor ACP de l'agent`},help:{"v1-1u3cdsg-2n":`Substitució opcional del motor ACP per a les sessions ACP d'aquest agent (si no s'especifica, s'utilitza el valor global acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Directori de treball ACP de l'agent`},help:{"v1-d9p9rf-1t":`Directori de treball predeterminat opcional per a les sessions ACP d'aquest agent.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Mode ACP de l'agent`},help:{"v1-yatuk4-21":`Mode de sessió ACP predeterminat opcional per a aquest agent (persistent o oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Tipus d'entorn d'execució de l'agent`},help:{"v1-139fbk6-2r":`Tipus d'entorn d'execució per a aquest agent: "embedded" (entorn d'execució predeterminat d'OpenClaw) o "acp" (valors predeterminats de l'entorn ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Interval d'origen CDP del navegador aïllat de l'agent`},help:{"v1-1q1qyso-1d":`Substitució per agent de la llista de rangs CIDR d'origen permesos per a CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Xarxa del navegador aïllat de l'agent`},help:{"v1-13bdfww-4c":`Substitució per agent de la xarxa Docker del navegador aïllat. Utilitzeu una xarxa de pont; "none" no és compatible perquè el control del navegador requereix ports CDP publicats.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Permet unir-se a l'espai de noms d'un contenidor Docker a l'entorn aïllat de l'agent`},help:{"v1-1xtnseb-2i":`Ajust específic per agent PERILLÓS que permet unir-se a espais de noms de contenidors en el mode de xarxa Docker de l'entorn aïllat.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`GPU de Docker de l'entorn aïllat de l'agent`},help:{"v1-1kek1n2-1t":`Ajust específic per agent de l'accés directe a la GPU de Docker per als contenidors de l'entorn aïllat.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Filtre d'habilitats de l'agent`},help:{"v1-igchue-6v":`Llista opcional d'habilitats permeses per a aquest agent. Si s'omet, l'agent hereta agents.defaults.skills quan està definit; en cas contrari, les habilitats continuen sense restriccions. Establiu [] per no permetre cap habilitat. Una llista explícita substitueix completament els valors predeterminats heretats en lloc de combinar-s'hi.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Límits d'habilitats de l'agent`},help:{"v1-1sv10v9-4y":`Ajustos opcionals específics per agent dels límits de recursos del subsistema d'habilitats. Utilitzeu-los quan un agent necessiti un límit diferent per al prompt d'habilitats sense introduir una segona via genèrica de límits de context.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Màxim de caràcters del prompt d'habilitats de l'agent`},help:{"v1-dys63y-52":`Ajust específic per agent del límit de caràcters del prompt d'habilitats. Amplia la via existent skills.limits.maxSkillsPromptChars en lloc de gestionar el mateix límit a través de contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegateToolsTo":{label:{"v1-bycm06-m":`Destinataris de les eines delegades`},help:{"v1-y7q6z7-d6":`Agents de destinació natius configurats específicament que poden ometre tools.deny d’aquest agent sol·licitant en iniciar-se. Requereix allowAgents de manera independent. Les transferències basades només en denegacions conserven totes les restriccions no locals; els perfils inicials o les llistes de permesos restrictius, o els transports no compatibles, rebutgen la transferència en lloc d’ampliar els permisos. Els auxiliars natius amb la mateixa destinació conserven els seus propis límits addicionals. Les sol·licituds restringides per remitent i les sol·licituds ACP no utilitzen mai aquesta autorització. La revocació restaura la instantània original del sol·licitant.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Mode de delegació de subagents`},help:{"v1-1rkgh6p-4s":`Valor específic per agent que substitueix la intensitat de delegació de subagents. Ometeu-lo per utilitzar "prefer" a la sessió principal d’aquest agent i "suggest" a la resta; els valors explícits "prefer" o "suggest" sempre tenen prioritat.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Nivell de raonament predeterminat de l’agent`},help:{"v1-173q7vy-43":`Nivell de raonament predeterminat opcional per agent. Substitueix agents.defaults.thinkingDefault per a aquest agent quan no s’ha establert cap valor específic per missatge o sessió.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent":{label:{"v1-q7r7ya-o":`Missatgeria de sortida de l’agent`},help:{"v1-xo2o9d-5d":`Política de missatgeria de l’agent només de sortida. Les destinacions d’enviament explícites no concedeixen permisos de lectura de sessions ni accés a l’estat, i continuen subjectes a les restriccions globals de participació entre agents i de l’entorn aïllat.`}},"agents%2Eentries%2E*%2Etools%2EagentToAgent%2Esend":{label:{"v1-1lxwft1-w":`Llista de destinacions d’enviament permeses de l’agent`},help:{"v1-tfolqu-ar":`Identificadors d'agent o patrons * amb els quals aquest agent pot contactar mitjançant sessions_send, fins i tot amb tools.sessions.visibility restringit. Si s'omet, hereta la visibilitat; [] denega els enviaments ordinaris entre agents. Els límits globals de tools.agentToAgent i de l'entorn aïllat continuen aplicant-se. No concedeix accés a llistes, historial, cerca, estat ni seguiment; les respostes pertanyen només al torn enviat. L'accés a les sessions filles propietat del sol·licitant no canvia.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Addicions a la llista d'eines permeses de l'agent`},help:{"v1-1550ui9-46":`Llista additiva d'eines permeses per agent, a més de les polítiques globals i de perfil. Manteniu-la restringida per evitar una ampliació accidental dels privilegis dels agents especialitzats.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Política d'eines de l'agent per proveïdor`},help:{"v1-mthxv9-4t":`Substitucions de la política d'eines específiques de cada proveïdor per agent, per controlar les capacitats dins l'àmbit del canal. Feu-les servir quan un agent necessiti restriccions més estrictes per a un proveïdor que per als altres.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Mode de codi de l'agent`},help:{"v1-118t8u5-65":`Opcions del mode de codi per agent. Un valor explícit d'enabled substitueix els valors d'activació predeterminats del model compartit i els globals; una substitució de codeMode del model específica de l'agent té prioritat. Les altres opcions es combinen amb tools.codeMode sense canviar l'activació.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Temps d'espera d'execució de l'agent (segons)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Substitució de la identitat de GitHub CLI de l'agent`},help:{"v1-mjwdh4-38":`Substitució completa de la identitat gestionada de GitHub CLI i de l'autor de Git per a aquest agent. Ometeu-la per heretar la identitat del sistema.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EallowInSandbox":{label:{"v1-1rxew98-12":`Permet la identitat de GitHub de l'agent a l'entorn aïllat`},help:{"v1-17rsbdj-6g":`Permet les credencials gestionades de GitHub i l'autor de Git d'aquest agent dins del seu propi entorn aïllat de Docker o Podman (per defecte: false). L'àmbit compartit rebutja la injecció d'identitat; els altres sistemes de rerefons rebutgen l'aprovisionament. L'auditoria de seguretat emet un avís mentre aquesta opció està activada.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Correu electrònic de l'autor de Git de l'agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Nom de l'autor de Git de l'agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Tipus de credencial de GitHub de l'agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Versió del perfil de GitHub de l'agent`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Llista d'accions de missatgeria permeses de l'agent`},help:{"v1-1g5gov3-67":`Llista d'accions de missatgeria permeses per agent per a l'eina message. Establiu una llista mínima com ara ["send"] per als agents públics en entorns aïllats perquè les accions de lectura, edició, supressió, reacció i altres accions de missatgeria específiques del proveïdor continuïn ocultes i bloquejades.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Missatgeria de l'agent entre contextos (entre proveïdors)`},help:{"v1-pehesn-49":`Valor específic per agent per a l'enviament entre proveïdors. Hereta la configuració global (per defecte: true). Establiu-lo a false per bloquejar la missatgeria entre proveïdors per a aquest agent.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Missatgeria de l'agent entre contextos (mateix proveïdor)`},help:{"v1-s9u09h-4t":`Restricció de missatgeria per agent per a l'enviament a altres converses del mateix proveïdor. Establiu tant aquesta opció com allowAcrossProviders a false per als agents públics limitats a la conversa actual.`}},"agents%2Eentries%2E*%2Etools%2Eopenclaw":{label:{"v1-1fc612h-p":`Delegació a OpenClaw de l'agent`},help:{"v1-wjtvl7-25":`Política d'aprovació per agent dels canvis delegats a l'agent de sistema OpenClaw.`}},"agents%2Eentries%2E*%2Etools%2Eopenclaw%2EautoApproveChanges":{label:{"v1-lxqapd-10":`Aprovació automàtica dels canvis delegats de l'agent`},help:{"v1-1ok03hg-a1":`Substitueix tools.openclaw.autoApproveChanges per a aquest agent. El valor true és una autorització permanent d'administració delegada que pot habilitar l'execució de codi a l'amfitrió de Gateway; el valor false requereix una aprovació individual, fins i tot amb accés complet. Si s'omet, s'hereta la configuració global i, després, l'autoritat efectiva de l'execució sol·licitant. Les restriccions del sistema de fitxers, de l'entorn aïllat i de les operacions continuen aplicant-se.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Perfil d'eines de l'agent`},help:{"v1-1du76ix-57":`Substitució per agent de la selecció del perfil d'eines quan un agent necessita un conjunt de capacitats de base diferent. Feu-ne un ús moderat perquè les diferències de polítiques entre agents siguin intencionades i es puguin revisar.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Eixam de l'agent`},help:{"v1-420ljs-2c":`Substitució de la configuració d'eixam per agent. Els valors es combinen amb la configuració de nivell superior tools.swarm i hi tenen prioritat.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Mode d'escriptura de l'agent`},help:{"v1-oxir52-2e":`Substitueix la política predeterminada d'inici de l'indicador d'escriptura per a un agent sense modificar els altres agents.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Model d'utilitat de l'agent`},help:{"v1-ccb32g-5u":`Model d'utilitat per agent, com a cadena o { primary, fallbacks }. Si no s'estableix, hereta agents.defaults.utilityModel. Un primary explícit sense fallbacks elimina les alternatives heretades; una cadena buida desactiva l'encaminament d'utilitat.`}},"agents%2Eentries%2E*%2EutilityModel%2Efallbacks":{label:{"v1-17pzdxs-t":`Models alternatius d'utilitat de l'agent`},help:{"v1-v419a0-2k":`Models alternatius d'utilitat ordenats per agent. Una llista buida elimina les alternatives d'utilitat heretades.`}},"agents%2Eentries%2E*%2EutilityModel%2Eprimary":{label:{"v1-lbcmz5-r":`Model principal d'utilitat de l'agent`},help:{"v1-1d8oent-1z":`Model d'utilitat principal per agent. Ometeu-lo per heretar el model d'utilitat principal predeterminat.`}},"agents%2Eentries%2E*%2EworkspaceFileMode":{label:{"v1-13trwkt-k":`Mode dels fitxers nous de memòria`},help:{"v1-8mxas6-56":`Substitueix agents.defaults.workspaceFileMode per a les sortides de memòria llegibles per humans que aquest agent creï. Es conserven els permisos dels fitxers existents; l'amfitrió que escriu aplica la seva pròpia umask.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generació de titularitat dels agents`},help:{"v1-1g8mxd3-8u":`Marcador persistent de generació de titularitat multiagent. "explicit" significa que els canals d'entorn, les consultes a l'agent del sistema, Talk, cron i les operacions directes de CLI han de determinar un titular específic de la superfície o aturar-se quan no se'n pugui identificar cap. OpenClaw estableix aquest marcador automàticament en crear o migrar una flota; ometeu-lo si només hi ha un agent.`}},approvals:{label:{"v1-1m405m7-9":`Aprovacions`},help:{"v1-4y3in-5w":`Controls d'encaminament d'aprovacions per reenviar sol·licituds d'aprovació d'exec i de connectors a destinacions de xat fora de la sessió d'origen. Manteniu-los desactivats tret que els operadors necessitin visibilitat explícita de les aprovacions per un canal alternatiu.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Reenviament d'aprovacions d'exec`},help:{"v1-1r2mozk-5v":`Agrupa el comportament de reenviament d'aprovacions d'exec, incloent-hi l'activació, el mode d'encaminament, els filtres i les destinacions explícites. Configureu-lo aquí quan les sol·licituds d'aprovació hagin d'arribar als canals operatius i no només al fil d'origen.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Filtre d'agents per a aprovacions`},help:{"v1-xip9a-4k":`Llista opcional d'identificadors d'agents autoritzats a rebre aprovacions reenviades, per exemple \`["primary", "ops-agent"]\`. Utilitzeu-la per evitar enviar notificacions als canals sobre agents no relacionats.`}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Reenvia les aprovacions d'execució`},help:{"v1-1t0whe8-5s":`Activa el reenviament de les sol·licituds d'aprovació d'execució a les destinacions de lliurament configurades (per defecte: false). Manteniu-lo desactivat en configuracions de baix risc i activeu-lo només quan les persones responsables de les aprovacions necessitin sol·licituds visibles al canal.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Mode de reenviament d'aprovacions`},help:{"v1-1dedfo4-69":`Controla on s'envien les sol·licituds d'aprovació: "session" utilitza el xat d'origen, "targets" utilitza les destinacions configurades i "both" les envia per totes dues vies. Utilitzeu "session" com a opció de base i amplieu-la només quan el flux de treball operatiu requereixi redundància.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Filtre de sessions per a les aprovacions`},help:{"v1-smeg8e-5u":`Filtres opcionals de claus de sessió que es comparen com a subcadenes o patrons d'expressió regular, per exemple \`["discord:", "^agent:ops:"]\`. Utilitzeu patrons restrictius perquè només es reenviïn els contextos d'aprovació previstos a les destinacions compartides.`}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Destinacions de reenviament d'aprovacions`},help:{"v1-17ah848-5u":`Destinacions de lliurament explícites que s'utilitzen quan el mode de reenviament inclou targets, cadascuna amb detalls del canal i de la destinació. Manteniu les llistes de destinacions segons el principi de privilegi mínim i valideu cada destinació abans d'activar un reenviament ampli.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`ID del compte de destinació de les aprovacions`},help:{"v1-16zopng-5e":`Selector de compte opcional per a configuracions de canals amb diversos comptes quan les aprovacions s'han d'encaminar a través del context d'un compte específic. Utilitzeu-lo només quan el canal de destinació tingui diverses identitats configurades.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Canal de destinació de les aprovacions`},help:{"v1-ji1igl-59":`ID del canal o proveïdor utilitzat per enviar aprovacions reenviades, com ara discord, slack o un ID de canal d'un connector. Utilitzeu només ID de canal vàlids perquè les aprovacions no fallin silenciosament a causa de rutes desconegudes.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`ID del fil de destinació de les aprovacions`},help:{"v1-1axynw7-59":`Fil o tema de destinació opcional per als canals que admeten l'enviament d'aprovacions reenviades en fils. Utilitzeu-lo per mantenir el trànsit d'aprovacions dins dels fils operatius en lloc dels canals principals.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Destinació de les aprovacions`},help:{"v1-1ijng7e-5n":`Identificador de destinació dins del canal de destinació (ID del canal, ID de l'usuari o arrel del fil, segons el proveïdor). Verifiqueu-ne la semàntica per a cada proveïdor, ja que el format de destinació varia entre les integracions de canals.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Reenviament d'aprovacions de connectors`},help:{"v1-1m6pzxv-6b":`Agrupa el comportament del reenviament d'aprovacions de connectors, inclosos l'activació, el mode d'encaminament, els filtres i les destinacions explícites. És independent del reenviament d'aprovacions d'execució. Configureu-lo aquí quan les sol·licituds d'aprovació de connectors hagin d'arribar als canals operatius.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Filtre d'agents per a les aprovacions de connectors`},help:{"v1-b3test-4y":`Llista opcional d'ID d'agents autoritzats per al reenviament d'aprovacions de connectors, per exemple \`["primary", "ops-agent"]\`. Utilitzeu-la per seleccionar de quins agents es reenvien les sol·licituds d'aprovació.`}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Reenvia les aprovacions de connectors`},help:{"v1-1ntctaf-3v":`Habilita el reenviament de les sol·licituds d'aprovació dels connectors a les destinacions de lliurament configurades (valor per defecte: false). És independent d'approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Mode de reenviament d'aprovacions dels connectors`},help:{"v1-1h62vy4-3z":`Controla on s'envien les sol·licituds d'aprovació dels connectors: "session" utilitza el xat d'origen, "targets" utilitza les destinacions configurades i "both" les envia per totes dues vies.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Filtre de sessions per a les aprovacions dels connectors`},help:{"v1-1eppxmt-57":`Filtres opcionals de claus de sessió que es comparen com a subcadenes o patrons d'expressions regulars, per exemple \`["discord:", "^agent:ops:"]\`. Utilitzeu patrons específics perquè només es reenviïn els contextos d'aprovació previstos.`}},"approvals%2Eplugin%2Eslack":{label:{"v1-o7dlxi-m":`Revisors dels connectors a Slack`},help:{"v1-1svd0ag-4x":`Política de revisors de Slack per a les aprovacions dels connectors. Ometeu la llista d'aprovadors per defecte per conservar l'autorització allowFrom/defaultTo del compte; establiu-la a [] per denegar per defecte les decisions de Slack.`}},"approvals%2Eplugin%2Eslack%2Eapprovers":{label:{"v1-r39jnl-u":`Revisors per defecte dels connectors a Slack`},help:{"v1-auy576-5v":`Revisors per defecte dels connectors a Slack, indicats com a identificadors d'usuari U/W sense modificar del compte de Slack seleccionat, o com a valors team:<team-id>:user:<user-id> qualificats per espai de treball. Les llistes de connectors i eines substitueixen aquesta llista per a les seves pròpies sol·licituds.`}},"approvals%2Eplugin%2Eslack%2Eplugins":{label:{"v1-13wg4dk-v":`Excepcions de revisors dels connectors a Slack`},help:{"v1-16kb0vj-2r":`Excepcions de revisors amb l'identificador del connector d'eina nativa seleccionat com a clau. Les claus d'eina codifiquen el nom de l'eina sense modificar.`}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Destinacions de reenviament d'aprovacions dels connectors`},help:{"v1-o92qze-3k":`Destinacions de lliurament explícites que s'utilitzen quan el mode de reenviament d'aprovacions de connectors inclou destinacions, cadascuna amb detalls del canal i de la destinació.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`ID del compte de destinació de les aprovacions de connectors`},help:{"v1-1wf3lqn-3j":`Selector de compte opcional per a configuracions de canals amb diversos comptes quan les aprovacions de connectors s'han d'encaminar a través del context d'un compte específic.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Canal de destinació de les aprovacions de connectors`},help:{"v1-1mzhzi9-34":`ID del canal o proveïdor utilitzat per lliurar les aprovacions de connectors reenviades, com ara discord, slack o un ID de canal d'un connector.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`ID del fil de destinació de les aprovacions de connectors`},help:{"v1-1scaw9c-2v":`Fil o tema de destinació opcional per als canals que admeten el lliurament en fils de les aprovacions de connectors reenviades.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Destinació de les aprovacions de connectors`},help:{"v1-sh5te1-31":`Identificador de destinació dins del canal de destinació (ID del canal, ID de l'usuari o arrel del fil, segons el proveïdor).`}},attachments:{label:{"v1-8925gh-b":`Fitxers adjunts`},help:{"v1-1xvgkss-40":`Comportament de retenció de nivell superior compartit entre els proveïdors i les eines que desen contingut multimèdia de manera persistent. Utilitzeu ttlHours quan calgui limitar el temps de conservació del contingut multimèdia emmagatzemat temporalment.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`TTL de retenció dels fitxers adjunts (hores)`},help:{"v1-r7enyq-98":`Període de retenció opcional en hores per als fitxers multimèdia desats que gestiona la neteja general basada en mtime. Deixeu-lo sense definir per desactivar aquesta neteja, o establiu valors com ara 24 (1 dia) o 168 (7 dies) per eliminar periòdicament els fitxers multimèdia preparats més antics. Els fitxers multimèdia de sortida gestionats (adjunts generats pel xat) en queden exclosos i segueixen la seva pròpia política de retenció, basada en SQLite i en el context del xat.`}},audio:{label:{"v1-11wczsp-5":`Àudio`}},auth:{label:{"v1-5xz433-4":`Autenticació`},help:{"v1-1eu3aud-5c":`Arrel dels perfils d'autenticació utilitzada per a les credencials de proveïdor amb múltiples perfils i l'ordre de commutació per error basat en períodes d'espera. Manteniu els perfils mínims i explícits perquè el comportament de la commutació automàtica per error es pugui auditar.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Ordre dels perfils d'autenticació`},help:{"v1-1x6kknp-1w":`Identificadors ordenats dels perfils d'autenticació per proveïdor (utilitzats per a la commutació automàtica per error).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Perfils d'autenticació`},help:{"v1-kzoqcn-1j":`Perfils d'autenticació amb nom (proveïdor + mode + correu electrònic opcional).`}},bindings:{label:{"v1-1hcih9f-8":`Vinculacions`},help:{"v1-y7hrzb-4i":`Regles de vinculació de nivell superior per a l'encaminament i l'assignació persistent de converses ACP. Utilitzeu type=route per a l'encaminament normal i type=acp per a les vinculacions persistents de l'entorn d'execució ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Sobreescriptures ACP de la vinculació`},help:{"v1-1t4lisi-44":`Sobreescriptures ACP opcionals per vinculació per a bindings[].type=acp. Aquesta capa sobreescriu els valors predeterminats d'agents.entries.*.runtime.acp per a la conversa coincident.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Motor ACP de la vinculació`},help:{"v1-rsrbkp-2x":`Sobreescriptura del motor ACP per a aquesta vinculació (si no es defineix, s'utilitza el motor ACP de l'entorn d'execució de l'agent i, després, el valor global acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Directori de treball de la vinculació ACP`},help:{"v1-ngpkj0-1y":`Directori de treball alternatiu per a les sessions ACP creades a partir d'aquesta vinculació.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Etiqueta de la vinculació ACP`},help:{"v1-azce82-23":`Etiqueta fàcil d'entendre per a l'estat i els diagnòstics d'ACP en aquesta conversa vinculada.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Mode de la vinculació ACP`},help:{"v1-cgq8xv-1v":`Mode de sessió ACP alternatiu per a aquesta vinculació (persistent o oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`ID de l'agent de la vinculació`},help:{"v1-17ra0cl-4m":`ID de l'agent de destinació que rep el trànsit quan es compleix la regla de coincidència de la vinculació corresponent. Utilitzeu només ID d'agents configurats vàlids perquè l'encaminament no falli durant l'execució.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Regla de coincidència de la vinculació`},help:{"v1-sc1w2e-51":`Objecte de regla de coincidència per decidir quan s'aplica una vinculació, incloent-hi el canal i les restriccions opcionals de compte o d'interlocutor. Definiu regles precises per evitar que un agent assumeixi accidentalment el control en altres contextos.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`ID del compte de la vinculació`},help:{"v1-1d209g7-56":`Selector de compte opcional per a configuracions de canal amb diversos comptes, perquè la vinculació s'apliqui només a una identitat. Utilitzeu-lo quan la ruta s'hagi de limitar a un compte i deixeu-lo sense definir en cas contrari.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Canal de la vinculació`},help:{"v1-d22m5-54":"Identificador del canal o proveïdor al qual s'aplica aquesta vinculació, com ara `telegram`, `discord` o un ID de canal d'un connector. Utilitzeu exactament la clau del canal configurada perquè l'avaluació de la vinculació funcioni de manera fiable."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`ID del servidor de la vinculació`},help:{"v1-jzzfj1-4x":`Restricció opcional d'ID de comunitat/servidor de tipus Discord per avaluar les vinculacions en desplegaments amb diversos servidors. Utilitzeu-la quan els mateixos identificadors d'interlocutor puguin aparèixer en comunitats diferents.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Coincidència d'interlocutor de la vinculació`},help:{"v1-gcjxff-4i":`Criteri opcional de coincidència d'interlocutor per a converses específiques, que inclou el tipus i l'ID de l'interlocutor. Utilitzeu-lo quan només s'hagi d'assignar a un agent una única destinació directa, de grup o de canal.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`ID de l'interlocutor de la vinculació`},help:{"v1-86fbh7-4b":`Identificador de conversa utilitzat per a la coincidència d'interlocutor, com ara un ID de xat, de canal o de grup del proveïdor. Manteniu-lo exacte per evitar que no es trobin coincidències sense cap avís.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Tipus d'interlocutor de la vinculació`},help:{"v1-uufscp-4x":`Tipus de conversa de l'interlocutor: "direct", "group", "channel" o l'antic "dm" (àlies obsolet de direct). Preferiu "direct" per a les configuracions noves i manteniu kind coherent amb la semàntica del canal.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Rols de la vinculació`},help:{"v1-6s891m-4k":`Llista opcional de filtres basats en rols que utilitzen els proveïdors que associen rols al context del xat. Utilitzeu-la per encaminar el trànsit de rols privilegiats o operatius cap a agents especialitzats.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`ID de l'equip de la vinculació`},help:{"v1-hh9ps2-48":`Restricció opcional d'ID d'equip/espai de treball que utilitzen els proveïdors que delimiten els xats per equips. Afegiu-la quan necessiteu que les vinculacions quedin aïllades en el context d'un únic espai de treball.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Sessió de la vinculació`},help:{"v1-x325l2-4v":`Sobreescriptures opcionals de la sessió de la ruta per a les converses que coincideixen amb aquesta vinculació. Utilitzeu-les quan una ruta específica hagi de mantenir el mateix agent però aïllar la continuïtat de la sessió d'una manera diferent.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Àmbit dels missatges directes de la sessió de vinculació`},help:{"v1-10sg3xw-4s":`Sobreescriptura opcional de l'àmbit de la sessió de missatges directes per a aquesta vinculació de ruta. Per exemple, manteniu el valor global session.dmScope="main" mentre utilitzeu "per-account-channel-peer" per a interlocutors directes seleccionats.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Àmbit de grup de la sessió de vinculació`},help:{"v1-1ys2u7k-6n":`Sobreescriptura opcional de l'àmbit de la sessió de grup/canal per a aquesta vinculació de ruta. "per-group" manté les sales coincidents separades i supervisades en segon pla per la sessió principal de l'agent, independentment de dmScope; "main" integra el seu context a la sessió principal i no requereix supervisió.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Tipus de vinculació`},help:{"v1-172mhtk-3o":`Tipus de vinculació. Utilitzeu "route" (o ometeu-lo per a les entrades de ruta antigues) per a l'encaminament normal, i "acp" per a les vinculacions persistents de converses ACP.`}},broadcast:{label:{"v1-awqjh0-j":`Fils de grup d'agents`},help:{"v1-1tz72sr-6b":`Utilitzeu fils de grup d'agents per executar diversos agents configurats en una mateixa conversa entrant, cadascun en la seva pròpia sessió. Les entrades qualificades per canal admeten rondes de seguiment limitades; les matrius antigues d'interlocutors de WhatsApp mantenen el comportament d'una sola passada.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Participants i opcions del grup d'agents`},help:{"v1-1b63zmt-7d":`Utilitzeu un ID d'interlocutor qualificat pel canal (per exemple, "telegram:-100123") per configurar una matriu d'ID d'agents o un objecte estricte amb agents, mentionGating, maxRounds i maxTurns. Les entrades qualificades tenen prioritat sobre les claus d'interlocutor antigues de WhatsApp i permeten un màxim de 16 agents.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Participants del grup d'agents`},help:{"v1-g5o0ky-43":`ID dels agents participants d'agents.entries (màxim: 16). Cada participant utilitza la seva pròpia sessió per a aquest canal, compte, conversa i fil.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Màxim de rondes del grup d'agents`},help:{"v1-i6v4jc-5a":`Nombre màxim de rondes per missatge entrant, inclosa la ronda inicial (enter: 1–4, valor per defecte: 1). Les rondes de seguiment comparteixen respostes limitades dels altres participants amb l'autoria indicada i s'aturen quan tots els participants passen el torn.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Màxim de torns del grup d'agents`},help:{"v1-1kiv8dy-72":`Nombre màxim de torns dels participants per missatge entrant entre totes les rondes (enter: 1–32, valor per defecte: agents.length). Les places es reserven abans de l'enviament en paral·lel; això limita els torns dels agents, no els fragments físics dels missatges ni els enviaments de les eines. Els pressupostos no es reprenen després d'un reinici.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Selecció per menció del grup d'agents`},help:{"v1-uay9zu-5u":`Seleccioneu només els participants mencionats explícitament amb @ quan hi hagi alguna coincidència; altrament, executeu tots els participants (valor per defecte: true). Els noms sense @ o els emojis no seleccionen participants. Les llistes de permesos del canal i les regles d'admissió continuen aplicant-se.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Estratègia del grup d'agents`},help:{"v1-p4k9hu-4q":`Ordre d'execució dels participants: "parallel" (per defecte) executa els agents simultàniament, mentre que "sequential" els executa en l'ordre configurat. Cada ronda es completa abans que comenci la següent.`}},browser:{label:{"v1-13dzmen-7":`Navegador`},help:{"v1-5b74wi-5l":`Controls d'execució del navegador per a la connexió CDP local o remota, l'encaminament de perfils i el comportament de les captures de pantalla i les instantànies. Manteniu els valors per defecte tret que el vostre flux de treball d'automatització requereixi una configuració de transport del navegador personalitzada.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Permet la importació de perfils del sistema`},help:{"v1-1lsvlxw-5w":`Permet als equips macOS importar galetes d'un perfil local del sistema d'un navegador de la família Chrome a un perfil de navegador gestionat per OpenClaw. Desactiveu aquesta opció per impedir la importació de galetes de perfils de navegador i la sol·licitud de consentiment corresponent del Clauer de macOS.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Mode de només connexió del navegador`},help:{"v1-xaw7xm-4s":`Restringeix el mode del navegador a la connexió a instàncies existents, sense iniciar processos de navegador locals. Utilitzeu-lo quan totes les sessions del navegador estiguin gestionades externament per un proveïdor CDP remot.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`URL de CDP del navegador`},help:{"v1-2n72jb-65":`URL del punt de connexió CDP/DevTools utilitzat per connectar-se a una instància de navegador gestionada externament. Utilitzeu-la per a equips de navegador centralitzats, túnels o connexions a sessions existents, i manteniu l'accés a l'URL restringit a rutes de xarxa de confiança.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Perfil per defecte del navegador`},help:{"v1-a6xo96-52":`Nom del perfil de navegador seleccionat per defecte quan qui fa la crida no tria explícitament cap perfil. Utilitzeu un perfil estable amb pocs privilegis com a predeterminat per reduir l'ús accidental de l'estat entre contextos diferents.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Navegador activat`},help:{"v1-1m3zcs-5g":`Activa la integració de les funcions del navegador a la passarel·la perquè es puguin executar les eines del navegador i els fluxos de treball basats en CDP. Desactiveu-la quan no calgui automatitzar el navegador per reduir les funcions disponibles i les tasques d'inici.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Avaluació al navegador activada`},help:{"v1-1oa79mq-59":`Activa les eines auxiliars d'avaluació al navegador per avaluar scripts en temps d'execució quan sigui compatible. Manteniu aquesta opció desactivada tret que els vostres fluxos de treball requereixin funcions d'avaluació més enllà de les instantànies i la navegació.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Camí de l'executable del navegador`},help:{"v1-1dshhkn-6g":`Camí explícit de l'executable del navegador quan la detecció automàtica no és suficient per a l'entorn de l'amfitrió. Utilitzeu un camí absolut estable, o un camí que comenci amb ~ per al directori personal del sistema operatiu, perquè el comportament d'inici es mantingui previsible entre reinicis.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Relé de l'extensió del navegador`},help:{"v1-6ywlwr-4e":`Configuració de compatibilitat de l'autenticació del relé de l'extensió de Chrome. Manteniu el període de compatibilitat amb versions anteriors només mentre les extensions aparellades antigues o els clients CDP externs encara el necessitin.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Permet l'autenticació antiga del relé del navegador`},help:{"v1-pj2e90-63":`Accepta temporalment l'autenticació antiga del relé amb Bearer, Basic i subprotocol de testimoni. Valor per defecte: true durant un període de migració. Establiu-lo a false quan totes les extensions i tots els clients CDP externs utilitzin Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Mode sense interfície gràfica del navegador`},help:{"v1-hlkywz-56":`Els navegadors locals gestionats s'executen sense interfície gràfica per defecte. Establiu el valor a false per mostrar una finestra del navegador. Els navegadors de sessió existent, d'extensió, remots i de només connexió mantenen el mode seleccionat externament.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Mode sense aïllament del Navegador`},help:{"v1-slntux-4w":`Desactiva els indicadors d'aïllament de Chromium per als entorns on l'aïllament falla en temps d'execució. Manteniu aquesta opció desactivada sempre que sigui possible, ja que es redueixen les proteccions d'aïllament dels processos.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Perfils del Navegador`},help:{"v1-1x8lf05-51":`Mapa de connexions de perfils de navegador amb nom que s'utilitza per a l'encaminament explícit cap a ports o URL de CDP, amb metadades opcionals. Manteniu la coherència dels noms dels perfils i eviteu definicions superposades de punts de connexió.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Mode de només connexió del perfil del Navegador`},help:{"v1-2b5zs0-5a":`Configuració específica per perfil del mode de només connexió, que omet l'inici local del navegador i només es connecta a un punt de connexió CDP existent. És útil quan un perfil es gestiona externament, però els altres s'inicien localment.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Port CDP del perfil del Navegador`},help:{"v1-gx1yiq-49":`Port CDP local específic de cada perfil que s'utilitza per connectar-se a instàncies del navegador mitjançant un port en lloc d'un URL. Utilitzeu ports únics per a cada perfil per evitar conflictes de connexió.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`URL de CDP del perfil del Navegador`},help:{"v1-x491r0-64":`URL del punt de connexió CDP/DevTools específic de cada perfil que s'utilitza per a l'encaminament explícit del navegador segons el nom del perfil. Utilitzeu-lo per a amfitrions CDP remots, túnels o perfils de sessions existents que s'hagin de connectar a través d'un punt de connexió Chrome DevTools en execució.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Controlador del perfil del Navegador`},help:{"v1-17byyx6-5r":`Mode del controlador del navegador per perfil. Utilitzeu "openclaw" (o l'antic "clawd") per als perfils basats en CDP, "existing-session" per a la connexió mitjançant Chrome DevTools MCP o "extension" per al relé autenticat de l'extensió de Chrome.`}},"browser%2Eprofiles%2E*%2Eengine":{label:{"v1-w0e8eg-m":`Motor del perfil del navegador`},help:{"v1-1n0drki-ab":`Predefinició de capacitats del motor del navegador: "chromium" (per defecte) o els motors experimentals "lightpanda" / "kitesurf" per a la navegació externa mitjançant CDP. Els motors externs requereixen un cdpUrl ws/wss explícit dedicat a un únic perfil i attachOnly: true, no inicien mai cap navegador local i només exposen les operacions que admeten. Lightpanda no ofereix captures de pantalla; Kitesurf renderitza captures de pantalla experimentals.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Camí de l'executable del perfil del navegador`},help:{"v1-29azyv-4w":`Camí de l'executable del navegador per perfil per als perfils de navegador gestionats que s'inicien localment. Substitueix browser.executablePath i accepta camins que comencen amb ~ per indicar el directori personal del sistema operatiu.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Mode sense interfície gràfica del perfil del navegador`},help:{"v1-p4jtgv-4u":`Configuració específica per perfil del mode sense interfície gràfica per a les instàncies del navegador iniciades localment. Utilitzeu-la quan un perfil hagi de mantenir-se sense interfície gràfica sense forçar browser.headless per a tots els altres perfils.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Arguments de Chrome MCP del perfil del navegador`},help:{"v1-rc45ke-5g":`Arguments addicionals de Chrome DevTools MCP per perfil per a la connexió existing-session, com ara --no-usage-statistics. Els arguments del punt de connexió indicats aquí substitueixen la connexió automàtica integrada o la selecció de l'URL del navegador.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Ordre de Chrome MCP del perfil del navegador`},help:{"v1-1xpty8o-2h":`Ordre de Chrome DevTools MCP per perfil per connectar-se a una sessió existent. Per defecte és npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Directori de dades d'usuari del perfil del Navegador`},help:{"v1-5xvgex-9h":`Directori de dades d'usuari de Chromium per perfil per connectar-se a una sessió existent mitjançant Chrome DevTools MCP. Utilitzeu-lo per a Brave, Edge, Chromium o perfils de Chrome no predeterminats quan el mecanisme integrat de connexió automàtica triï el directori de dades del navegador incorrecte a l'amfitrió o al node de navegador seleccionat. Les rutes que comencen amb ~ s'expandeixen al directori d'inici del sistema operatiu.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Valors predeterminats de les instantànies del Navegador`},help:{"v1-v19wdy-4y":`Configuració predeterminada de captura d'instantànies que s'utilitza quan qui fa la crida no proporciona opcions explícites d'instantània. Ajusteu-la per obtenir un comportament de captura coherent entre canals i vies d'automatització.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Mode d'instantània del Navegador`},help:{"v1-joeyxp-5c":`Mode predeterminat d'extracció d'instantànies que controla com es transforma el contingut de la pàgina perquè l'agent el pugui utilitzar. Trieu el mode que equilibri la llegibilitat, la fidelitat i el consum de tokens per als vostres fluxos de treball.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Política SSRF del Navegador`},help:{"v1-1qbp9im-5e":`Configuració de les proteccions contra la falsificació de sol·licituds del costat del servidor per a les vies d'obtenció de dades del navegador o de la xarxa que podrien accedir a amfitrions interns. Manteniu els valors predeterminats restrictius en producció i permeteu l'accés només a les destinacions aprovades explícitament.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Noms d'amfitrió permesos del Navegador`},help:{"v1-1rng39-2k":`Noms d'amfitrió exactes o adreces IP literals permesos per les comprovacions de la política SSRF del navegador. Manteniu la llista al mínim.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Navegador: permet l'interval local únic d'IPv6`},help:{"v1-1glx5cy-2c":`Permet adreces locals úniques d'IPv6 (fc00::/7) en entorns de servidor intermediari amb IP fictícies de confiança.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Navegador: permet l'interval de proves de rendiment de l'RFC 2544`},help:{"v1-10ateu3-2i":`Permet les IP de l'interval de proves de rendiment de l'RFC 2544 (198.18.0.0/15) en entorns de servidor intermediari amb IP fictícies de confiança.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Navegador: noms d'amfitrió bloquejats`},help:{"v1-nug0we-6k":`Patrons de noms d'amfitrió denegats abans de la resolució DNS i de les regles de permís, fins i tot amb l'accés a la xarxa privada activat. Admet amfitrions exactes i "*.example.com" només per als subdominis; afegiu "example.com" per separat per bloquejar el domini arrel. Si és buit o no s'ha definit, no afegeix cap denegació.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Navegador: permet la xarxa privada de manera perillosa`},help:{"v1-17103pi-4m":`Permet accedir als intervals d'adreces de xarxa privada des de les eines del navegador. Per defecte, està desactivat si no s'ha definit; activeu-lo només per a destinacions de xarxa privada explícitament de confiança.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Navegador: neteja de pestanyes`},help:{"v1-1ctwaad-4y":`Política de neteja, en la mesura del possible, de les pestanyes del navegador obertes per sessions de l'agent principal. Manteniu-la activada per evitar que s'acumulin pestanyes obsoletes de l'entorn aïllat o del navegador gestionat en passarel·les que funcionen durant períodes llargs.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Navegador: neteja de pestanyes activada`},help:{"v1-4sv97p-3u":`Activa la neteja de les pestanyes del navegador supervisades que estan inactives a les sessions de l'agent principal. Desactiveu-la només quan les eines externes gestionin completament el cicle de vida de les pestanyes.`}},channels:{label:{"v1-1ju93md-8":`Canals`},help:{"v1-18k1gv4-50":`Configuracions dels proveïdors de canals i valors predeterminats compartits que controlen les polítiques d'accés i el comportament de cada interfície. Manteniu els valors predeterminats centralitzats i substituïu-los per a cada proveïdor només quan calgui.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Valors predeterminats dels canals`},help:{"v1-uz6veb-4p":`Comportament predeterminat dels canals que s'aplica a tots els proveïdors quan no s'ha definit una configuració específica per al proveïdor. Utilitzeu-lo per establir una política de base coherent abans d'ajustar-la per a cada proveïdor.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Protecció predeterminada contra bucles entre bots`},help:{"v1-1lpznyk-4w":`Configuració predeterminada de protecció contra bucles entre parelles per als proveïdors de canals que admeten proteccions contra bucles entre bots. Utilitzeu valors específics per a un proveïdor només quan un canal necessiti un límit diferent.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Segons de pausa predeterminats per als bucles entre bots`},help:{"v1-1yl5ird-2z":`Segons de pausa que s'apliquen a una parella després que superi el límit de bucles. El valor predeterminat per als canals compatibles és de 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Protecció contra bucles entre bots activada per defecte`},help:{"v1-3ruik-4r":`Activa per defecte la protecció contra bucles entre parelles als canals compatibles quan els missatges escrits per bots poden arribar al sistema de distribució. Els proveïdors poden desactivar la protecció si s'ignoren els bots.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Esdeveniments predeterminats de bucle entre bots per interval`},help:{"v1-1u0mdjc-41":`Nombre màxim d'esdeveniments que una parella d'emissor i receptor pot intercanviar dins de la finestra configurada abans que comenci la supressió. El valor per defecte per als canals compatibles és 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Durada per defecte de la finestra de bucle del bot en segons`},help:{"v1-12xpmen-2m":`Durada de la finestra lliscant en segons per als límits de bucle per parella. El valor per defecte per als canals compatibles és 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Visibilitat del context per defecte`},help:{"v1-1hze3g1-5o":`Visibilitat per defecte del context complementari per al contingut recuperat de cites, fils i historial: "all" (conserva tot el context), "allowlist" (només els emissors de la llista de permesos) o "allowlist_quote" (llista de permesos + conserva les cites explícites).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Política de grup per defecte`},help:{"v1-ntl9m4-4n":`Política de grup per defecte per a tots els canals: "open", "disabled" o "allowlist". Manteniu "allowlist" per a configuracions de producció més segures, tret que vulgueu permetre una participació àmplia als grups.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Mencions implícites per defecte`},help:{"v1-4gtdyv-48":`Política per defecte que determina si respondre al bot, citar-lo o participar en un fil on ha intervingut activa els canals de missatgeria compatibles sense una menció explícita.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Mencions implícites per defecte en citar el bot`},help:{"v1-va1u5v-2v":`Tracta les cites de missatges del bot com a mencions implícites per defecte. El valor per defecte és true per garantir la compatibilitat amb versions anteriors.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Mencions implícites per defecte en respostes al bot`},help:{"v1-lm44c3-39":`Tracta les respostes als missatges del mateix bot com a mencions implícites per defecte. El valor per defecte és true per mantenir la compatibilitat amb versions anteriors.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Mencions implícites per defecte per participació en fils`},help:{"v1-160205h-3o":`Tracta els missatges posteriors en fils on ha participat el bot com a mencions implícites per defecte. El valor per defecte és true per mantenir la compatibilitat amb versions anteriors.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Substitucions de model per canal`},help:{"v1-1b01spx-2p":`Assigna proveïdor -> identificador del canal / identificador de l'interlocutor del missatge directe -> substitució de model (els valors són provider/model o àlies).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Processos de treball al núvol`},help:{"v1-10carc4-5v":`Perfils de processos de treball al núvol d'activació voluntària per a entorns remots d'un sol ús. Quan s'omet aquesta secció o no conté cap perfil, la creació de processos de treball al núvol continua sense estar disponible i el comportament existent de l'estat de la passarel·la i dels nodes no canvia.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Escriptori del procés de treball al núvol (experimental)`},help:{"v1-sly85c-3k":`Activa la interfície experimental worker.desktop.observe i el tauler d’escriptori de l’aplicació web per als entorns de processos de treball al núvol amb capacitats d’escriptori.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Grup de processos de treball al núvol preparats`},help:{"v1-rw51o5-6b":`Límits dels processos de treball al núvol que es mantenen preparats per a sessions posteriors. Les reserves generen càrrecs de màquina en execució fins que el proveïdor completa la neteja; el seu venciment fix s'ajusta a la demanda real del projecte i a la política d'inactivitat existent del proveïdor.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Límit de reserva de treballadors al núvol preparats`},help:{"v1-1mpd1dt-7u":`Límit global de la Passarel·la per als treballadors al núvol preparats sense assignar en tots els projectes i perfils (per defecte: 4). Els treballadors en preparació i els recursos de reserva amb neteja pendent de confirmació compten per al límit. Establiu-lo a 0 per buidar les reserves sense assignar i desactivar-ne la reposició, tot mantenint la reutilització d'instantànies i les sessions actives.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Perfils de treballadors al núvol`},help:{"v1-eii67l-3j":`Perfils amb nom de treballadors al núvol. Cada perfil selecciona un proveïdor de treballadors registrat per un connector i conté la configuració pròpia del proveïdor.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Perfil de treballador al núvol`},help:{"v1-1v2w7jl-4u":`Un perfil de treballador al núvol seleccionat pel nom en crear un entorn. Deseu les credencials del proveïdor en referències compatibles en lloc d'incrustar dades secretes en aquest bloc.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Mètode d'instal·lació del treballador al núvol`},help:{"v1-blrtbf-74":`Mètode d'instal·lació del treballador: "bundle" (per defecte) transfereix la compilació instal·lada de la Passarel·la, identificada pel hash del contingut, i admet versions publicades, de desenvolupament i no publicades; "npm" instal·la la versió exacta de la Passarel·la i només està disponible quan aquesta versió s'ha publicat.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Proveïdor de treballadors al núvol`},help:{"v1-1p4s4c1-44":`Identificador del proveïdor de treballadors registrat per un connector. El connector configurat ha d'exposar aquest identificador perquè la Passarel·la pugui aprovisionar entorns a partir del perfil.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Objectiu de reserva de treballadors al núvol preparats`},help:{"v1-1nwve9s-7w":`Nombre objectiu de treballadors preparats sense assignar per projecte elegible que utilitzi aquest perfil (per defecte: 1), subjecte al límit global del conjunt de treballadors preparats de la Passarel·la. Establiu-lo a 0 per desactivar les reserves d'aquest perfil tot mantenint la reutilització d'instantànies. Els treballadors en preparació i les reserves amb la neteja pendent de confirmar compten per assolir l'objectiu.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Configuració del proveïdor de treballadors al núvol`},help:{"v1-mq7u32-4j":`Paràmetres propis del proveïdor validats pel connector seleccionat. Utilitzeu objectes SecretRef per als valors que continguin secrets; els paràmetres opacs no obtenen resolució automàtica de secrets.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Temps d'inactivitat abans de suspendre el treballador al núvol`},help:{"v1-1keuwgh-4w":`Allibera automàticament un treballador al núvol inactiu un cop transcorregut aquest temps, com ara 45m o 2h; el missatge següent aprovisiona un substitut. Mínim: 1m. Deixeu-lo sense definir per mantenir els treballadors en execució.`}},"cloudWorkers%2Eprofiles%2E*%2EworkspaceDurability":{label:{"v1-1yi22sz-v":`Durabilitat de l'espai de treball del repositori`},help:{"v1-1r6ow8r-6o":`Replicat per defecte. Els repositoris amb disc retingut requereixen un proveïdor de nodes gestionats amb recursos exactes i un interval de còmput finit explícit en segons. El disc original continua sent la font de referència entre torns; Mou a la Passarel·la l'exporta i el retira.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Perfils de treballadors al núvol per projecte`},help:{"v1-1kkfrif-46":`Noms dels perfils de treballadors al núvol predeterminats, amb la identitat del repositori normalitzada en minúscules (host/owner/repo) com a clau. Els identificadors de perfil explícits de l'enviament tenen prioritat.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Perfil de treballador al núvol del projecte`},help:{"v1-1mux5u0-30":`Nom del perfil de treballador al núvol utilitzat per defecte quan l'origen de l'arbre de treball d'una sessió coincideix amb aquesta identitat de repositori.`}},"cloudWorkers%2ErequiredProfile":{label:{"v1-1rqoa9j-n":`Perfil de treballador obligatori`},help:{"v1-1q30qf7-57":`Exigeix que totes les sessions s'executin amb aquest perfil de procés de treball. Les Sessions s'assignen automàticament i no poden recórrer a l'execució a la Passarel·la com a alternativa. Els processos de treball no disponibles bloquegen els torns, però no l'inici de la Passarel·la.`}},commands:{label:{"v1-15x4mpf-8":`Ordres`},help:{"v1-1gi0dr2-5a":`Controla les interfícies d'ordres del xat, les restriccions al propietari i el comportament de l'accés a ordres amb privilegis elevats entre proveïdors. Manteniu els valors per defecte tret que necessiteu controls d'operador més estrictes o una disponibilitat més àmplia de les ordres.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Regles d'accés a ordres amb privilegis elevats`},help:{"v1-7azkw-5g":`Defineix les regles que permeten ordres amb privilegis elevats per canal i remitent a les interfícies d'ordres de nivell de propietari. Utilitzeu identitats específiques de cada proveïdor amb un abast limitat perquè les ordres privilegiades no quedin exposades a un públic ampli del xat.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Permet l'ordre Bash del xat`},help:{"v1-83ah7w-36":"Permet que l'ordre bash del xat (`!`; àlies `/bash`) executi ordres de l'intèrpret d'ordres de l'amfitrió (per defecte: false; requereix tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Interval de Bash en primer pla (ms)`},help:{"v1-1o0o4dw-2c":`Temps que bash espera abans de passar a segon pla (per defecte: 2000; 0 passa a segon pla immediatament).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Permet /config`},help:{"v1-151bb7c-21":`Permet que l'ordre /config del xat llegeixi i escrigui la configuració al disc (per defecte: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Permet /debug`},help:{"v1-y1lc3j-1y":`Permet l'ordre /debug del xat per aplicar sobreescriptures només durant l'execució (per defecte: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Permet /mcp`},help:{"v1-1rtwcgd-2o":`Permet que l'ordre /mcp del xat gestioni la configuració dels servidors MCP d'OpenClaw a mcp.servers (per defecte: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Ordres natives`},help:{"v1-dighr2-5n":`Registra ordres natives de barra inclinada o de menú als canals que admeten el registre d'ordres (Discord, Slack, Telegram). Manteniu aquesta opció activada perquè siguin fàcils de trobar, tret que utilitzeu expressament fluxos de treball amb ordres només de text.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Ordres natives d'habilitats`},help:{"v1-19gtqci-5h":`Registra ordres natives d'habilitats perquè els usuaris puguin invocar habilitats directament des dels menús d'ordres del proveïdor, quan s'admeti. Manteniu aquesta opció d'acord amb la vostra política d'habilitats perquè les ordres disponibles coincideixin amb el que esperen els operadors.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Propietaris de les ordres`},help:{"v1-1di38gv-3y":`Llista explícita de propietaris autoritzats per a les ordres restringides als propietaris. Utilitzeu identificadors natius del canal (opcionalment amb un prefix, com ara "whatsapp:+15551234567"). '*' s'ignora.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Permet /plugins`},help:{"v1-akwy9y-33":`Permet que l'ordre de xat /plugins mostri els connectors detectats i n'activi o desactivi l'ús a la configuració (valor per defecte: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Permet el reinici`},help:{"v1-m32fv2-27":`Permet /restart, /update i les sol·licituds externes de reinici SIGUSR2 (valor per defecte: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Ordres de text`},help:{"v1-1utu76s-5j":`Activa l'anàlisi d'ordres de text a l'entrada del xat, a més de les interfícies d'ordres natives quan estiguin disponibles. Manteniu aquesta opció activada per garantir la compatibilitat amb els canals que no admeten el registre d'ordres natives.`}},cron:{label:{"v1-1qlte4b-b":`Automatitzacions`},help:{"v1-4md8ic-5u":`Configuració global del planificador per a les automatitzacions desades, la concurrència d'execucions, el lliurament alternatiu i la retenció de sessions d'execució. Manteniu els valors per defecte tret que estigueu ampliant el volum d'automatitzacions o integrant receptors de webhooks externs.`}},"cron%2Eagents":{label:{"v1-13sapf2-u":`Valors predeterminats de les automatitzacions per agent`},help:{"v1-15ynqdo-4x":`Valors predeterminats de les automatitzacions per agent, amb l'identificador de l'agent com a clau. Cada automatització utilitza l'entrada del seu agent efectiu (el seu agentId; si no, l'agent de la seva clau de sessió; si no, l'agent predeterminat).`}},"cron%2Eagents%2E*%2Edelivery":{label:{"v1-106qeoh-y":`Lliurament predeterminat de les automatitzacions de l'agent`},help:{"v1-fgez3q-5r":"Destinació predeterminada dels anuncis de les automatitzacions d'aquest agent que no especifiquen cap ruta. Substitueix completament `cron.delivery` per a aquest agent; els camps no es combinen. Un valor predeterminat del creador humà de la tasca hi té prioritat."}},"cron%2Eagents%2E*%2EfailureAlert":{label:{"v1-15hpccn-11":`Ruta de les alertes d'error de les automatitzacions de l'agent`},help:{"v1-ppqxgd-6j":"Ruta predeterminada de les alertes d'error (`mode`, `channel`, `to`, `threadId`, `accountId`) de les automatitzacions d'aquest agent. Substitueix completament els camps de ruta de `cron.failureAlert`; `enabled`, `after`, `cooldownMs` i `includeSkipped` continuen sent d'àmbit global a Gateway."}},"cron%2Ecreators":{label:{"v1-8luomx-w":`Valors predeterminats de les automatitzacions per creador`},help:{"v1-12liwzq-9q":`Valors predeterminats de les automatitzacions per creador, amb l'identificador del perfil de Gateway de la persona que ha creat l'automatització com a clau. Només s'apliquen quan l'automatització registra un perfil humà com a creador (directament o com a perfil que ha delegat la creació a un agent); les automatitzacions antigues i els creadors identificats només per un canal, desconeguts, agents o del sistema no utilitzen cap entrada de creador. Les claus han de coincidir exactament.`}},"cron%2Ecreators%2E*%2Edelivery":{label:{"v1-85aipy-10":`Lliurament predeterminat de les automatitzacions del creador`},help:{"v1-ybgvfk-4j":"Destinació predeterminada dels anuncis de les automatitzacions d'aquesta persona que no especifiquen cap ruta. Té prioritat sobre `cron.agents.<agentId>.delivery` i `cron.delivery`; els substitueix completament."}},"cron%2Ecreators%2E*%2EfailureAlert":{label:{"v1-1e8apq2-13":`Ruta d'alertes de fallada de les automatitzacions del creador`},help:{"v1-mlj76p-7m":"Ruta d'alertes de fallada predeterminada (`mode`, `channel`, `to`, `threadId`, `accountId`) per a les automatitzacions d'aquesta persona. Té prioritat sobre la ruta de l'agent propietari i substitueix íntegrament els camps de ruta de `cron.failureAlert`; `enabled`, `after`, `cooldownMs` i `includeSkipped` continuen sent globals per a Gateway."}},"cron%2EdefaultTools":{label:{"v1-huhclk-o":`Eines per defecte de les automatitzacions`},help:{"v1-1x80rr1-7x":`Eines que s'afegeixen quan l'eina d'automatitzacions crea o modifica explícitament una llista toolsAllow no buida, abans de les comprovacions de la política del creador i de l'aprovació. Si no es defineix, no s'hi afegeix res. Utilitzeu toolsAllowMode: "exact" en aquesta sol·licitud per evitar que s'hi afegeixin; [] continua sense eines. Les tasques existents i les modificacions no relacionades no canvien.`}},"cron%2Edelivery":{label:{"v1-11v82ye-s":`Lliurament predeterminat de les automatitzacions`},help:{"v1-1rndf98-aj":"Destinació d'anuncis predeterminada global de Gateway per a les automatitzacions que no especifiquen cap ruta pròpia (cap canal diferent de `last`, ni `to`, `threadId`, `accountId` o adreçament al propietari). Substitueix la ruta de sessió desada en el moment de l'execució i no s'aplica mai als lliuraments `none` o `webhook`. Un valor predeterminat de `cron.creators.<profileId>.delivery` o `cron.agents.<agentId>.delivery` té prioritat sobre aquest."}},"cron%2Edelivery%2EaccountId":{label:{"v1-192kjm5-10":`Compte de lliurament predeterminat de les automatitzacions`},help:{"v1-1ishqby-2j":`Compte de canal opcional per a la destinació predeterminada quan el canal té diversos comptes.`}},"cron%2Edelivery%2Echannel":{label:{"v1-b4tjph-10":`Canal de lliurament predeterminat de les automatitzacions`},help:{"v1-x3hpfs-39":"Canal per a la destinació predeterminada, com ara `telegram`. Ometeu-lo per utilitzar la resolució `last` amb el destinatari predeterminat."}},"cron%2Edelivery%2EthreadId":{label:{"v1-16jecza-z":`Fil de lliurament predeterminat de les automatitzacions`},help:{"v1-12h3hbw-2g":`Fil o tema de fòrum opcional per a la destinació predeterminada, com ara un identificador de tema de Telegram.`}},"cron%2Edelivery%2Eto":{label:{"v1-1iipxgp-12":`Destinatari de lliurament predeterminat de les automatitzacions`},help:{"v1-1odj9jz-3j":"Destinatari de la destinació predeterminada, amb la sintaxi de destinació del canal (per exemple, un identificador de xat de Telegram com ara `-100123456789`)."}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automatitzacions activades`},help:{"v1-y8otx6-5i":`Activa l'execució d'automatitzacions per a les programacions desades que gestiona la passarel·la. Manteniu aquesta opció activada per als fluxos habituals de recordatoris i automatitzacions, i desactiveu-la només per posar en pausa totes les execucions d'automatitzacions sense suprimir tasques.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Retenció de sessions d'automatitzacions`},help:{"v1-4wagu6-7e":"Controla quant de temps es conserven les sessions d'execució d'automatitzacions completades abans de purgar-les (`24h`, `7d`, `1h30m` o `false` per desactivar la purga; una durada nul·la com ara `0h` també la desactiva; valor per defecte: `24h`). Utilitzeu una retenció més curta per reduir el creixement de l'emmagatzematge en programacions d'alta freqüència."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Omet les automatitzacions recurrents no executades`},help:{"v1-w9wfmo-66":`Omet les execucions recurrents cron/every pendents en iniciar la Passarel·la i en programa la propera ocurrència futura en lloc de recuperar-les. Valor per defecte: false. Activeu aquesta opció per evitar recordatoris obsolets després d'un període d'inactivitat; les tasques puntuals at encara es recuperen.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Política SSRF dels webhooks d'automatitzacions`},help:{"v1-1xlfqnu-5h":`Política SSRF aplicada a cada webhook de sortida de les automatitzacions. Les destinacions privades, de bucle local, locals d'enllaç i internes es mantenen bloquejades tret que aquesta política les permeti explícitament. Deixeu-la sense definir per aplicar un lliurament estricte.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Noms d'amfitrió permesos per als webhooks d'Automatitzacions`},help:{"v1-1i94hyz-3n":`Noms d'amfitrió exactes o adreces IP literals permesos per al lliurament de webhooks d'automatitzacions, incloses les destinacions que altrament estarien bloquejades. Manteniu la llista al mínim.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Permet l'interval local únic IPv6 per als webhooks d'Automatitzacions`},help:{"v1-rke0oj-3b":`Permet enviar webhooks d'automatitzacions a adreces locals úniques IPv6 (fc00::/7). Feu-ho servir només amb entorns de servidor intermediari de confiança que utilitzin IP fictícies.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Permet l'interval de proves de rendiment RFC 2544 per als webhooks d'Automatitzacions`},help:{"v1-x1usg4-3h":`Permet enviar webhooks d'automatitzacions a adreces IP de l'interval de proves de rendiment RFC 2544 (198.18.0.0/15). Feu-ho servir només amb entorns de servidor intermediari de confiança que utilitzin IP fictícies.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Noms d'amfitrió bloquejats per als webhooks d'Automatitzacions`},help:{"v1-16cv1ic-6a":`Patrons de noms d'amfitrió denegats abans de la resolució DNS i de les regles de permís per al lliurament de webhooks d'automatitzacions. Admet amfitrions exactes i "*.example.com" només per als subdominis; afegiu "example.com" per separat per bloquejar el domini arrel. Si és buit o no està definit, no afegeix cap denegació.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Permet de manera perillosa la xarxa privada per als webhooks d'Automatitzacions`},help:{"v1-1n9710c-3t":`Permet webhooks d'automatització amb destinacions en xarxes privades i internes. Mantén aquesta opció desactivada tret que totes les destinacions de webhook configurades siguin de confiança.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Token de portador del webhook d'Automatitzacions`},help:{"v1-1l90hxg-5l":`Token de portador adjunt als enviaments POST dels webhooks d'automatització quan s'utilitza el mode webhook. És preferible fer servir la substitució per secrets o variables d'entorn i renovar aquest token periòdicament si els punts de connexió de webhook compartits són accessibles des d'Internet.`}},database:{label:{"v1-1ur2pjs-8":`Base de dades`},help:{"v1-zxclpq-90":`Selecció del motor de base de dades. SQLite és el motor predeterminat; PostgreSQL és una alternativa compatible amb les cinc famílies configurables. Doctor informa dels motors configurats i detectats i avisa de discrepàncies, funcionalitats que falten o magatzems no disponibles. Consulta la guia d'operació de PostgreSQL per conèixer els límits de validació de plataformes i actualitzacions.`}},"database%2Eengine":{label:{"v1-we5l2i-f":`Motor de base de dades`},help:{"v1-6hsgz2-6j":`Motor d'emmagatzematge predeterminat (per defecte: sqlite). PostgreSQL admet state, agent, workboard, logbook i team-reports tret que database.families els sobreescrigui; els magatzems de seguretat es mantenen en SQLite local. Canviar de motor no migra les dades existents.`}},"database%2Efamilies":{label:{"v1-1xrm7s9-n":`Motors de base de dades per família`},help:{"v1-12i1jst-75":`Sobreescriptures opcionals del motor per a state, agent, workboard, logbook i team-reports. Cada sobreescriptura requereix engine. Les famílies state i agent poden utilitzar motors diferents; els diaris locals de seguretat no són configurables. Totes les famílies de PostgreSQL comparteixen database.postgres.`}},"database%2Efamilies%2Eagent%2Eengine":{label:{"v1-1e7sns0-m":`Motor de base de dades de la família`},help:{"v1-fv44v3-77":`Sobreescriu database.engine per a aquesta família. Canviar de motor requereix executar database port --family i reiniciar; editar la configuració no migra les dades existents. La còpia de seguretat i la restauració amb motors mixtos conserven el motor de cada magatzem, i les actualitzacions requereixen que la versió candidata admeti la família.`}},"database%2Efamilies%2Elogbook%2Eengine":{label:{"v1-1e7sns0-m":`Motor de base de dades de la família`},help:{"v1-fv44v3-77":`Sobreescriu database.engine per a aquesta família. Canviar de motor requereix executar database port --family i reiniciar; editar la configuració no migra les dades existents. La còpia de seguretat i la restauració amb motors mixtos conserven el motor de cada magatzem, i les actualitzacions requereixen que la versió candidata admeti la família.`}},"database%2Efamilies%2Estate%2Eengine":{label:{"v1-1e7sns0-m":`Motor de base de dades de la família`},help:{"v1-fv44v3-77":`Sobreescriu database.engine per a aquesta família. Canviar de motor requereix executar database port --family i reiniciar; editar la configuració no migra les dades existents. La còpia de seguretat i la restauració amb motors mixtos conserven el motor de cada magatzem, i les actualitzacions requereixen que la versió candidata admeti la família.`}},"database%2Efamilies%2Eteam-reports%2Eengine":{label:{"v1-1e7sns0-m":`Motor de base de dades de la família`},help:{"v1-fv44v3-77":`Sobreescriu database.engine per a aquesta família. Canviar de motor requereix executar database port --family i reiniciar; editar la configuració no migra les dades existents. La còpia de seguretat i la restauració amb motors mixtos conserven el motor de cada magatzem, i les actualitzacions requereixen que la versió candidata admeti la família.`}},"database%2Efamilies%2Eworkboard%2Eengine":{label:{"v1-1e7sns0-m":`Motor de base de dades de la família`},help:{"v1-fv44v3-77":`Sobreescriu database.engine per a aquesta família. Canviar de motor requereix database port --family i un reinici; editar la configuració no migra les dades existents. La còpia de seguretat i la restauració amb motors mixtos preserven el motor de cada magatzem, i les actualitzacions requereixen compatibilitat amb la família candidata.`}},"database%2Epostgres":{label:{"v1-11caiz7-a":`PostgreSQL`},help:{"v1-1hstnlv-7j":`Connexió i nomenclatura d'esquemes de PostgreSQL. Les versions 16–18 de PostgreSQL estan validades; les altres versions principals admeses continuen sent experimentals fins que se'n comprovi la conformitat. Feu una còpia de seguretat de l'esquema de cada magatzem juntament amb el seu ancoratge local SQLite. Consulteu la guia d'operació de PostgreSQL per conèixer els límits de validació dels desplegaments.`}},"database%2Epostgres%2Econnection":{label:{"v1-17ej0zp-l":`Connexió de PostgreSQL`},help:{"v1-1gbko0p-9s":`DSN de PostgreSQL compartit, obligatori quan el motor efectiu de qualsevol família és postgres. Admet SecretRefs d'env, file i exec i connexions TLS; consulteu la guia d'operació de PostgreSQL per obtenir informació sobre la configuració i els límits de validació. Les referències basades en un magatzem no poden inicialitzar la base de dades. L'amfitrió el resol una sola vegada per als processos de treball de la base de dades. Els errors de connexió no provoquen mai l'ús de SQLite com a alternativa.`}},"database%2Epostgres%2Eownership":{label:{"v1-87ucg-s":`Titularitat de l'estat del Gateway a PostgreSQL`},help:{"v1-1e7fkqn-cj":`Àmbit de la titularitat de l'estat del Gateway (per defecte: state-directory, un fitxer de bloqueig local). installation també manté un bloqueig consultiu de sessió de PostgreSQL identificat per la base de dades i el prefix de l'esquema, de manera que es rebutja un segon Gateway o titular de manteniment per a la mateixa instal·lació en qualsevol amfitrió, i la pèrdua d'aquesta sessió atura el Gateway. Requereix que totes les famílies configurables utilitzin postgres. Els ancoratges del magatzem i els altres fitxers locals no canvien; consulteu la guia d'operació de PostgreSQL.`}},"database%2Epostgres%2ErecoveryCaptures":{label:{"v1-dlnk9p-s":`Captures de recuperació de PostgreSQL`},help:{"v1-1qes8ml-9m":`On les captures per revertir actualitzacions i canvis de Doctor desen les files de PostgreSQL (valor per defecte: portable). portable escriu una imatge d'exportació local de SQLite. server conserva les files en un esquema restore_ de la mateixa base de dades i només escriu l'àncora i el manifest localment; estalvia espai de disc local i temps d'exportació, però no sobreviu a la pèrdua del servidor. Les còpies de seguretat de l'usuari continuen sent portables.`}},"database%2Epostgres%2EschemaPrefix":{label:{"v1-1s0mt2q-o":`Prefix d'esquema de PostgreSQL`},help:{"v1-1a5738a-7o":`Prefix per als nous esquemes d'emmagatzematge de PostgreSQL (per defecte: openclaw). Feu servir entre 1 i 27 lletres minúscules, dígits o guions baixos, començant per una lletra o un guió baix. El prefix pg i els prefixos que comencen per pg_ generen noms d'esquema reservats de PostgreSQL. Els ancoratges existents conserven el seu esquema.`}},desktop:{label:{"v1-rs698z-7":`Escriptori`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Escriptori local`},help:{"v1-99weio-30":`Observació de l'escriptori per a nodes aparellats, o la font experimental de l'amfitrió de la Passarel·la, mitjançant un servidor VNC local.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Compartició de l'escriptori`},help:{"v1-m9lbcj-83":`Activa la font d'escriptori d'aquesta màquina. Els nodes macOS, Windows i Linux aparellats estan activats per defecte; una preferència explícita de compartició a l'aplicació d'escriptori té prioritat. La font Labs de l'amfitrió de la Passarel·la està desactivada per defecte i aplica els canvis en directe. Reinicieu el node aparellat després de canviar-ne la configuració d'escriptori.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Escriptori gestionat de l'amfitrió Linux`},help:{"v1-1r7n22m-49":`Executa i supervisa un escriptori TigerVNC/XFCE sense pantalla a Linux, accessible només per la interfície de bucle local. Un port explícit o un servidor VNC existent al port predeterminat continuen tenint prioritat.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Fitxer local de contrasenyes VNC`},help:{"v1-1m5lsox-37":`Camí absolut al fitxer de contrasenyes VNC. Ometeu-lo a macOS per introduir les credencials del compte en obrir el visor d'escriptori.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Port VNC local`},help:{"v1-1ku4w9b-2b":`Port RFB de bucle local d'un servidor VNC que ja s'executa en aquesta màquina (per defecte: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnòstic`},help:{"v1-1d5rnym-5p":`Controls de diagnòstic per al seguiment específic, l'exportació de telemetria i la inspecció de la memòria cau durant la depuració. Manteniu el diagnòstic bàsic al mínim en producció i activeu senyals més detallats només quan investigueu problemes.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Seguiment de la memòria cau`},help:{"v1-10523zm-5b":`Configuració del registre de seguiment de la memòria cau per observar les decisions de la memòria cau i el context de les dades de càrrega en execucions integrades. Activeu-lo temporalment per depurar i desactiveu-lo després per reduir la presència de dades sensibles als registres.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Seguiment de la memòria cau activat`},help:{"v1-2c1umi-1v":`Registra instantànies de les traces de memòria cau de les execucions d'agents integrats (per defecte: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnòstic activat`},help:{"v1-a46pxt-4h":`Interruptor general de la sortida d'instrumentació de diagnòstic als registres i a les vies d'integració de telemetria. Activat per defecte; establiu-lo a false només en entorns amb restriccions estrictes.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Indicadors de diagnòstic`},help:{"v1-x4w5ok-33":`Activa registres de diagnòstic específics per indicador (p. ex. ["telegram.http"]). Admet comodins com ara "telegram.*" o "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Configuració d'exportació d'OpenTelemetry per a traces, mètriques i registres emesos pels components de la Passarel·la. Utilitzeu-la per integrar-los amb sistemes centralitzats d'observabilitat i fluxos de processament de traces distribuïdes.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Captura de contingut d'OpenTelemetry`},help:{"v1-19tid4t-2t":`Captura opcional de contingut dels segments de traça d'OTEL. Desactivada per defecte; true captura el contingut dels missatges que no són del sistema i de les eines.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry activat`},help:{"v1-193bm0-5b":`Activa el flux d'exportació d'OpenTelemetry per a traces, mètriques i registres segons la configuració del punt de connexió i del protocol. Manteniu-lo desactivat llevat que el punt de connexió del col·lector i l'autenticació estiguin completament configurats.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Punt de connexió d'OpenTelemetry`},help:{"v1-4rrd1x-4y":`URL del punt de connexió del col·lector utilitzat per al transport de l'exportació d'OpenTelemetry, inclosos l'esquema i el port. Utilitzeu un punt de connexió del col·lector accessible i de confiança, i superviseu els errors d'ingestió després del desplegament.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Interval de buidatge d'OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Interval en mil·lisegons per al buidatge periòdic de telemetria de les memòries intermèdies al col·lector. Augmenteu-lo per reduir la freqüència de les exportacions o reduïu-lo per obtenir visibilitat més ràpidament durant la resposta activa a incidents.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Capçaleres d'OpenTelemetry`},help:{"v1-s26t2a-52":`Capçaleres HTTP addicionals enviades amb les sol·licituds d'exportació d'OpenTelemetry, sovint utilitzades per a l'autenticació de l'inquilí o l'encaminament. Manteniu els secrets en valors basats en variables d'entorn i eviteu la proliferació innecessària de capçaleres.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Registres d'OpenTelemetry habilitats`},help:{"v1-12wo6rv-4k":`Habilita l'exportació de senyals de registre mitjançant OpenTelemetry, a més de les destinacions de registre locals. Utilitzeu aquesta opció quan calgui una correlació centralitzada dels registres entre serveis i agents.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Punt de connexió dels registres d'OpenTelemetry`},help:{"v1-1vgzldu-40":`Punt de connexió OTLP/HTTP de registres específic del senyal. Quan es defineix, substitueix diagnostics.otel.endpoint i OTEL_EXPORTER_OTLP_ENDPOINT només per a l'exportació de registres.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Exportador de registres d'OpenTelemetry`},help:{"v1-9bzywd-5q":`Destinació d'exportació de registres per a diagnostics.otel.logs. Utilitzeu "otlp" per al punt de connexió de registres OTLP configurat, "stdout" per obtenir un registre JSON per línia de stdout en canalitzacions de registres de contenidors i "both" quan calguin totes dues destinacions.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Prefix dels noms de mètriques d'OpenTelemetry`},help:{"v1-1epdpi9-b2":`Substitueix el prefix predeterminat "openclaw." dels noms de les mètriques pròpies d'OpenClaw. Feu servir una cadena buida per eliminar el prefix, o fins a 128 lletres ASCII, dígits, guions baixos, punts, guions i barres inclinades, començant amb una lletra. Incloeu-hi qualsevol separador que necessiteu, per exemple "acme."; els noms de mètriques estàndard gen_ai.* no es modifiquen. Canviar aquest valor requereix actualitzar els taulers i les alertes que consulten els noms antics.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Mètriques d'OpenTelemetry activades`},help:{"v1-13r4cf4-4x":`Activa l'exportació de senyals de mètriques al punt de connexió del col·lector d'OpenTelemetry configurat. Manteniu-la activada per als taulers de salut en temps d'execució i desactiveu-la només si cal minimitzar el volum de mètriques.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Punt de connexió de mètriques d'OpenTelemetry`},help:{"v1-qlfh7x-47":`Punt de connexió de mètriques OTLP/HTTP específic del senyal. Quan es defineix, substitueix diagnostics.otel.endpoint i OTEL_EXPORTER_OTLP_ENDPOINT només per a l'exportació de mètriques.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Protocol d'OpenTelemetry`},help:{"v1-17ine8s-5e":`Protocol de transport OTel per a l'exportació de telemetria. Només s'accepta "http/protobuf"; executeu "openclaw doctor --fix" per corregir un valor antic "grpc" desat o obtenir indicacions d'edició manual específiques de l'origen.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Taxa de mostreig de traces d'OpenTelemetry`},help:{"v1-brcwep-50":`Taxa de mostreig de traces (0-1) que controla la quantitat de trànsit de traces que s'exporta als sistemes d'observabilitat. Les taxes més baixes redueixen la sobrecàrrega i el cost, mentre que les més altes milloren la fidelitat de la depuració.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Nom del servei d'OpenTelemetry`},help:{"v1-1hpiqon-5d":`Nom del servei indicat als atributs de recurs de telemetria per identificar aquesta instància de la passarel·la als sistemes d’observabilitat. Feu servir noms estables perquè els taulers i les alertes es mantinguin coherents entre desplegaments.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Traces d’OpenTelemetry activades`},help:{"v1-j7zrrp-4s":`Activa l’exportació de senyals de traça al punt de connexió configurat del col·lector d’OpenTelemetry. Manteniu-la activada quan calguin traces de latència o depuració i desactiveu-la si només voleu mètriques o registres.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Punt de connexió de traces d’OpenTelemetry`},help:{"v1-8yw5p1-43":`Punt de connexió de traces OTLP/HTTP específic del senyal. Quan s’estableix, substitueix diagnostics.otel.endpoint i OTEL_EXPORTER_OTLP_ENDPOINT només per a l’exportació de traces.`}},discovery:{label:{"v1-l2sr05-9":`Descobriment`},help:{"v1-1sqleij-4w":`Configuració del descobriment de serveis per a l’anunci local mitjançant mDNS i la senyalització opcional de presència en xarxes d’àrea extensa. Limiteu el descobriment a les xarxes previstes per evitar la filtració de metadades del servei.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Descobriment mDNS`},help:{"v1-vtbyyq-4w":`Grup de configuració del descobriment mDNS per ajustar l’anunci a la xarxa local i el comportament del descobriment. Manteniu el mode mínim per al descobriment habitual a la LAN, tret que calguin metadades addicionals.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Mode de descobriment mDNS`},help:{"v1-1p28pd5-2m":`Mode de difusió mDNS ("minimal" per defecte, "full" inclou cliPath/sshPort, "off" desactiva mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Descobriment en xarxes d’àrea extensa`},help:{"v1-1akkqjm-53":`Grup de configuració de la descoberta d'àrea extensa per exposar senyals de descoberta més enllà de l'àmbit de l'enllaç local. Activeu-lo només en desplegaments que agreguin intencionadament la presència de passarel·les entre ubicacions.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domini de descoberta d'àrea extensa`},help:{"v1-rxrygo-4m":`Domini DNS-SD unicast opcional per a la descoberta d'àrea extensa, com ara openclaw.internal. Utilitzeu-lo quan publiqueu intencionadament la descoberta de passarel·les més enllà dels àmbits mDNS locals.`}},env:{label:{"v1-1zc80q-b":`Entorn`},help:{"v1-1ao5po6-55":`Configuració d'importació i sobreescriptura de l'entorn que s'utilitza per proporcionar variables d'execució al procés de la passarel·la. Utilitzeu aquesta secció per controlar la càrrega de l'entorn de l'intèrpret d'ordres i el comportament de la injecció explícita de variables.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Importació de l'entorn de l'intèrpret d'ordres`},help:{"v1-1gw487t-4y":`Controls d'importació de l'entorn de l'intèrpret d'ordres per carregar variables de l'intèrpret d'ordres d'inici de sessió durant l'arrencada. Manteniu aquesta opció activada si depeneu de secrets definits al perfil o de personalitzacions de PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Importació de l'entorn de l'intèrpret d'ordres activada`},help:{"v1-5tiuup-5u":`Activa la càrrega de variables d'entorn des del perfil de l'intèrpret d'ordres de l'usuari durant la inicialització de l'arrencada. Manteniu aquesta opció activada en equips de desenvolupament, o desactiveu-la en entorns de servei restringits amb gestió explícita de l'entorn.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Temps d'espera de la importació de l'entorn de l'intèrpret d'ordres (ms)`},help:{"v1-nsk2yf-5c":`Temps màxim en mil·lisegons permès per resoldre l'entorn de l'intèrpret d'ordres abans d'aplicar el comportament alternatiu. Utilitzeu temps d'espera més curts per accelerar l'arrencada, o augmenteu-los si la inicialització de l'intèrpret d'ordres és costosa.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Sobreescriptures de variables d'entorn`},help:{"v1-1uloveo-5t":`Sobreescriptures explícites de variables d'entorn en format clau/valor que es fusionen amb l'entorn del procés d'execució d'OpenClaw. Utilitzeu-les per obtenir una configuració d'entorn predictible en lloc de dependre només dels efectes secundaris del perfil de l'intèrpret d'ordres.`}},gateway:{label:{"v1-7gz34p-7":`Passarel·la`},help:{"v1-1hooncl-5s":`Interfície d’execució de Gateway per al mode de vinculació, l’autenticació, l’aplicació web, el transport remot i els controls de seguretat operativa. Mantén els valors predeterminats conservadors tret que vulguis exposar expressament la passarel·la més enllà de les interfícies locals de confiança.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Permet x-real-ip com a alternativa a la Passarel·la`},help:{"v1-1wr3qmw-4c":`Habilita x-real-ip com a alternativa quan falta x-forwarded-for en escenaris amb servidor intermediari. Manteniu aquesta opció desactivada tret que la vostra infraestructura d'entrada requereixi aquest comportament de compatibilitat.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Autenticació de la Passarel·la`},help:{"v1-70b6ni-50":`Política d'autenticació per a l'accés HTTP/WebSocket a la passarel·la, inclosos el mode, les credencials, el comportament del servidor intermediari de confiança i la limitació de freqüència. Manteniu l'autenticació activada en qualsevol desplegament que no estigui restringit a la interfície de bucle local.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Permet la identitat de Tailscale per a l'autenticació de la Passarel·la`},help:{"v1-vqtmgw-53":`Permet que les vies d'identitat de confiança de Tailscale satisfacin les comprovacions d'autenticació de la passarel·la quan estiguin configurades. Utilitzeu aquesta opció només si la seguretat de les identitats de la vostra tailnet és sòlida i els fluxos de treball dels operadors en depenen.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Concessions d'àmbits d'identitat de la Passarel·la`},help:{"v1-1h0zxy7-5n":`Assigna identitats verificades d'un servidor intermediari de confiança o de Tailscale a concessions d'àmbits d'operador vàlides només per a la connexió. Les claus de correu electrònic es comparen sense distingir entre majúscules i minúscules; les concessions amplien els àmbits del dispositiu abans que s'apliqui el límit d'àmbits de la connexió.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Mode d'autenticació de la Passarel·la`},help:{"v1-j8rodq-9t":`Mode d'autenticació de la Passarel·la: "none", "token", "password" o "trusted-proxy", segons l'arquitectura perimetral. El mode token/password selecciona el secret configurat (gateway.auth.token o gateway.auth.password); els clients el poden enviar en qualsevol dels dos camps d'autenticació de connexió. Utilitzeu token/password per a l'exposició directa, i trusted-proxy només darrere de servidors intermediaris reforçats que verifiquin la identitat.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Contrasenya de la Passarel·la`},help:{"v1-1ndt0u2-4g":`Secret compartit seleccionat per gateway.auth.mode=password. Els clients el poden enviar tant a auth.token com a auth.password. El mode de contrasenya és obligatori per a Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Límit de freqüència d'autenticació de la Passarel·la`},help:{"v1-1kstr42-54":`Controls de limitació dels intents d'inici de sessió i autenticació per reduir el risc d'atacs de força bruta contra les credencials al perímetre de la passarel·la. Manteniu-los activats en entorns exposats i ajusteu els llindars al trànsit habitual.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Testimoni de la Passarel·la`},help:{"v1-16i7cxs-5q":`Secret compartit seleccionat per gateway.auth.mode=token, el valor per defecte per a les noves configuracions inicials locals. Els clients el poden enviar tant a auth.token com a auth.password. La vinculació a adreces que no siguin de bucle local requereix un mode d'autenticació activat.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Autenticació de la Passarel·la amb servidor intermediari de confiança`},help:{"v1-12fsi5d-58":`Mapatge de capçaleres d'autenticació trusted-proxy per als proveïdors d'identitat anteriors a la cadena que injecten atributs d'usuari. Utilitzeu-lo només amb blocs CIDR de servidors intermediaris coneguts i llistes estrictes de capçaleres permeses per evitar capçaleres d'identitat falsificades.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Identitat de GitHub amb OIDC de Cloudflare Access`},help:{"v1-1puth4k-6t":`Identitat verificada de GitHub opcional d'un proveïdor OIDC de Cloudflare Access seleccionat. Requereix les capçaleres estàndard de correu electrònic i d'asserció d'Access. Si falten les declaracions, es mantenen els perfils basats només en el correu electrònic; es conserven els rols dels perfils i les preferències de coautoria existents.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Declaració de l'ID del compte de GitHub`},help:{"v1-qd4qvh-87":`Declaració OIDC reenviada exacta el valor de la qual és un ID de compte de GitHub verificat, expressat com una cadena decimal positiva. Configureu Access perquè la reenviï i, a continuació, inspeccioneu la resposta d'identitat autenticada d'Access. OpenClaw llegeix oidc_fields, o bé custom si oidc_fields no hi és. No utilitzeu mai una declaració no verificada que l'usuari pugui editar.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Emissor de Cloudflare Access`},help:{"v1-gykv03-56":`Origen HTTPS exacte de l'equip de confiança de Cloudflare Access, com ara https://example.cloudflareaccess.com, sense barra final. Les declaracions d'altres emissors no proporcionen la identitat de GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`ID del proveïdor OIDC de Cloudflare Access`},help:{"v1-kbyo5w-44":`ID exacte del proveïdor d'identitat d'Access per a la integració OIDC de confiança. El nom visible d'un proveïdor o un nom de declaració coincident, per si sols, no estableixen confiança.`}},"gateway%2Eauth%2EtrustedProxy%2Edelegation":{label:{"v1-gzv594-t":`Delegació del navegador empresarial`},help:{"v1-1i9071w-4d":`Accepta la identitat del navegador OCE i les autoritzacions d'àmbit vinculades a una revisió a través del servidor intermediari de confiança privat. Els perfils delegats no utilitzen àlies de correu electrònic ni autoritzacions de dispositiu.`}},"gateway%2Eauth%2EtrustedProxy%2Edelegation%2EcredentialFile":{label:{"v1-vi5w92-q":`Fitxer de credencials de delegació`},help:{"v1-1tfpp2u-4t":`Camí absolut a un fitxer privat que conté la credencial de 32 bytes de la revisió en forma de 64 caràcters hexadecimals en minúscules. La substitució o l'eliminació del fitxer invalida les autoritzacions existents.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Aprovació automàtica de dispositius mitjançant un servidor intermediari de confiança`},help:{"v1-uh32ha-6z":`Política opcional per aprovar automàticament nous dispositius d'operador del navegador i de la interfície nativa, així com ampliacions d'àmbit amb la mateixa clau, després de l'autenticació mitjançant un servidor intermediari de confiança. Els permisos concedits estan limitats per deviceAutoApprove.scopes i per la capçalera x-openclaw-scopes del servidor intermediari, si hi és present.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Aprovació automàtica de dispositius mitjançant un servidor intermediari de confiança activada`},help:{"v1-1nntwls-78":`Aprova automàticament nous dispositius d'operador del navegador i de la interfície nativa, així com ampliacions d'àmbit amb la mateixa clau, després que el servidor intermediari invers autentiqui un usuari autoritzat. Valor predeterminat: false. Activeu aquesta opció només quan el perímetre de confiança de la identitat del servidor intermediari sigui prou sòlid per substituir l'aparellament manual de dispositius.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Àmbits d'aprovació automàtica de dispositius mitjançant un servidor intermediari de confiança`},help:{"v1-raeila-g3":`Àmbits màxims concedits als dispositius d'operador aprovats automàticament. Els valors predeterminats són operator.read, operator.write, operator.approvals i operator.questions. Els àmbits sol·licitats es limiten a aquesta llista; les sol·licituds sense àmbits reben aquesta llista. Si no es defineix, l'aprovació automàtica també afegeix operator.questions per als clients d'interfície antics; una llista explícita no s'amplia mai. Incloure explícitament operator.admin permet que qualsevol usuari autenticat pel servidor intermediari obtingui automàticament permisos d'administració complets i fa que les sol·licituds sense àmbits també els rebin automàticament; a més, genera una incidència crítica a l'auditoria de seguretat i un avís en iniciar la Passarel·la.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor":{help:{"v1-dai5ie-71":`Valors predeterminats opcionals de coautoria de l'organització provinents de les capçaleres del servidor intermediari autenticat. El servidor intermediari ha de sobreescriure aquests camps. No verifiquen la identitat de GitHub ni atorguen permisos; cal desar el consentiment abans que les adreces electròniques proporcionades apareguin a l'historial de commits.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EemailHeader":{help:{"v1-1j8gxp7-2h":`Capçalera que conté l'adreça electrònica d'atribució d'autoria dels commits de l'organització per a la identitat autenticada.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EemailVerifiedHeader":{help:{"v1-64bvpw-49":`Capçalera opcional que ha de tenir el valor true abans d'importar els valors predeterminats de l'organització. Ometeu-la només si l'afirmació del servidor intermediari sobre l'adreça electrònica és suficient segons la vostra política.`}},"gateway%2Eauth%2EtrustedProxy%2EgitCoauthor%2EnameHeader":{help:{"v1-14uvheq-2c":`Capçalera que conté el nom de coautor de l'organització per a la identitat autenticada.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Mode de vinculació de la Passarel·la`},help:{"v1-1unqude-4y":`Perfil de vinculació de xarxa: "auto", "lan", "loopback", "custom" o "tailnet" per controlar l'exposició de les interfícies. Manteniu "loopback" per al funcionament només local; "auto" pot exposar totes les interfícies.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Agents CLI`},help:{"v1-1unx5p8-57":`Descobriment des de l’aplicació web de motors de sessió CLI externs exposats pel catàleg de sessions de Gateway. Activat per defecte; desactiva’l per impedir que s’iniciïn aquests motors des del selector de models de sessions noves.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Agents CLI activats`},help:{"v1-9ei1mn-8m":`Mostra els agents CLI del catàleg al selector de models de sessions noves de l’aplicació web quan el valor és true (per defecte: true). Estableix-lo a false per desactivar els agents CLI i la creació de sessions CLI natives. Només es mostren els catàlegs que anuncien la creació de sessions, i el selector es manté ocult quan Gateway no anuncia la compatibilitat amb catàlegs de sessions.`}},"gateway%2EcontrolUi":{label:{"v1-zyppo6-7":`Aplicació web`},help:{"v1-v2rtyb-5f":`Configuració de l'allotjament de l'aplicació web, incloent-hi l'activació, les rutes i les mesures de seguretat per als orígens del navegador i l'autenticació. Manteniu al mínim l'exposició de la interfície i combineu-la amb controls d'autenticació robustos abans de fer desplegaments accessibles des d'Internet.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-14ny3x-n":`Orígens permesos de l'aplicació web`},help:{"v1-1br04sw-aq":`Orígens del navegador permesos per a les connexions de l'aplicació web/WebChat (només orígens complets, p. ex. https://control.example.com). Si s'omet, s'utilitza gateway.publicOrigin per defecte, si està configurat. Una llista explícita, inclosa [], substitueix aquest valor per defecte; les regles existents per als orígens locals o privats continuen aplicant-se. Establir ["*"] permet qualsevol origen del navegador i s'ha d'evitar fora de proves locals estrictament controlades.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-ylb79x-x":`Permet URL externs per a contingut incrustat a l'aplicació web`},help:{"v1-y8g73z-62":`Opció PERILLOSA que permet que el contingut incrustat allotjat carregui URL http(s) externs absoluts. Manteniu-la desactivada tret que l'aplicació web incrusti intencionadament pàgines de tercers de confiança; els documents allotjats a /__openclaw__/canvas no la necessiten.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Obtén automàticament les icones de lloc dels enllaços`},help:{"v1-1dimlov-ac":`Obtén les icones de lloc dels enllaços i les previsualitzacions de pàgines d’enllaços externs a través del Gateway (activat per defecte). Les previsualitzacions de pàgines carreguen les metadades públiques de la pàgina i les imatges declarades sense galetes del navegador ni credencials del lloc web. Totes les sol·licituds utilitzen comprovacions SSRF estrictes i un processament limitat d’HTML i imatges. Estableix el valor a false per desactivar tant l’obtenció automàtica d’icones de lloc com la de previsualitzacions de pàgines; les captures de pantalla en directe del navegador no es veuen afectades.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-zclsby-h":`Ruta base de l'aplicació web`},help:{"v1-npn03b-1t":`Prefix d'URL opcional des d'on se serveix l'aplicació web (p. ex. /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-13uozha-s":`Invitació a la comunitat de l'aplicació web`},help:{"v1-1m3mu0g-7i":`Mostra una targeta de comunitat que es pot tancar a la barra lateral de l'aplicació web (activada per defecte), amb enllaços a Discord, Reddit i X. Establiu el valor false per amagar-la en tots els navegadors que utilitzin aquest desplegament de la interfície. Els canvis s'apliquen després d'actualitzar el navegador o de tornar a connectar-se. Es continuen respectant els tancaments de la targeta ja desats localment al navegador.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Permet de manera perillosa utilitzar la capçalera Host com a alternativa per determinar l'origen`},help:{"v1-1i3oa94-7s":`Opció PERILLOSA que habilita un mecanisme alternatiu d'origen basat en la capçalera Host per a les comprovacions de WebSocket de l'aplicació web i de WebChat. Aquest mode és compatible amb desplegaments que es basen intencionadament en una política d'origen de la capçalera Host; configurar explícitament gateway.controlUi.allowedOrigins continua sent l'opció predeterminada recomanada per reforçar la seguretat.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-kc00jb-q":`Mode d'aïllament del contingut incrustat a l'aplicació web`},help:{"v1-176jrc2-79":`Política d'aïllament d'iframe per al contingut incrustat a l'aplicació web allotjada. "strict" desactiva els scripts, "scripts" permet contingut incrustat interactiu tot mantenint l'aïllament d'origen (opció predeterminada) i "trusted" afegeix \`allow-same-origin\` per als documents del mateix lloc que necessiten intencionadament més privilegis.`}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-vpzojz-f":`Aplicació web habilitada`},help:{"v1-1u14fve-4l":`Permet servir l'aplicació web des del procés HTTP de la passarel·la quan el valor és true. Manteniu aquesta opció habilitada per a l'administració local i desactiveu-la quan una interfície de control externa la substitueixi.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-1d85isf-j":`Entorn de l'aplicació web`},help:{"v1-vlhh70-4k":`Identitat pública opcional de l'entorn que es mostra a la franja de l'aplicació web, a l'avatar de l'agent, a les etiquetes, al títol del navegador i a la icona de lloc. Ometeu-la per conservar l'aparença predeterminada.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-1h2k80-p":`Color de l'entorn de l'aplicació web`},help:{"v1-mp6cta-2i":`Escala de colors de l'entorn amb nom: teal, amber, purple, coral, pink, blue, green, red o gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-vrxwqd-p":`Etiqueta de l'entorn de l'aplicació web`},help:{"v1-1l8ng2x-3w":`Etiqueta de l'entorn que es mostra a l'aplicació web i a la pestanya del navegador; se n'eliminen els espais en blanc inicials i finals i ha de contenir entre 1 i 24 caràcters.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-1oh9bbh-t":`Funcions experimentals de l'aplicació web`},help:{"v1-d3p8ng-3m":`Funcions experimentals de l'aplicació web i ajustos avançats que es conserven. Les funcions experimentals estan desactivades per defecte, tret que la documentació de l'opció corresponent indiqui el contrari.`}},"gateway%2EcontrolUi%2Eexperimental%2EchatBubbles":{label:{"v1-1i4j62s-e":`Bombolles de conversa`},help:{"v1-19ex4en-5j":`Activa les bafarades experimentals a l'aplicació web (per defecte: false). Mentre aquesta opció està activada, la pàgina d'inici fa servir bafarades per defecte; les preferències de cada sessió desades localment al navegador tenen prioritat. Els canvis s'apliquen sense reiniciar Gateway.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Interfície dels connectors personalitzats`},help:{"v1-18073xm-by":`Permet que els connectors instal·lats per l'usuari que estiguin activats executin JavaScript natiu a l'aplicació web (per defecte: true). Es conserva com a opció avançada de desactivació accessible només mitjançant la configuració; els valors false existents continuen desactivats. No afecta les vistes dels connectors inclosos. La interfície nativa comparteix els permisos de Gateway de l'operador que ha iniciat la sessió; instal·leu només connectors de confiança. Els canvis s'apliquen sense reiniciar Gateway. Després de desactivar aquesta opció, torneu a carregar les pàgines obertes de l'aplicació web per eliminar el codi dels connectors carregat anteriorment.`}},"gateway%2EcontrolUi%2Eexperimental%2Etemplates":{label:{"v1-it5x1k-9":`Plantilles`},help:{"v1-1879y2q-3u":`Activa la descoberta de ClawHub i l'addició unidireccional a través de l'aplicació web i Gateway (per defecte: false). Els agents existents continuen funcionant mentre aquesta opció està desactivada.`}},"gateway%2EcontrolUi%2Egithub%2Ehost":{label:{"v1-rjp3f8-r":`Amfitrió del servei de GitHub de l'aplicació web`},help:{"v1-qaa5xb-3z":`Amfitrió al qual pot accedir aquesta credencial de servei. Ometeu-lo per a github.com; establiu-lo a gateway.github.host per a la descoberta de projectes i les metadades del compte d'Enterprise.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1ia5u0n-x":`Credencial del servei de GitHub de l'aplicació web`},help:{"v1-uw4wdq-b5":`Credencial de servei basada en SecretRef per a la descoberta de projectes de l'aplicació web i les previsualitzacions de GitHub en passar-hi el cursor, sense una identitat gestionada. Establiu gateway.controlUi.github.host per a Enterprise; si s'omet l'amfitrió, es fa servir github.com. Les previsualitzacions en passar-hi el cursor donen preferència a la identitat de GitHub configurada de l'agent seleccionat. L'ús de GH_TOKEN/GITHUB_TOKEN com a alternativa només s'aplica a github.com. Es rebutgen les sol·licituds que utilitzen una credencial que no coincideix o que no està disponible.`}},"gateway%2EcontrolUi%2EnewSessionModelDefaults":{label:{"v1-bxfhmu-q":`Valors predeterminats del model per a sessions noves`},help:{"v1-1r6o74t-98":`Trieu "configured" per iniciar esborranys nous de l’aplicació web amb els valors predeterminats de model, entorn d’execució i raonament configurats per a l’agent seleccionat, en lloc de les seleccions desades. Valor predeterminat: "last-used". Les opcions explícites dels esborranys i de les converses continuen sent editables; el mode ràpid i les preferències d’ubicació no canvien. S’aplica després d’actualitzar el navegador o de tornar a connectar.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-1ke8erh-j":`Directori arrel dels recursos de l’aplicació web`},help:{"v1-192j3ry-22":`Directori arrel opcional del sistema de fitxers per als recursos de l’aplicació web (per defecte, dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-zsqsj8-o":`Observador de sessions de l’aplicació web`},help:{"v1-1uilm4q-87":`Genera resums de l’estat de les sessions en temps real per als clients subscrits de l’aplicació web amb el model auxiliar de cada agent (activat per defecte). Establiu-lo a false per desactivar les crides al model observador a tota la passarel·la; establir agents.defaults.utilityModel a una cadena buida desactiva l’observació amb el model auxiliar per als agents que no sobreescriuen aquest valor.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Amfitrió d'escolta personalitzat de la Passarel·la`},help:{"v1-lwjcyo-4d":`Adreça IPv4 utilitzada per a una vinculació personalitzada. Les adreces IPv4 específiques també requereixen el mateix port de la Passarel·la a 127.0.0.1; eviteu 0.0.0.0 tret que calgui exposar el servei a totes les interfícies.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`API HTTP de la Passarel·la`},help:{"v1-9vup6v-4y":`Configuració de l'API HTTP de la Passarel·la que agrupa els controls d'activació dels punts de connexió i els controls d'exposició de l'API a la capa de transport. Manteniu activats només els punts de connexió necessaris per limitar allò a què poden accedir els clients remots.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Punts de connexió HTTP de la Passarel·la`},help:{"v1-1a0r104-55":`Controls d'activació de les funcions dels punts de connexió HTTP de l'API de la passarel·la per a rutes de compatibilitat i integracions opcionals. Activeu els punts de connexió de manera deliberada i superviseu els patrons d'accés després del desplegament.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Punt de connexió d'OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Activa el punt de connexió `POST /v1/chat/completions` compatible amb OpenAI (valor per defecte: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Límits d'imatge d'OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Controls d'obtenció i validació d'imatges per a les parts `image_url` compatibles amb OpenAI."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Llista de tipus MIME d'imatge permesos d'OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Tipus MIME permesos per a les parts `image_url` (llista que no distingeix entre majúscules i minúscules)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Permet els URL d'imatges a OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Permet obtenir contingut d'URL des del servidor per a les parts `image_url` (valor predeterminat: false; els URI de dades continuen sent compatibles). Establiu aquest valor a `false` per desactivar completament l'obtenció de contingut d'URL."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Màxim de bytes per imatge d'OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Màxim de bytes per imatge `image_url` obtinguda o descodificada (valor predeterminat: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Màxim de redireccions per imatge d'OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Màxim de redireccions HTTP permeses en obtenir contingut dels URL d'`image_url` (valor predeterminat: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Temps d'espera de les imatges d'OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Temps d'espera en mil·lisegons per obtenir contingut dels URL d'`image_url` (valor predeterminat: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Llista d'URL d'imatges permesos d'OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Llista opcional de noms d'amfitrió permesos per obtenir recursos d'URL d'`image_url`; admet noms d'amfitrió exactes i comodins com `*.example.com`. Si la llista és buida o s'omet, no s'aplica cap restricció de noms d'amfitrió permesos."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Capçaleres de seguretat HTTP de la Passarel·la`},help:{"v1-n8z1hb-44":`Capçaleres opcionals de seguretat de resposta HTTP aplicades pel mateix procés de la passarel·la. És preferible configurar-les al servidor intermediari invers si la connexió TLS hi acaba.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Capçalera de seguretat estricta del transport`},help:{"v1-1buwhc3-3v":`Valor de la capçalera de resposta Strict-Transport-Security. Establiu-lo només en orígens HTTPS que controleu completament; utilitzeu false per desactivar-lo explícitament.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Mode de la Passarel·la`},help:{"v1-nfjirv-5m":`Mode de funcionament de la Passarel·la: "local" executa els canals i l'entorn d'execució de l'agent en aquest amfitrió, mentre que "remote" es connecta mitjançant un transport remot. Manteniu "local" tret que utilitzeu expressament una topologia de passarel·la remota dividida.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Habilitats dels nodes de la Passarel·la activades`},help:{"v1-1xwu6at-3g":`Accepta les habilitats publicades pels nodes aparellats mentre estan connectats (valor predeterminat: true). Establiu false per ignorar les habilitats publicades pels nodes.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Mode del Navegador dels nodes de la Passarel·la`},help:{"v1-oeu1nc-69":`Encaminament del navegador dels nodes ("auto" = prioritza el navegador de l'amfitrió i utilitza un únic node de navegador connectat quan la funcionalitat local no està disponible; "manual" = requereix una selecció explícita del node o una assignació fixa configurada; "off" = desactiva l'encaminament als nodes).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Fixació del node del navegador de la Passarel·la`},help:{"v1-1cykty2-1p":`Fixa l'encaminament del navegador a un identificador o nom de node concret (opcional).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Llista de permesos dels nodes de la Passarel·la (ordres addicionals)`},help:{"v1-6l4otb-5m":"Ordres node.invoke addicionals que es permeten més enllà de les predeterminades de la passarel·la (matriu de cadenes d'ordres). Habilitar ordres perilloses aquí és una excepció sensible per a la seguretat que `openclaw security audit` assenyala."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Llista de bloquejats dels nodes de la Passarel·la`},help:{"v1-u7c8wx-53":"Noms d'ordres de node que cal bloquejar encara que figurin a les declaracions del node o a la llista de permesos predeterminada (només coincidències exactes del nom de l'ordre, p. ex. `system.run`; no inspecciona el text de l'intèrpret d'ordres dins d'aquesta ordre)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Aparellament de nodes de la Passarel·la`},help:{"v1-gldsi2-4s":`Configuració de la política d'aparellament de nodes. L'aprovació automàtica verificada per SSH està habilitada per defecte; l'aprovació automàtica per CIDR continua deshabilitada tret que es configurin llistes explícites de CIDR/IP de confiança permesos.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR d'aprovació automàtica de l'aparellament de nodes de la Passarel·la`},help:{"v1-jeel9f-6u":`Llista de CIDR/IP permesos d’activació opcional per aprovar automàticament el primer aparellament de dispositius amb rol de node sense àmbits sol·licitats. Desactivada si no es defineix. Els aparellaments d’operadors, navegadors i aplicacions web, així com qualsevol aparellament que ampliï rols, àmbits, metadades o claus públiques, continuen requerint aprovació manual.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Aprovació automàtica local de l'aparellament de nodes de la Passarel·la`},help:{"v1-glzm36-41":`Aprova sense avisar els aparellaments locals de confiança i les ampliacions d'accés (per defecte: true); estableix-ho a false per renunciar a la comoditat a canvi de l'aprovació explícita de cada dispositiu.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Verificació SSH de l'aparellament de nodes de la Passarel·la`},help:{"v1-1e4da92-ct":"Aprovació automàtica verificada per SSH per al primer aparellament de dispositius amb rol de node (per defecte: activada). La passarel·la es connecta per SSH a l'amfitrió que sol·licita l'aparellament (BatchMode, comprovació estricta de les claus d'amfitrió) i només l'aprova quan la sortida remota de `openclaw node identity` coincideix amb la clau del dispositiu pendent. Estableix-ho a false per desactivar la verificació SSH (independent d'autoApproveCidrs, que continua actiu); per permetre només l'aparellament manual, elimina també el valor d'autoApproveCidrs. Passa un objecte per sobreescriure user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Eines de connectors dels nodes de la Passarel·la`},help:{"v1-1c24iq3-28":`Controla si els nodes aparellats poden publicar descriptors d'eines de connectors visibles per als agents.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Eines de connectors dels nodes de la Passarel·la activades`},help:{"v1-14lgfu6-47":`Accepta els descriptors d'eines de connectors visibles per als agents publicats pels nodes aparellats (per defecte: true). Estableix-ho a false per ignorar i eliminar totes les eines de connectors publicades pels nodes.`}},"gateway%2EopenclawId":{label:{"v1-ezzq9b-p":`Accés remot amb OpenClaw ID`},help:{"v1-1ulzsn4-95":`Accés remot experimental amb OpenClaw ID (Labs). Quan està activat, la passarel·la supervisa un procés fill de túnel que accepta connexions iroh de dispositius admesos i les reenvia a aquesta passarel·la. Està desactivat per defecte; mentre està desactivat, la passarel·la no inicia cap procés fill, no obre cap sòcol de túnel ni contacta amb OpenClaw ID ni amb cap servei de descoberta o de retransmissió.`}},"gateway%2EopenclawId%2EclientId":{label:{"v1-1g7ikna-t":`ID de client de l’aplicació web d’OpenClaw ID`},help:{"v1-4vjfwu-8r":`Client OAuth públic (codi d’autorització amb PKCE) que l’aplicació web utilitza per iniciar sessió amb OpenClaw ID des del menú del compte. El seu URI de redirecció és <web app origin>/openclaw-id/callback. En aquesta màquina, l’inici de sessió utilitza aquesta redirecció; una aplicació web a la qual s’accedeix mitjançant un inici de sessió personal, com ara Tailscale, utilitza el flux d’autorització de dispositius de l’emissor.`}},"gateway%2EopenclawId%2EdiscoveryUrl":{label:{"v1-hnez1c-p":`URL de descoberta d'OpenClaw ID`},help:{"v1-14rpvwb-5h":`Servei de descoberta que replica el descriptor del claw i la instantània de pertinença i retransmet els missatges de la bústia. No es considera de confiança: cada declaració que retorna es verifica amb l'arrel de confiança fixada del propietari del claw.`}},"gateway%2EopenclawId%2Eenabled":{label:{"v1-c5v95y-x":`Accés remot amb OpenClaw ID activat`},help:{"v1-19yjuzt-66":`Activa l'accés remot experimental amb OpenClaw ID (valor per defecte: false). Els canvis s'apliquen sense reiniciar la passarel·la. L'accés remot també requereix relayUrl; per vincular un claw, també calen issuerUrl, discoveryUrl i loaderDomain.`}},"gateway%2EopenclawId%2EissuerUrl":{label:{"v1-g27qab-m":`URL de l'emissor d'OpenClaw ID`},help:{"v1-dmrsc-4e":`Emissor d'OpenClaw ID utilitzat per iniciar sessió únicament per verificar la identitat durant la vinculació d'un claw. Mai no es considera de confiança per determinar la pertinença, aprovar dispositius o decidir a quin servidor es connecta un client.`}},"gateway%2EopenclawId%2EloaderDomain":{label:{"v1-1m8dm2q-p":`Domini del carregador d'OpenClaw ID`},help:{"v1-1xj9br0-4o":`Domini DNS del carregador d'OpenClaw ID, sense protocol ni ruta; un claw vinculat és accessible a https://<name>-<account tag>.<loaderDomain> i la vinculació del seu servidor està signada per a aquest nom d'amfitrió.`}},"gateway%2EopenclawId%2EmemberDeviceInactivityDays":{label:{"v1-bv2n4v-17":`Inactivitat del dispositiu del membre d'OpenClaw ID (dies)`},help:{"v1-1n802ug-3g":`Dies que el navegador d'un membre pot passar sense connectar-se a aquest claw abans que el claw l'elimini (per defecte: 30). El membre continua figurant a la llista.`}},"gateway%2EopenclawId%2EownerDeviceInactivityDays":{label:{"v1-1elnzyi-16":`Inactivitat del dispositiu del propietari d'OpenClaw ID (dies)`},help:{"v1-cy2c02-3x":`Dies que un dispositiu del propietari pot passar sense connectar-se a aquest claw abans que el claw l'elimini de la seva llista de permesos (per defecte: 90). Els dispositius que hagi aprovat es mantenen.`}},"gateway%2EopenclawId%2ErelayUrl":{label:{"v1-1r8to4f-l":`URL del servidor de retransmissió d'OpenClaw ID`},help:{"v1-1f4exuo-3w":`L'únic servidor de retransmissió iroh del mapa de retransmissió del punt final del túnel (sense servidors de retransmissió públics n0, DNS ni pkarr). Els navegadors només es connecten al claw a través d'aquest servidor de retransmissió.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Port de la Passarel·la`},help:{"v1-af1nrn-51":`Port TCP que utilitza el servei d'escolta de la passarel·la per a l'API, l'aplicació web i les vies d'entrada dels canals. Utilitzeu un port dedicat i eviteu conflictes amb servidors intermediaris inversos o serveis de desenvolupament locals.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Portals de la Passarel·la`},help:{"v1-1v2lkw9-1c":`Configuració de la publicació de portals i de l'accés d'entrada privat.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Entrada privada dels portals`},help:{"v1-20w4gq-69":`Servidor intermediari invers HTTPS privat amb comodí, opcional i gestionat per l'operador. Reenvieu el Host original, els camins i les actualitzacions de connexió WebSocket al receptor de bucle local dedicat. L'autenticació amb testimoni de portador dels portals continua sent obligatòria. Requereix reiniciar la Passarel·la.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Domini amb comodí dels portals`},help:{"v1-1ffvdzt-50":`Domini DNS base per a subdominis de portal aleatoris (per exemple, previews.example.net). Configureu el DNS amb comodí i l'HTTPS de manera privada; no compartiu l'espai de noms de host del Gateway ni de l'aplicació web.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Port de bucle local d'entrada dels portals`},help:{"v1-1mb98cv-4g":`Port HTTP de bucle local dedicat que rep el trànsit del servidor intermediari HTTPS privat amb comodí. Ha de ser diferent del port de la Passarel·la. És el port del rerefons, no el port HTTPS públic.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Origen públic de la Passarel·la`},help:{"v1-1c6onp0-ae":`Origen HTTPS del Gateway accessible des de l'exterior. També és l'origen predeterminat del navegador quan s'omet gateway.controlUi.allowedOrigins. Només es permet HTTP per a localhost, 127.0.0.1 o [::1]. L'OAuth d'MCP per sol·licitant l'utilitza per construir l'URL de retorn a /oauth/mcp/callback; els enllaços de sessió dels canals i els enllaços de visualització generats pels connectors l'utilitzen per accedir a l'aplicació web i a les rutes del Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Lliurament de notificacions push de la Passarel·la`},help:{"v1-h23oz7-5s":`Configuració del lliurament de notificacions push que utilitza la passarel·la quan necessita activar dispositius aparellats o enviar-los notificacions. Configureu aquí les APNs mitjançant un servidor de retransmissió per a les compilacions oficials d'iOS; l'autenticació directa d'APNs continua basada en variables d'entorn per a les compilacions locals o manuals.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Lliurament d'APNs de la Passarel·la`},help:{"v1-4bbafr-4e":`Configuració de lliurament d'APNs per als dispositius iOS aparellats amb aquesta passarel·la. Feu servir la configuració del retransmissor per a les compilacions oficials de l'App Store que es registren mitjançant el retransmissor extern de notificacions push.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Retransmissor APNs de la Passarel·la`},help:{"v1-7glbel-6x":`Configuració del retransmissor extern per als enviaments APNs mitjançant un retransmissor. La passarel·la fa servir per defecte el retransmissor allotjat d'OpenClaw, o bé aquest retransmissor personalitzat, per a push.test, els avisos d'activació i les activacions de reconnexió després que una compilació oficial d'iOS aparellada publiqui un registre mitjançant un retransmissor.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`URL base del retransmissor APNs de la Passarel·la`},help:{"v1-1o8mgnq-69":`URL HTTPS base personalitzada opcional per al servei extern de retransmissió APNs que fan servir les compilacions oficials d'iOS de l'App Store. Manteniu-la alineada amb l'URL del retransmissor integrada a la compilació d'iOS perquè el trànsit de registre i d'enviament arribi al mateix desplegament.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Temps d'espera del retransmissor APNs de la Passarel·la (ms)`},help:{"v1-a0jkb1-4z":`Temps d'espera en mil·lisegons per a les sol·licituds d'enviament de la passarel·la al retransmissor APNs (per defecte: 10000). Augmenteu-lo per a retransmissors o xarxes més lents, o reduïu-lo perquè els intents d'activació fallin més aviat.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Recàrrega de la configuració`},help:{"v1-d02mvq-4w":`Política de recàrrega de la configuració en directe que determina com s'apliquen els canvis i quan s'activen els reinicis complets. Manteniu el comportament híbrid per fer actualitzacions operatives amb la màxima seguretat, llevat que estigueu depurant els mecanismes interns de recàrrega.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Mode de recàrrega de la configuració`},help:{"v1-1q1etcf-3m":`Controla com s'apliquen els canvis de configuració: "off" ignora els canvis en directe i "hybrid" aplica els canvis que es poden fer en calent de manera segura i després reinicia quan cal.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Passarel·la remota`},help:{"v1-6xv7gd-5a":`Configuració de connexió a la passarel·la remota per al transport directe o per SSH quan aquesta instància actua com a intermediària amb un altre amfitrió d'execució. Feu servir el mode remot només quan hàgiu configurat expressament el funcionament amb amfitrions separats.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Capçaleres d'autenticació perimetral de la Passarel·la remota`},help:{"v1-jg9p7d-5o":`Capçaleres HTTP basades en secrets que es presenten a un servidor intermediari amb reconeixement d'identitat situat davant de la Passarel·la remota configurada. Les capçaleres s'envien només a l'origen exacte de gateway.remote.url mitjançant WSS i no segueixen mai les redireccions.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Contrasenya de la Passarel·la remota`},help:{"v1-16jc0yx-7y":`Secret compartit que s'envia al camp de contrasenya per autenticar aquest client davant d'una passarel·la remota. El paràmetre gateway.auth.mode del servidor selecciona el secret configurat; s'accepta tant el camp de testimoni del client com el de contrasenya. Gestioneu aquest secret externament i eviteu els valors en text pla a la configuració desada al control de versions.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Política de claus d'amfitrió SSH de la Passarel·la remota`},help:{"v1-7qoxtb-49":`Política de verificació de claus d'amfitrió SSH a macOS. "strict" requereix una clau d'amfitrió que ja sigui de confiança; "openssh" delega explícitament en la configuració efectiva d'OpenSSH.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Identitat SSH de la Passarel·la remota`},help:{"v1-hz2hsm-1f":`Camí opcional del fitxer d'identitat SSH (es passa a ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Destinació SSH de la Passarel·la remota`},help:{"v1-85w39w-2t":`Passarel·la remota per SSH (crea un túnel del port de la passarel·la a localhost). Format: user@host o user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Empremta TLS de la Passarel·la remota`},help:{"v1-1ri16lk-23":`Empremta TLS sha256 esperada de la passarel·la remota (fixeu-la per evitar atacs MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Testimoni de la Passarel·la remota`},help:{"v1-1pb9q8w-7v":`Secret compartit que s'envia al camp token per autenticar aquest client en una passarel·la remota. El paràmetre gateway.auth.mode del servidor selecciona el secret configurat; s'accepta tant el camp token com el camp password del client. Emmagatzemeu-lo mitjançant substitució de secrets o variables d'entorn i renoveu-lo quan canvieu l'autenticació de la passarel·la remota.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transport de la Passarel·la remota`},help:{"v1-1acfs7m-54":`Transport de la connexió remota: "direct" utilitza la connectivitat de l'URL configurat, mentre que "ssh" crea un túnel a través d'SSH. Utilitzeu SSH quan necessiteu un túnel xifrat sense exposar ports remots.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL de la Passarel·la remota`},help:{"v1-va7exe-1b":`URL WebSocket de la Passarel·la remota (ws:// o wss://).`}},"gateway%2ErepositoryIntegration":{label:{"v1-9msrgf-m":`Integració de repositoris`},help:{"v1-10mbwuf-7d":`ID del connector necessari per autoritzar l'accés dels processos de treball al codi font dels repositoris, incloent-hi les credencials natives, de GitHub App i les credencials OAuth o PAT gestionades. Si els connectors responsables no existeixen, estan desactivats o no s'han carregat, es denega l'accés. Ometeu-lo per utilitzar el comportament natiu dels repositoris; activar un connector no el selecciona automàticament.`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Rols d'operador de la Passarel·la`},help:{"v1-1h5f6fh-84":`Definicions de rols d'operador amb nom per als Gateways d'equip. Configurar gateway.roles.default activa l'aplicació de restriccions vinculades al perfil sobre l'accés a les sessions, l'aïllament de l'entorn de proves, els agents i els àmbits d'operador. Les definicions sense un rol per defecte són només un catàleg i mantenen el comportament d'un Gateway sense gateway.roles.`}},"gateway%2Eroles%2Eassignments":{label:{"v1-hv31t1-p":`Assignacions de rols d'operador`},help:{"v1-do2i61-55":`Assignacions declaratives opcionals de rols per als perfils autenticats. Una assignació explícita vàlida feta amb users.setRole té prioritat sobre aquestes correspondències, seguides del rol per defecte.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin":{label:{"v1-wujwr5-u":`Rols d'operador per nom d'usuari de GitHub`},help:{"v1-ecgzr1-95":`Requereix gateway.roles.default, fins i tot per a un mapa buit. Assigna els noms d'usuari de les identitats de GitHub emmagatzemades a la memòria cau als noms dels rols configurats, sense distingir entre majúscules i minúscules després d'eliminar els espais dels extrems. Es rebutgen els noms d'usuari no vàlids, els noms d'usuari normalitzats duplicats i els rols desconeguts. Els perfils sense una identitat de GitHub a la memòria cau utilitzen la seva assignació explícita o el rol per defecte.`}},"gateway%2Eroles%2Eassignments%2EbyGithubLogin%2E*":{label:{"v1-1wr68uf-q":`Rol d'operador del nom d'usuari de GitHub`},help:{"v1-dad5ey-5e":`Nom del rol configurat per a aquest nom d'usuari de GitHub. S'aplica quan el perfil té una identitat de GitHub coincident a la memòria cau i no té cap assignació explícita de rol vàlida. Els canvis s'apliquen en calent quan la recàrrega de la configuració està activada.`}},"gateway%2Eroles%2Edefault":{label:{"v1-12e6yd7-17":`Rol d'operador per defecte (activa l'aplicació de restriccions)`},help:{"v1-18k9r00-7c":`Rol per defecte opcional que activa l'aplicació de restriccions segons els rols amb nom i s'aplica als perfils autenticats sense una assignació vàlida explícita o basada en el nom d'usuari de GitHub. El seu nom ha de coincidir amb una definició configurada. Si s'omet, l'aplicació de restriccions segons els rols amb nom es manté desactivada, encara que hi hagi definicions.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definicions de rols d'operador`},help:{"v1-11qtcgr-6w":`Catàleg no buit de rols amb noms definits per l'administrador que agrupa les polítiques de compartició de sessions, aïllament de l'entorn de proves, accés als agents i àmbits d'operador. Les definicions per si soles no activen l'aplicació de restriccions; configura gateway.roles.default per aplicar rols amb nom als perfils autenticats.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definició de rol d'operador`},help:{"v1-p8tfws-6q":`Un rol d'operador amb nom. Cada definició ha d'indicar explícitament la política de compartició de sessions, els agents permesos per a sessions i execucions, i el límit d'abast de l'operador, i pot exigir aïllament en un entorn de proves per a les sessions noves i una política d'accés mitjançant un connector.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Connector de política d'accés del rol d'operador`},help:{"v1-1gq4q08-9n":`ID exacte opcional del connector la política d'accés a la Passarel·la del qual ha d'autoritzar aquest rol. L'accés es denega quan el connector no hi és, està desactivat, no es pot carregar o no proporciona cap autorització vigent. Els ID de connectors no disponibles continuen sent vàlids a la configuració perquè els rols independents del personal i el propietari de la Passarel·la puguin restablir l'accés. Ometre aquest camp no afegeix cap dependència de connectors.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Agents permesos per al rol d'operador`},help:{"v1-fvun18-4v":`Agents disponibles quan aquest rol crea sessions o inicia execucions: establiu "*" per permetre tots els agents, enumereu els ID dels agents per permetre només aquests agents, o feu servir una llista buida per desactivar totes dues accions.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy":{label:{"v1-1b2q6cc-q":`Política de models del rol d'operador`},help:{"v1-r9daa-e8":`Límit opcional de models per a les sol·licituds d'aquest rol i les seves descendents. Un objecte buit només permet els models principal i alternatius configurats de l'agent d'origen; ometre la política deixa l'accés als models sense canvis. Els àlies dels models es resolen abans d'aplicar la política, i els models denegats no es poden utilitzar en reintents ni com a alternatives. Amb la recàrrega de la configuració activada, els canvis limitats a les polítiques de models dels rols existents s'apliquen quan es confirmen, sense reiniciar la feina permesa. Els altres canvis de rol s'apliquen en calent i tornen a connectar els clients amb l'autorització vigent.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Eallow":{label:{"v1-zdw95f-s":`Models permesos del rol d'operador`},help:{"v1-1dutf3o-8u":`Llista de permisos de substitució opcional amb referències de models, àlies configurats o prefixos amb comodins al final, com ara "provider/*" o "provider/family-*". Si s'omet, s'utilitzen el model principal i els alternatius de l'agent d'origen; una llista buida denega tots els models. El primer model d'origen permès continua sent el predeterminat, seguit dels models permesos explícitament.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2Edeny":{label:{"v1-1hx2vzz-t":`Models exclosos del rol d'operador`},help:{"v1-1kx70ze-7o":`Referències de models, àlies de l'agent d'origen o prefixos amb comodins al final exclosos d'aquest rol. Un patró com ara "provider/family-*" també exclou els membres futurs d'aquesta família. Les exclusions es comparen amb les identitats resoltes dels models i tenen prioritat sobre els models permesos i els de l'agent d'origen.`}},"gateway%2Eroles%2Edefinitions%2E*%2EmodelPolicy%2EsourceAgent":{label:{"v1-8bg4yu-w":`Agent d'origen dels models del rol d'operador`},help:{"v1-yf7mu-62":`Agent el model principal, els models alternatius i els àlies de models del qual defineixen la política de models d'aquest rol. Per defecte, s'utilitza l'agent del sistema o predeterminat configurat, o bé l'únic agent existent. Establiu-lo explícitament quan una Passarel·la amb diversos agents no tingui cap propietari implícit en el context.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Aïllament en un entorn de proves del rol d'operador`},help:{"v1-11bb0ps-6a":`Aïllament d'execució per a les sessions acabades de crear: "inherit" (predeterminat) utilitza la política de l'agent; "required" exigeix permanentment un entorn de proves, fins i tot quan el mode d'entorn de proves de l'agent està desactivat, i bloqueja l'execució si el sistema de rerefons no està disponible.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Límit d'àmbits del rol d'operador`},help:{"v1-1selr2i-4s":`Llista tancada d'àmbits d'operador concedits com a autoritat màxima de connexió d'aquest rol. Els àmbits sol·licitats, aparellats, concedits per identitat i ampliats es restringeixen a la intersecció amb aquesta llista.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Accés del rol d'operador a les sessions`},help:{"v1-hsoiop-45":`Permisos de compartició de sessions concedits a aquest rol per a sessions creades per altres persones autenticades; les sessions pròpies continuen sent accessibles per al seu propietari.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Accés del rol d'operador a altres sessions`},help:{"v1-1pmaa4o-al":`Accés a les sessions d'altres persones: "none" les amaga fins i tot amb pertinença explícita a la sessió, "view" en permet la lectura, "suggest" permet el flux de suggeriments i "write" permet participar-hi sense ser-ne membre. La pertinença explícita a una sessió pot ampliar l'accés "view" o "suggest" per a una sessió concreta. Els creadors de sessions i les connexions amb operator.admin conserven el seu accés a les sessions.`}},"gateway%2Eroles%2Edefinitions%2E*%2EworkerProfiles":{label:{"v1-o0hlzf-t":`Perfils de processos de treball del rol d'operador`},help:{"v1-v6xpap-5r":`Perfils de processos de treball al núvol als quals aquest rol pot enviar explícitament les seves pròpies sessions. Si s'omet o es deixa buit, es denega l'enviament al núvol; els administradors conserven l'accés. La configuració i els trasllats a perfils al núvol continuen sent exclusius dels administradors.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale de la Passarel·la`},help:{"v1-6ar9o-4x":`Configuració de la integració amb Tailscale per a l'exposició mitjançant Serve/Funnel i la gestió del cicle de vida en iniciar o tancar la passarel·la. Manteniu-la desactivada tret que el desplegament depengui intencionadament de l'accés entrant mitjançant Tailscale.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Mode de Tailscale de la Passarel·la`},help:{"v1-6l2099-5a":`Mode de publicació de Tailscale: "off", "serve" o "funnel" per a vies d'exposició privades o públiques. Feu servir "serve" per limitar l'accés a la tailnet i "funnel" només quan calgui que sigui accessible des d'Internet.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Protecció de migració de Funnel extern de Tailscale de la Passarel·la`},help:{"v1-1mntkor-7q":`Protecció de migració obsoleta per a mode='serve'. Si un Funnel extern encara apunta al punt d'escolta habitual de la Passarel·la, OpenClaw deixa l'exposició sense canvis i avisa que només es poden continuar utilitzant els webhooks autenticats mitjançant connectors fins que es configuri l'autenticació amb contrasenya i es migri el mode a 'funnel'.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Terminal de l'operador`},help:{"v1-1qtq5dc-88":`Terminal d'operador disponible per a l'aplicació web i els clients mòbils: un intèrpret d'ordres basat en PTY al host de la passarel·la, restringit a sessions d'operador amb permisos d'administració. S'inicia a l'espai de treball de l'agent de destinació i es denega als agents completament aïllats (sandbox.mode 'all'), en lloc de proporcionar un intèrpret d'ordres del host sense restriccions.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Temps d'espera de la sessió desconnectada del Terminal de l'operador`},help:{"v1-k6qbgr-9e":`Segons que una sessió de terminal es manté activa després de perdre la connexió (suspensió del portàtil, recàrrega de la pàgina), durant els quals es pot reprendre mitjançant terminal.attach amb la sortida recent reproduïda. Establiu-ho a 0 per finalitzar les sessions en el moment que es perdi la connexió. Valor per defecte: 300 (5 minuts). Les sessions desconnectades continuen executant les seves ordres, de manera que convé reduir aquest temps en amfitrions compartits o exposats.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Terminal de l'operador habilitat`},help:{"v1-1nez06v-7p":`Activa el terminal de l'operador per als clients amb abast d'administració (per defecte: true). Això exposa un intèrpret d'ordres al navegador o al mòbil amb l'entorn del procés de la passarel·la; establiu-lo a false per desactivar-lo en desplegaments on els operadors administradors no hagin de tenir accés a un intèrpret d'ordres de l'amfitrió. Els canvis s'apliquen sense reiniciar la Passarel·la.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Intèrpret d'ordres del terminal de l'operador`},help:{"v1-19mfe6t-5i":`Executable de l'intèrpret d'ordres que inicia el terminal de l'operador. Deixeu-lo sense definir per utilitzar l'intèrpret d'ordres d'inici de sessió de l'amfitrió ($SHELL a Unix, %ComSpec% a Windows), o fixeu un intèrpret explícit per mantenir un entorn coherent per a l'operador.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS de la Passarel·la`},help:{"v1-1dx77dq-4z":`Configuració del certificat i de la clau TLS per finalitzar les connexions HTTPS directament al procés de la passarel·la. Utilitzeu certificats explícits en producció i eviteu l'exposició de dades en text pla en xarxes no fiables.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Generació automàtica del certificat TLS de la Passarel·la`},help:{"v1-1ld6uiu-4w":`Genera automàticament un parell local de certificat i clau TLS quan no s'han configurat fitxers explícits. Utilitzeu-lo només en entorns locals o de desenvolupament i substituïu-lo per certificats reals per al trànsit de producció.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Camí de la CA TLS de la Passarel·la`},help:{"v1-andqlu-52":`Camí opcional del paquet de CA per verificar clients o satisfer requisits de cadenes de confiança personalitzades al perímetre de la passarel·la. Utilitzeu-lo quan el desplegament inclogui una PKI privada o cadenes de certificats personalitzades.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Camí del certificat TLS de la Passarel·la`},help:{"v1-1wznaof-4q":`Camí al sistema de fitxers del fitxer de certificat TLS que utilitza la passarel·la quan TLS està activat. Utilitzeu camins de certificats gestionats i manteniu l'automatització de la renovació alineada amb aquesta ubicació.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS de la Passarel·la activat`},help:{"v1-ykhwp0-4o":`Activa la terminació TLS al punt d'escolta de la Passarel·la perquè els clients es connectin directament per HTTPS/WSS. Manteniu-la activada si hi ha exposició directa a Internet o qualsevol límit amb una xarxa no fiable.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Camí de la clau TLS de la Passarel·la`},help:{"v1-15knri0-4i":`Camí del sistema de fitxers al fitxer de clau privada TLS que utilitza la Passarel·la quan TLS està activat. Manteniu restringits els permisos d'aquest fitxer de clau i renoveu la clau segons la vostra política de seguretat.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Política d'exposició d'eines de la Passarel·la`},help:{"v1-1ffol26-5a":`Política de permisos i denegacions d'exposició d'eines a nivell de Passarel·la que pot restringir la disponibilitat d'eines en temps d'execució independentment dels perfils d'agents o eines. Utilitzeu-la per aplicar controls generals d'emergència i reforçar la seguretat en producció.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Llista d'eines permeses de la Passarel·la`},help:{"v1-163khb1-4y":`Llista explícita d'eines permeses a nivell de Passarel·la per quan vulgueu que només hi hagi un conjunt reduït d'eines disponibles en temps d'execució. Utilitzeu-la en entorns restringits on cal controlar estrictament l'abast de les eines.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Llista d'eines denegades de la Passarel·la`},help:{"v1-1lhssnf-4o":`Llista explícita d'eines denegades a nivell de Passarel·la per bloquejar eines de risc encara que les polítiques de nivell inferior les permetin. Utilitzeu regles de denegació per respondre a emergències i reforçar la defensa en profunditat.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR dels servidors intermediaris de confiança de la Passarel·la`},help:{"v1-n5zcvf-4f":`Llista de CIDR/IP permesos dels servidors intermediaris anteriors a la cadena autoritzats a proporcionar capçaleres reenviades d'identitat del client. Manteniu aquesta llista limitada perquè els salts no fiables no puguin suplantar usuaris.`}},"gateway%2Euploads":{label:{"v1-pn01yp-m":`Pujades de fitxers i imatges`},help:{"v1-ger7hh-3a":`Política de pujada de fitxers i imatges dels clients per al Gateway i l'aplicació web. Les baixades i els continguts multimèdia generats pels agents continuen disponibles.`}},"gateway%2Euploads%2Eenabled":{label:{"v1-1m4q5zw-f":`Càrregues activades`},help:{"v1-1tqoi1v-93":`Permet la càrrega de fitxers i imatges del client (valor per defecte: true). Establiu-ho en false per rebutjar els fitxers adjunts, les càrregues a l'espai de treball o al terminal, les càrregues d'avatars i les importacions d'arxius a la Passarel·la, incloses les sol·licituds directes a l'API. Els canvis s'apliquen sense reiniciar. Això no és un entorn aïllat ni una restricció sobre els continguts multimèdia dels canals, les eines dels agents o l'accés de l'operador a l'intèrpret d'ordres.`}},hooks:{label:{"v1-j9ywl7-5":`Ganxos`},help:{"v1-1mzh0ry-5v":`Interfície d'automatització de webhooks entrants per associar esdeveniments externs a accions d'activació o d'agent a OpenClaw. Manteniu-la protegida amb controls explícits de testimoni, sessió i agent abans d'exposar-la fora de les xarxes de confiança.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Identificadors d'agent permesos per als ganxos`},help:{"v1-1imjux7-79":`Llista d'identificadors d'agent efectius permesos als quals es poden adreçar les sol·licituds i les assignacions dels ganxos, inclòs l'encaminament a l'agent per defecte quan s'omet agentId. Feu-la servir per restringir els esdeveniments d'automatització a agents de servei dedicats i limitar els danys si s'exposa un testimoni de ganxo.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Prefixos de clau de sessió permesos per als ganxos`},help:{"v1-b346oh-4r":`Llista de prefixos de clau de sessió acceptats per a les sol·licituds entrants dels ganxos quan estan activades les claus proporcionades pel sol·licitant. Feu servir prefixos específics per evitar la injecció arbitrària de claus de sessió.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Permet la clau de sessió de la sol·licitud als ganxos`},help:{"v1-11n9ps-52":`Permet als sol·licitants proporcionar una clau de sessió a les peticions de ganxo quan és true, cosa que habilita l'encaminament controlat pel sol·licitant. Manteniu-lo en false tret que els integradors de confiança necessitin explícitament una agrupació personalitzada de les sessions.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Clau de sessió predeterminada dels ganxos`},help:{"v1-bzdgkn-57":`Clau de sessió alternativa utilitzada per als lliuraments de ganxos quan una petició no en proporciona cap pels canals permesos. Utilitzeu una clau estable però d'abast limitat per evitar barrejar converses d'automatització no relacionades.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Ganxos habilitats`},help:{"v1-1mixmjf-4n":`Habilita el punt final dels ganxos i el flux d'execució dels mapatges per a les peticions de webhook entrants. Manteniu-lo deshabilitat tret que estigueu encaminant activament esdeveniments externs cap a la passarel·la.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Ganxo de Gmail`},help:{"v1-4cibmt-4r":`Configuració de la integració push de Gmail utilitzada per a les notificacions de Pub/Sub i el servei local opcional de crides de retorn. Sempre que sigui possible, limiteu-la a comptes de Gmail dedicats a l'automatització.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Compte del ganxo de Gmail`},help:{"v1-12l1h96-4v":`Identificador del compte de Google utilitzat per a les operacions de supervisió i subscripció de Gmail en aquesta integració de ganxo. Utilitzeu un compte de correu dedicat a l'automatització per aïllar els permisos operatius.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Permet contingut extern no segur al ganxo de Gmail`},help:{"v1-1w3gdvs-55":`Quan està habilitat, permet que el contingut extern de Gmail amb menys sanejament passi al processament. Manteniu-lo deshabilitat per tenir uns valors predeterminats més segurs i habiliteu-lo només per a fluxos de correu de confiança amb transformacions controlades.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`URL de crida de retorn del ganxo de Gmail`},help:{"v1-19fhn6q-4z":`URL pública de retorn que Gmail o els intermediaris invoquen per lliurar notificacions a aquest flux de processament del hook. Protegiu aquesta URL amb validació de tokens i una exposició de xarxa restringida.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Inclou el cos al hook de Gmail`},help:{"v1-14cf1c3-52":`Quan és true, recupera i inclou el contingut del cos del correu per al mapatge o el processament posterior per part de l'agent. Manteniu-ho en false tret que calgui el text del cos, ja que això augmenta la mida i la sensibilitat de les dades transmeses.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Etiqueta del hook de Gmail`},help:{"v1-9zpdg8-4g":`Filtre opcional d'etiquetes de Gmail que limita quins missatges etiquetats activen esdeveniments del hook. Manteniu els filtres restrictius per evitar saturar les automatitzacions amb correus no relacionats de la safata d'entrada.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Màxim de bytes del cos del hook de Gmail`},help:{"v1-2aaxx1-4b":`Nombre màxim de bytes de dades de Gmail processats per esdeveniment quan includeBody està activat. Manteniu límits conservadors per reduir el cost i el risc de processar missatges massa grans.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Substitució del model del hook de Gmail`},help:{"v1-1var65t-59":`Substitució opcional del model per a les execucions activades per Gmail quan les automatitzacions de la bústia han d'utilitzar un comportament de model específic. Deixeu-ho sense definir per heretar els valors predeterminats de l'agent, tret que les tasques de la bústia requereixin especialització.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Token de notificacions push del hook de Gmail`},help:{"v1-h1vx01-4o":`Token secret compartit obligatori a les crides de retorn del hook de notificacions push de Gmail abans de processar les notificacions. Utilitzeu la substitució amb variables d'entorn i renoveu el token si els punts finals de retorn estan exposats externament.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Interval de renovació del hook de Gmail (min)`},help:{"v1-pr1z9-49":`Interval de renovació en minuts de les subscripcions de seguiment de Gmail per evitar que caduquin. Establiu un interval inferior als terminis de caducitat del proveïdor i superviseu els errors de renovació als registres.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Servidor local del hook de Gmail`},help:{"v1-hom4wq-54":`Bloc de configuració del servidor local de retorn de crida per rebre directament notificacions de Gmail sense una capa d'entrada independent. Activeu-lo només quan aquest procés hagi de gestionar directament el trànsit de webhooks.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Adreça d'escolta del servidor del hook de Gmail`},help:{"v1-55bieu-4d":`Adreça d'escolta del servidor HTTP local de retorn de crida de Gmail que s'utilitza quan se serveixen hooks directament. Limiteu-la a la interfície de bucle local, tret que es requereixi expressament una entrada externa.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Camí del servidor del hook de Gmail`},help:{"v1-1jqhcw4-4h":`Camí HTTP del servidor local de retorn de crida de Gmail on s'accepten les notificacions automàtiques. Manteniu-lo coherent amb la configuració de la subscripció per evitar la pèrdua d'esdeveniments.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Port del servidor del hook de Gmail`},help:{"v1-1yku7dz-43":`Port del servidor HTTP local de retorn de crida de Gmail quan el mode de servei està activat. Utilitzeu un port dedicat per evitar conflictes amb les interfícies de la passarel·la o de control.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Subscripció del hook de Gmail`},help:{"v1-127h8vg-5b":`Subscripció de Pub/Sub que consumeix la passarel·la per rebre notificacions de canvis de Gmail des del tema configurat. Definiu clarament la titularitat de la subscripció perquè diversos consumidors no competeixin de manera inesperada.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale del hook de Gmail`},help:{"v1-7jzidp-4l":`Bloc de configuració de l'exposició de Tailscale per publicar crides de retorn de Gmail mitjançant rutes de Serve/Funnel. Utilitzeu modes de xarxa tailnet privada abans d'habilitar qualsevol via d'accés públic.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Mode de Tailscale per al ganxo de Gmail`},help:{"v1-vhm395-4u":`Mode d'exposició de Tailscale per a les crides de retorn de Gmail: "off", "serve" o "funnel". Utilitzeu "serve" per al lliurament a través d'una xarxa tailnet privada i "funnel" només quan calgui accés des d'Internet públic.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Camí de Tailscale per al ganxo de Gmail`},help:{"v1-fr8qi-4m":`Camí publicat per Tailscale Serve/Funnel per reenviar les crides de retorn de Gmail quan està habilitat. Manteniu-lo coherent amb la configuració del webhook de Gmail perquè les sol·licituds arribin al gestor previst.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Destinació de Tailscale per al ganxo de Gmail`},help:{"v1-1twwxge-47":`Destinació del servei local a la qual Tailscale Serve/Funnel reenvia el trànsit (per exemple, http://127.0.0.1:8787). Utilitzeu destinacions de bucle local explícites per evitar encaminaments ambigus.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Sobreescriptura del raonament del ganxo de Gmail`},help:{"v1-17owk9q-4z":`Sobreescriptura de l'esforç de raonament per a les execucions de l'agent activades per Gmail: "off", "minimal", "low", "medium" o "high". Manteniu valors predeterminats moderats per a les automatitzacions rutinàries de la safata d'entrada per controlar el cost i la latència.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Tema de Pub/Sub del ganxo de Gmail`},help:{"v1-fdm0kn-4t":`Nom del tema de Google Pub/Sub que la supervisió de Gmail utilitza per publicar notificacions de canvis d'aquest compte. Comproveu que la configuració IAM del tema concedeixi a Gmail permís de publicació abans d'habilitar la supervisió.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Ganxos interns`},help:{"v1-piq9k-4v":`Configuració de l'entorn d'execució dels punts d'extensió interns per als gestors d'esdeveniments integrats o personalitzats carregats des de rutes de mòduls. Feu-la servir per a automatitzacions de confiança dins del procés i manteniu l'àmbit de càrrega dels gestors ben delimitat.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Punts d'extensió interns activats`},help:{"v1-1wv0289-4c":`Activa el processament dels punts d'extensió interns i de les entrades configurades en el seu entorn d'execució. Manteniu aquesta opció desactivada tret que hàgiu configurat expressament punts d'extensió interns.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Entrades dels punts d'extensió interns`},help:{"v1-1ovi38l-4o":`Registres d'entrades de punts d'extensió interns configurats que s'utilitzen per registrar gestors concrets de l'entorn d'execució i metadades. Manteniu les entrades explícites i sota control de versions perquè es pugui auditar el comportament en producció.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Carregador de punts d'extensió interns`},help:{"v1-11re5ph-4p":`Configuració del carregador de punts d'extensió interns que controla on es busquen els mòduls dels gestors durant l'inici. Feu servir directoris arrel de càrrega restringits per reduir els conflictes accidentals entre mòduls o l'ocultació d'uns mòduls per altres.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Directoris addicionals dels punts d'extensió interns`},help:{"v1-1xfdqxg-4c":`Directoris addicionals on es busquen mòduls de punts d'extensió interns, a banda de les rutes de càrrega predeterminades. Manteniu aquesta llista mínima i controlada per reduir l'ocultació accidental d'uns mòduls per altres.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Assignacions dels punts d'extensió`},help:{"v1-frhp3v-5i":`Regles d'assignació ordenades que identifiquen les sol·licituds entrants dels punts d'extensió i trien accions d'activació o d'agent, amb encaminament de lliurament opcional. Poseu primer les assignacions específiques per evitar que les regles amb patrons amplis ho capturin tot.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Acció d'assignació del punt d'extensió`},help:{"v1-i2kbzp-4h":`Tipus d'acció del mapatge: "wake" posa un avís a la cua de la sessió propietària, mentre que "agent" inicia un torn d'agent independent. Els avisos de sessió no interrompen el treball actiu.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`ID de l'agent del mapatge del hook`},help:{"v1-l0uioz-4y":`ID de l'agent de destinació per executar el mapatge quan l'encaminament d'accions no ha d'utilitzar els valors predeterminats. Utilitzeu agents d'automatització dedicats per aïllar el comportament del webhook de les sessions interactives de l'operador.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Permet contingut extern no segur en el mapatge del hook`},help:{"v1-1np9426-57":`Quan és true, el contingut del mapatge pot incloure dades de càrregues útils externes menys sanejades en els missatges generats. Manteniu el valor false per defecte i activeu aquesta opció només per a fonts de confiança amb una lògica de transformació revisada.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Canal de lliurament del mapatge del hook`},help:{"v1-oz7pu5-5s":`Substitució del canal de lliurament per a les sortides del mapatge (per exemple, "last", "telegram", "discord", "slack", "signal", "imessage" o "msteams"). Definiu explícitament les substitucions de canal per evitar enviaments accidentals entre canals.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Lliura la resposta del mapatge del hook`},help:{"v1-12tbbam-5o":`Controla si els resultats de l'execució del mapatge es lliuren a una destinació de canal o es processen silenciosament. Desactiveu el lliurament per a les automatitzacions en segon pla que no hagin de publicar cap sortida visible per a l'usuari.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Clau de distribució del mapatge del hook`},help:{"v1-1d593op-7e":`Clau de la matriu de nivell superior de les dades sobre la qual es desplega el mapatge: cada element activa la seva pròpia acció, i les plantilles o transformacions reben unes dades en què la matriu només conté l’element actual. La configuració predefinida de Gmail utilitza forEach: messages perquè les notificacions per lots activin una execució per correu electrònic.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`ID del mapatge del hook`},help:{"v1-q1t4zw-57":`Identificador estable opcional d’una entrada de mapatge de hook, utilitzat per a auditories, resolució de problemes i actualitzacions específiques. Utilitzeu ID únics perquè els registres i les diferències de configuració puguin fer referència als mapatges sense ambigüitats.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Coincidència del mapatge del hook`},help:{"v1-6u73k2-5a":`Objecte que agrupa els predicats de coincidència del mapatge, com ara el camí i l’origen, abans d’aplicar l’encaminament d’accions. Manteniu uns criteris de coincidència específics perquè el trànsit de webhooks no relacionat no activi automatitzacions.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Camí de coincidència del mapatge del hook`},help:{"v1-1d7dc5j-4k":`Condició de coincidència del camí per a un mapatge de hook, que normalment es compara amb el camí de la sol·licitud entrant. Utilitzeu-la per separar el comportament de les automatitzacions segons les famílies de camins dels punts finals de webhook.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Origen de coincidència del mapatge del hook`},help:{"v1-1nw7um7-4v":`Condició de coincidència de l’origen per a un mapatge de hook, establerta habitualment per metadades fiables dels sistemes anteriors o per la lògica de l’adaptador. Utilitzeu identificadors d’origen estables perquè l’encaminament es mantingui igual en els reintents.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Plantilla de missatge del mapatge del hook`},help:{"v1-m0lqv5-5t":`Plantilla per sintetitzar l'entrada estructurada del mapatge en el contingut final del missatge enviat a la ruta de l'acció de destinació. Feu que les mateixes entrades produeixin el mateix missatge perquè l'anàlisi i el comportament posteriors es mantinguin estables.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Substitució del model del mapatge del hook`},help:{"v1-10qyo4j-5e":`Substitució opcional del model per a les execucions activades pel mapatge quan l'automatització hagi d'utilitzar un model diferent del predeterminat de l'agent. Utilitzeu-la amb moderació perquè el comportament es mantingui previsible entre les execucions del mapatge.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Nom del mapatge del hook`},help:{"v1-zrd9tn-4v":`Nom de visualització llegible del mapatge, utilitzat en els diagnòstics i les interfícies de configuració per a operadors. Feu servir noms concisos i descriptius perquè la intenció de l'encaminament sigui evident durant la revisió d'incidents.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Clau de sessió del mapatge del hook`},help:{"v1-lfnt1n-58":`Substitució explícita de la clau de sessió dels missatges lliurats pel mapatge per controlar la continuïtat del fil. Utilitzeu claus estables amb un àmbit definit perquè els esdeveniments repetits es correlacionin sense barrejar-se amb converses no relacionades.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Mode de sessió del mapatge del hook`},help:{"v1-1ggtdze-5k":`Controla la continuïtat de la sessió del mapatge: "isolated" inicia una sessió d'execució nova, mentre que "persistent" reutilitza la sessionKey resolta. Manteniu el mode aïllat tret que la integració necessiti expressament un context durador.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Plantilla de text del mapatge del hook`},help:{"v1-1rg732b-4y":`Plantilla alternativa de només text que s'utilitza quan no es vol o no s'admet la representació de contingut enriquit. Utilitzeu-la per proporcionar un resum breu i coherent per als entorns d'entrega de xat.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Substitució del nivell de raonament de l'assignació del hook`},help:{"v1-17hq8me-57":`Substitució opcional de l'esforç de raonament per a les execucions activades per assignacions, que permet ajustar l'equilibri entre la latència i la profunditat del raonament. Manteniu un nivell baix o mínim per als hooks amb un volum elevat, tret que calgui clarament un raonament més profund.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Temps d'espera de l'assignació del hook (s)`},help:{"v1-1r44ox2-4i":`Temps màxim permès per executar l'acció de l'assignació abans d'aplicar la gestió del temps d'espera exhaurit. Utilitzeu límits més estrictes per a les fonts de webhooks amb un volum elevat per evitar acumulacions a la cua.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Destinació d'entrega de l'assignació del hook`},help:{"v1-1p7928e-55":`Identificador de destinació dins del canal seleccionat quan les respostes de l'assignació s'han d'encaminar a una destinació fixa. Verifiqueu els formats de destinació específics del proveïdor abans d'activar les assignacions en producció.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformació de l'assignació del hook`},help:{"v1-118nw83-5j":`Bloc de configuració de la transformació que defineix el preprocessament mitjançant un mòdul o una exportació abans de gestionar l'acció de l'assignació. Utilitzeu només transformacions de rutes de codi revisades i manteniu un comportament reproduïble perquè l'automatització també ho sigui.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Exportació de la transformació del hook`},help:{"v1-atn8v-4b":`Exportació amb nom que s'ha d'invocar des del mòdul de transformació; si s'omet, s'utilitza l'exportació per defecte del mòdul. Definiu-la quan un fitxer contingui diversos gestors de transformació.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Mòdul de transformació del hook`},help:{"v1-56futq-4v":`Camí relatiu del mòdul de transformació carregat des de hooks.transformsDir per reescriure les càrregues útils entrants abans del lliurament. Manteniu els mòduls locals, revisats i lliures de patrons de recorregut de directoris.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Mode d'activació de l'assignació del hook`},help:{"v1-1vp6cpn-6m":`Mode de programació de l'activació: "now" posa immediatament un torn de sessió a la cua, mentre que "next-heartbeat" assigna l'avís a la següent automatització programada apta per a aquella sessió. Les activacions ajornades requereixen una automatització habilitada que pugui rebre l'avís.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Camí del punt de connexió dels hooks`},help:{"v1-1l9ijzv-4u":"Camí HTTP utilitzat pel punt de connexió dels hooks (per exemple, `/hooks`) al servidor de control de la passarel·la. Utilitzeu un camí difícil d'endevinar i combineu-lo amb la validació de tokens per a una defensa en profunditat."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Predefinicions dels hooks`},help:{"v1-dp8m0l-4v":`Paquets de predefinicions de hooks amb nom que s'apliquen durant la càrrega per establir les assignacions estàndard i el comportament per defecte. Feu explícit l'ús de predefinicions perquè els operadors puguin auditar quines automatitzacions estan actives.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Token d'autenticació dels hooks`},help:{"v1-1ihf6mv-82":`Token de portador compartit que el punt d'entrada dels hooks comprova per autenticar les sol·licituds abans d'executar les assignacions. Tracteu-ne els posseïdors com a emissors de plena confiança per a la interfície d'entrada dels hooks, no com un rol separat sense drets de propietari. Utilitzeu la substitució de variables d'entorn i renoveu el token periòdicament quan els punts de connexió dels webhooks siguin accessibles des d'Internet.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Directori de transformacions dels hooks`},help:{"v1-1ayj9p0-4t":`Directori base dels mòduls de transformació dels hooks als quals fan referència els camins transform.module dels mapatges. Utilitzeu un directori de repositori controlat perquè les importacions dinàmiques es puguin revisar i siguin previsibles.`}},logging:{label:{"v1-rq08xq-7":`Registre`},help:{"v1-11an9pb-5e":`Controls del comportament del registre per a la gravetat, les destinacions de sortida, el format i l'ocultació de dades sensibles. Manteniu els nivells i l'ocultació prou estrictes per a producció, tot conservant informació de diagnòstic útil.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Registre d'auditoria`},help:{"v1-1lauvy2-6w":`Historial d'auditoria limitat que només conté metadades perquè l'operador el revisi. Els registres d'execucions i d'eines estan activats per defecte; les metadades del cicle de vida dels missatges requereixen una activació voluntària independent perquè són sensibles des del punt de vista de la privadesa. El procés d'escriptura en segon pla fa el possible per registrar les dades, però no és un arxiu de compliment normatiu sense pèrdues.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Registre d'auditoria activat`},help:{"v1-snknxb-4v":`Registra els nous esdeveniments d'auditoria d'execucions, d'eines i de missatges, si estan activats. Valor per defecte: true. Els canvis s'apliquen immediatament; les escriptures acceptades es completen i les files conservades es poden continuar consultant fins que caduquin.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Auditoria de la identitat d'execució`},help:{"v1-1ucirwv-5b":`Conserva informació limitada sobre l'atribució de la identitat d'execució per inspeccionar execucions concretes. Valor per defecte: false. Requereix logging.audit.enabled i s'aplica a les execucions admeses a partir d'aleshores; els contextos existents no canvien.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Abast de l'auditoria de missatges`},help:{"v1-1yg4lc3-76":`Controla els registres del cicle de vida dels missatges sense contingut: "off" (per defecte), "direct" només per a converses directes conegudes, o "all" per a converses directes, de grup, de canal i de tipus desconegut. Requereix logging.audit.enabled. Els canvis s'apliquen als esdeveniments posteriors del cicle de vida.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Nivell de registre de la consola`},help:{"v1-16badbd-5u":`Llindar de registre específic de la consola: "silent", "fatal", "error", "warn", "info", "debug" o "trace" per controlar la sortida del terminal. Feu-lo servir per reduir la sortida de la consola local i mantenir, si cal, un registre més detallat en fitxers.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Estil de registre de la consola`},help:{"v1-d7u0iq-3q":`Estil del format de sortida de la consola: "pretty" o "json". Feu servir json per a fluxos de processament automatitzat i pretty per a fluxos de treball al terminal orientats a persones.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Camí del fitxer de registre`},help:{"v1-16gaitv-4w":`Camí opcional d'un fitxer per desar la sortida del registre, a més del registre de la consola o en lloc seu. Feu servir un camí gestionat amb permisos d'escriptura i ajusteu la retenció i la rotació a la vostra política operativa.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Nivell de registre`},help:{"v1-1r5yku0-5o":`Llindar principal del nivell de registre per a la sortida del sistema de registre en temps d'execució: "silent", "fatal", "error", "warn", "info", "debug" o "trace". Manteniu "info" o "warn" en producció i feu servir debug/trace només durant la investigació de problemes.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Patrons d'ocultació personalitzats`},help:{"v1-11x24rh-8c":`Les cadenes d'expressions regulars personalitzades substitueixen la llista de cadenes per defecte dels registres i dels diagnòstics. Les proteccions integrades per als cossos de formulari, les dades d'autenticació estructurades i les claus AWS sense format s'apliquen sempre. Els arguments de les eines, els resultats i l'historial del xat no s'oculten. Feu-les servir per emmascarar tokens i identificadors específics del desplegament a la sortida de diagnòstic.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Definicions globals de servidors MCP gestionades per OpenClaw. L'OpenClaw integrat i altres adaptadors d'entorns d'execució poden utilitzar aquests servidors sense desar-los a la configuració del projecte pròpia de l'entorn d'execució.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP Apps`},help:{"v1-amyd91-38":`Compatibilitat amb la interfície d'usuari de MCP Apps. Quan està activada, els servidors MCP configurats poden proporcionar vistes HTML interactives per als resultats de les seves eines.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps activat`},help:{"v1-ghqy98-3w":`Renderització de MCP Apps i pont entre aplicació i servidor d'activació voluntària. Manteniu aquesta opció desactivada tret que confieu en els servidors MCP configurats que proporcionen recursos d'interfície d'usuari de les aplicacions.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Origen de l'entorn aïllat de MCP Apps`},help:{"v1-5lqj7v-6s":`Origen HTTP(S) públic dedicat opcional per a MCP Apps. Utilitzeu-lo darrere d'un servidor intermediari invers o d'un terminador TLS i reenvieu-ne el trànsit només al port configurat de l'entorn aïllat de MCP Apps. Ha de ser diferent de l'origen de l'aplicació web i no ha de servir contingut que requereixi autenticació.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Port de l'entorn aïllat de MCP Apps`},help:{"v1-1b8n71l-4p":`Port d'escolta dedicat de l'entorn aïllat de MCP Apps. Per defecte, és el port de la Passarel·la més u. Establiu un port lliure quan un altre servei local o perfil de la Passarel·la ja utilitzi aquest port.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Servidors MCP`},help:{"v1-157ozoz-42":`Definicions de servidors MCP amb nom. OpenClaw les desa a la seva pròpia configuració i els adaptadors d'execució decideixen quins transports s'admeten en temps d'execució.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Autenticació del servidor MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Certificat del client MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Clau del client MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Certificat del client MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Clau del client MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Projecció MCP de Codex`},help:{"v1-slcmq1-6x":`Metadades de projecció d'OpenClaw només per als fils de Codex app-server. No afecten les sessions ACP ni la configuració genèrica de l'entorn d'execució de Codex. Ometeu aquest bloc per mantenir el servidor disponible per a tots els agents de Codex app-server amb el comportament d'aprovació MCP predeterminat de Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Agents MCP de Codex`},help:{"v1-1i6v0fm-6a":`Identificadors opcionals i no buits d'agents d'OpenClaw que han de rebre aquest servidor MCP a la configuració dels fils de Codex app-server. Les llistes sense identificadors d'agent vàlids no concedeixen cap accés; si s'ometen, el servidor es projecta per a tots els agents de Codex app-server.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Aprovació d'eines MCP de Codex`},help:{"v1-1xql0qr-3d":`Forma nativa de Codex per al mateix mode d'aprovació d'eines MCP per servidor. És preferible utilitzar defaultToolsApprovalMode a la configuració d'OpenClaw.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Aprovació d'eines MCP de Codex`},help:{"v1-y5vsqq-3s":`Mode opcional d'aprovació d'eines MCP de Codex per a aquest servidor: "auto", "prompt" o "approve". Utilitzeu-lo només per a servidors MCP en què confieu expressament.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Temps d'espera de connexió MCP (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Servidor MCP habilitat`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth de MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Perfil d'autenticació OAuth de MCP`},help:{"v1-fcrb4u-5z":`Identificador del perfil d'autenticació amb capacitat de renovació que s'utilitza per injectar el testimoni de portador actual en aquest servidor MCP remot. Quan s'estableix, OpenClaw resol i renova el perfil en temps d'execució i no transmet les dades de renovació als components posteriors.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL de metadades del client OAuth de MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Identitat OAuth de MCP`},help:{"v1-1ie6ys7-59":`Titularitat de les credencials OAuth d'aquest servidor. Ometeu aquest camp o utilitzeu "shared" per a les credencials gestionades per l'operador; utilitzeu "per-requester" perquè cada remitent autenticat pugui connectar el seu propi compte.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`URL de redirecció OAuth de MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Àmbit OAuth de MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Temps d'espera de sol·licituds MCP (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Verificació TLS de MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Verificació TLS de MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Crides paral·leles a eines MCP`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Crides paral·leles a eines MCP`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Selecció d'eines MCP`},help:{"v1-10poyzb-4v":`Selecció d'eines MCP per servidor. Feu servir include per exposar només les eines MCP seleccionades pel nom, o exclude per amagar-les. Les entrades accepten noms exactes i patrons simples amb el comodí '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Eines MCP excloses`},help:{"v1-ijrc5y-1u":`Noms exactes d'eines MCP o patrons simples amb el comodí '*' per amagar eines d'aquest servidor.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Eines MCP incloses`},help:{"v1-89fdfq-3o":`Noms exactes d'eines MCP o patrons simples amb el comodí '*' per exposar eines d'aquest servidor. Si s'omet, totes les eines del servidor es poden seleccionar, tret de les excloses.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL d'inactivitat de la sessió MCP (ms)`},help:{"v1-j9si74-87":`Eliminació opcional per inactivitat dels entorns d'execució MCP de sessió d'OpenClaw, en mil·lisegons. Si no s'estableix o és 0, els entorns d'execució es mantenen actius fins a la neteja de la sessió o l'aturada de la Passarel·la. Els valors positius s'arrodoneixen a la baixa; les reserves actives i les adquisicions pendents impedeixen l'eliminació. Els entorns vinculats a una execució es continuen retirant quan finalitza la seva execució única.`}},memory:{label:{"v1-oopaku-6":`Memòria`},help:{"v1-1wlx40m-13":`Configuració de la memòria integrada (global).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Mode de citacions de la memòria`},help:{"v1-1q6dxr5-4u":`Controla la visibilitat de les citacions a les respostes: "auto" mostra les citacions quan són útils, "on" les mostra sempre i "off" les amaga. Manteniu "auto" per obtenir una relació senyal-soroll equilibrada per defecte.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Cerca a la memòria`},help:{"v1-1ukbud1-25":`Cerca vectorial a MEMORY.md i memory/*.md (admet personalitzacions per agent).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Memòria cau de vectors de la cerca de memòria`},help:{"v1-d8h2e4-5b":`Desa a la memòria cau d'SQLite els vectors calculats dels fragments perquè la reindexació i les actualitzacions incrementals siguin més ràpides (per defecte: true). Manteniu aquesta opció activada tret que investigueu la correcció de la memòria cau o vulgueu minimitzar l'ús del disc.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Tipus d'entrada de documents de la cerca de memòria`},help:{"v1-1ui33sv-5f":"Valor opcional d'`input_type` específic del proveïdor per als vectors de memòria dels documents i de la indexació. Feu-lo servir amb punts de connexió de vectorització asimètrica compatibles amb OpenAI que requereixin una etiqueta de passatge o de document."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Activa la cerca de memòria`},help:{"v1-14f11b9-4t":`Interruptor principal per a la indexació i la recuperació de la cerca de memòria en aquest perfil d'agent. Manteniu-lo activat per a la recuperació semàntica i desactiveu-lo quan vulgueu respostes completament sense estat.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Índex de sessions de la cerca de memòria (experimental)`},help:{"v1-1y8ykw2-3b":`Indexa l'historial de xat per a la cerca a la memòria. Manteniu aquesta configuració avançada quan l'herència de la recuperació de context difereixi entre el nivell arrel i el de cada agent.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Camins de memòria addicionals`},help:{"v1-ojqokq-7i":`Afegeix directoris o fitxers .md addicionals a l'índex de memòria, a més dels fitxers de memòria predeterminats. Les entrades poden ser cadenes de camí o objectes amb un patró glob relatiu a l'arrel. Quan la memòria multimodal està activada, els fitxers d'imatge o d'àudio coincidents dins d'aquests camins també es poden indexar.`}},"memory%2Esearch%2EextraPaths%2E*%2Eevergreen":{label:{"v1-1pdtd1w-r":`Camí addicional de Memòria sempre vigent`},help:{"v1-5y3z66-5f":`Exclou els fitxers de referència coincidents dels camins addicionals de la pèrdua de rellevància temporal basada en la data de modificació del sistema de fitxers. Això només canvia la classificació per actualitat; no fa que el contingut sigui fiable, no li dona prioritat ni en canvia la procedència.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Camí addicional de Memòria`},help:{"v1-b9mbq8-3m":`Defineix el directori o fitxer de memòria addicional. Els camins relatius es resolen des de l'espai de treball de l'agent; les entrades que apunten directament a fitxers s'indexen exactament tal com s'indiquen.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Patró del camí addicional de Memòria`},help:{"v1-j8br1v-4e":`Limita una entrada de directori als fitxers compatibles que coincideixin amb aquest patró glob relatiu a l'arrel, per exemple "runbooks/**/*.md". Ometeu-lo per explorar recursivament tots els fitxers compatibles.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Alternativa de cerca de Memòria`},help:{"v1-1r6368w-6p":`Proveïdor alternatiu que s'utilitza quan fallen les representacions vectorials del proveïdor principal: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" o "none". Configureu una alternativa real per garantir la fiabilitat en producció; utilitzeu "none" només si preferiu errors explícits.`}},"memory%2Esearch%2EinputFormat":{label:{"v1-1qisc0t-q":`Format d'entrada de cerca de Memòria`},help:{"v1-xus8vr-b2":`Parella opcional de prefixos de text literal per a les consultes i els documents dels quals es generen representacions vectorials, com ara { query: "query: ", document: "passage: " }. Substitueix el format automàtic del model, també per als àlies de models. Calen totes dues cadenes; es conserven els espais i els salts de línia, i les cadenes buides seleccionen text sense format. Un valor de queryInstruction no buit té prioritat per a les consultes. Canviar el prefix dels documents requereix tornar a indexar.`}},"memory%2Esearch%2EinputFormat%2Edocument":{label:{"v1-ml4fv9-t":`Prefix dels documents de cerca a la Memòria`},help:{"v1-m9hsjw-4q":`Prefix literal per a les representacions vectorials dels documents. Una cadena buida selecciona el text del document sense processar. Canviar aquest prefix modifica la identitat de l'índex i de la memòria cau de representacions vectorials i requereix tornar a indexar.`}},"memory%2Esearch%2EinputFormat%2Equery":{label:{"v1-16lu8lu-q":`Prefix de les consultes de cerca a la Memòria`},help:{"v1-hxaub1-3u":`Prefix literal per a les representacions vectorials de les consultes. S'utilitza tret que s'estableixi un valor no buit de queryInstruction; una cadena buida desactiva el format automàtic de les consultes.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Tipus d'entrada de cerca a la Memòria`},help:{"v1-26vbwe-5u":"Utilitzeu aquest valor opcional `input_type`, específic del proveïdor, només quan la mateixa etiqueta s'hagi d'aplicar tant a les sol·licituds de representacions vectorials de consultes com a les de documents. Per als proveïdors asimètrics, és preferible utilitzar queryInputType i documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Camí del model local de representacions vectorials`},help:{"v1-13ymbnt-5q":"Especifica l'origen del model local de representacions vectorials per a la cerca local a la Memòria, com ara el camí d'un fitxer GGUF o un URI `hf:`. Utilitzeu-lo només quan provider sigui `local` i verifiqueu la compatibilitat del model abans de reconstruir índexs grans."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Model de cerca a la Memòria`},help:{"v1-11pohrl-59":`Model de representacions vectorials alternatiu que utilitza el proveïdor de Memòria seleccionat quan cal un model diferent del predeterminat. Establiu-lo només quan necessiteu ajustar explícitament la qualitat de recuperació o el cost més enllà dels valors predeterminats del proveïdor.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Cerca multimodal a la Memòria`},help:{"v1-1jn02s-9e":'Configuració opcional de memòria multimodal per indexar fitxers d\'imatge i àudio de les rutes addicionals configurades. Manteniu aquesta opció desactivada tret que el model de representacions vectorials admeti explícitament representacions entre modalitats, i establiu `memory.search.fallback` a "none" mentre estigui activada. Durant la indexació, els fitxers coincidents es carreguen al proveïdor remot de representacions vectorials configurat.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Activa la cerca multimodal a la memòria`},help:{"v1-1dk5d7o-7e":`Activa la indexació d'imatges i àudio a la memòria des d'extraPaths. Actualment requereix Gemini embedding-2, manté les arrels de memòria predeterminades limitades a Markdown, desactiva els proveïdors alternatius de cerca a la memòria i carrega el contingut binari coincident al proveïdor remot de representacions vectorials configurat.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Màxim de bytes per fitxer per a la cerca multimodal a la memòria`},help:{"v1-1mmdrvk-5d":`Estableix el nombre màxim de bytes permès per fitxer multimodal; si se supera, el fitxer s'omet durant la indexació de la memòria. Feu servir aquest límit per reduir el cost de càrrega i la latència d'indexació, o augmenteu-lo per a clips d'àudio curts d'alta qualitat.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modalitats de cerca multimodal a la memòria`},help:{"v1-alp4vh-4l":`Selecciona quins tipus de fitxers multimodals s'indexen des d'extraPaths: "image", "audio" o "all". Limiteu aquesta selecció per evitar indexar involuntàriament grans col·leccions de fitxers binaris.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Dimensionalitat de sortida de la cerca a la memòria`},help:{"v1-jx51wj-dm":"Sobreescriptura de la mida del vector de sortida específica del proveïdor per a les representacions vectorials de memòria. Els models Gemini admeten entre 128 i 3072 dimensions i recomanen 768, 1536 o 3072; les famílies de Bedrock, com ara Titan V2, Cohere V4 i Nova, ofereixen les seves pròpies mides permeses. Els punts de connexió compatibles amb OpenAI la reben com a `dimensions` i han de retornar vectors exactament d'aquesta mida. Les representacions vectorials GGUF locals gestionades es trunquen i es normalitzen localment. Preveieu una reindexació completa quan la canvieu, perquè les dimensions dels vectors emmagatzemats han de mantenir-se coherents."}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Proveïdor de cerca a la Memòria`},help:{"v1-5evseb-71":`Selecciona el motor de representacions vectorials utilitzat per crear i consultar vectors de memòria. El valor per defecte és "openai"; establiu "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" o "local" si voleu un altre motor.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Nombre màxim de resultats de cerca a la Memòria`},help:{"v1-13ekath-4x":`Nombre màxim de coincidències de memòria retornades per la cerca abans de reordenar-les i inserir-les a la instrucció. Augmenteu-lo per recuperar més informació o reduïu-lo per obtenir instruccions més concises i respostes més ràpides.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Puntuació mínima de cerca a la Memòria`},help:{"v1-1ww231l-4v":`Llindar mínim de puntuació de rellevància per incloure resultats de memòria a la sortida final de recuperació. Augmenteu-lo per reduir les coincidències febles o irrellevants, o reduïu-lo quan necessiteu una recuperació més permissiva.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Tipus d'entrada de consulta de cerca a la Memòria`},help:{"v1-831yrv-4q":"Valor opcional d’`input_type` específic del proveïdor per als vectors de memòria en el moment de la consulta. Feu-lo servir amb punts de connexió de vectorització asimètrica compatibles amb OpenAI que requereixin una etiqueta de consulta."}},"memory%2Esearch%2EqueryInstruction":{label:{"v1-izdliq-v":`Instrucció de consulta de cerca a la memòria`},help:{"v1-19u8npy-b1":`Prefix literal opcional per als vectors de consulta, com ara "search_query: ". Incloeu-hi els espais o salts de línia necessaris. Els valors no buits substitueixen inputFormat.query i el format automàtic de les consultes; els valors no definits o buits utilitzen inputFormat.query si està definit i, en cas contrari, els valors predeterminats del proveïdor. Els documents i la identitat de l’índex no canvien, de manera que no cal tornar a indexar. Una substitució buida per a un agent elimina la instrucció heretada.`}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Recorda entre converses`},help:{"v1-1r9xto0-7s":`Utilitza context rellevant d'altres converses privades d'aquest agent mitjançant la recuperació protegida de xats. Només s'activa per defecte quan session.dmScope global no està definit o és "main" i cap vinculació no substitueix l'àmbit dels missatges directes; qualsevol aïllament configurat dels missatges directes el desactiva per defecte. Un valor explícit true o false sempre té prioritat.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Clau d’API de vectorització remota`},help:{"v1-nfuuu-62":`Proporciona una clau d’API dedicada per a les crides de vectorització remota utilitzades en la indexació de memòria i la vectorització en el moment de la consulta. Feu-la servir quan la vectorització de memòria hagi d’utilitzar credencials diferents de les predeterminades globals o de les variables d’entorn.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`URL base de vectorització remota`},help:{"v1-1ugvqgt-5p":`Substitueix el punt de connexió de l'API de vectorització, com ara un servidor intermediari compatible amb OpenAI o un URL base personalitzat de Gemini. Feu-ho servir només quan encamineu les peticions a través de la vostra pròpia passarel·la o del punt de connexió d'un proveïdor; en cas contrari, manteniu els valors predeterminats del proveïdor.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Vectorització remota per lots activada`},help:{"v1-1fehqi-5x":`Activa les API per lots del proveïdor per a les tasques de vectorització quan són compatibles (OpenAI/Gemini), cosa que millora el rendiment en indexacions de gran volum. Manteniu aquesta opció activada tret que estigueu depurant errors de processament per lots del proveïdor o executant càrregues de treball molt petites.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Capçaleres de vectorització remota`},help:{"v1-1uic0kd-5i":`Afegeix capçaleres HTTP personalitzades a les peticions de vectorització remota i les combina amb les predeterminades del proveïdor. Feu-ho servir per a les capçaleres d'autenticació del servidor intermediari i d'encaminament per inquilí, i limiteu els valors al mínim per evitar filtracions de metadades sensibles.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Fonts de cerca de memòria`},help:{"v1-1xxndig-4q":`Tria quines fonts s'indexen: "memory" llegeix MEMORY.md i els fitxers de memòria, i "sessions" inclou l'historial de xat. Manteniu ["memory"] tret que necessiteu recuperar context de xats anteriors.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Índex vectorial de cerca de memòria`},help:{"v1-fbybkj-37":`Controla l'índex semàntic de sqlite-vec. Manteniu aquesta configuració avançada de substitució quan les polítiques vectorials globals i les de cada agent siguin diferents.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Camí de l'extensió vectorial de cerca de memòria`},help:{"v1-1hysv5q-58":"Substitueix el camí de la biblioteca de l'extensió sqlite-vec detectat automàticament (`.dylib`, `.so` o `.dll`). Utilitzeu aquesta opció quan l'entorn d'execució no pugui trobar sqlite-vec automàticament o quan vulgueu fixar una compilació de funcionament provat."}},messages:{label:{"v1-1wwzqad-8":`Missatges`},help:{"v1-i5k0iw-5k":`Infraestructura de missatges i valors predeterminats compartits entre agents. Les claus del mateix nivell a l'arrel gestionen la infraestructura i els valors predeterminats compartits entre agents; agents.defaults gestiona el comportament del bucle de l'agent; les entrades dels agents poden substituir qualsevol d'aquests valors quan s'admeti.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji de reacció de confirmació`},help:{"v1-1iip0zs-1x":`Reacció amb emoji utilitzada per confirmar la recepció dels missatges entrants (si es deixa buit, es desactiva).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Àmbit de les reaccions de confirmació`},help:{"v1-1jvdg5n-7s":`Quan s'han d'enviar reaccions de confirmació ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" confirma els missatges de grup que esmenten l'agent, tant si el grup exigeix mencions com si no; "group-all" confirma tots els missatges de grup. "off"/"none" desactiva completament les reaccions de confirmació.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Regles del xat de grup`},help:{"v1-chqsvh-4l":`Controls de gestió dels missatges de grup, inclosos els activadors per menció i la mida de la finestra de l'historial. Manteniu els patrons de menció específics perquè els canals de grup no s'activin amb cada missatge.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Límit de l'historial del grup`},help:{"v1-1mkbpw-9k":`Nombre màxim de missatges anteriors del grup que es carreguen com a context per torn a les sessions de grup. Feu servir valors més alts per obtenir més continuïtat, o valors més baixos per obtenir respostes més ràpides i econòmiques. L'historial automàtic d'entrada està limitat a 200 missatges. El valor màxim d'un enter JSON selecciona la finestra predeterminada del canal (50 per a l'historial compartit del grup), no una finestra il·limitada.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Patrons de mencions al grup`},help:{"v1-i7h7qc-6f":`Patrons d'expressions regulars segurs que no distingeixen entre majúscules i minúscules, utilitzats per detectar mencions explícites o frases d'activació als xats de grup. Feu servir patrons precisos per reduir els falsos positius en canals amb molt de trànsit; els patrons no vàlids o insegurs amb repeticions imbricades s'ignoren.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Missatges entrants del grup sense menció`},help:{"v1-17wef8h-5f":`Controla com s'envien les converses de grup sense menció quan l'escolta és permanent. "user_request" les tracta com una sol·licitud de l'usuari; "room_event" les envia com a context silenciós en què la sortida visible requereix l'eina de missatges.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Respostes visibles del grup`},help:{"v1-qa4z1s-aa":`Substitueix les respostes originals redactades pel model a les converses de grup o canal. El valor predeterminat és "automatic" quan no s'ha definit cap política global de respostes visibles. "message_tool" requereix message(action=send) per a la sortida normal de l'assistent i el contingut multimèdia genèric de les eines; la sortida d'execució explícitament gestionada per l'amfitrió es pot continuar lliurant, excepte en el cas dels esdeveniments ambientals de la sala. "automatic" publica les respostes normals com abans.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Retard d'agrupació dels missatges entrants`},help:{"v1-ebyu5x-4a":`Configuració del retard d'agrupació dels missatges entrants directes que s'aplica abans d'iniciar el processament de la cua o del torn. Configura-la per gestionar ràfegues ràpides de missatges d'un mateix remitent segons el proveïdor.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Retard d'agrupació d'entrada per canal (ms)`},help:{"v1-wbz54j-4g":`Valors específics del retard d'agrupació d'entrada per canal, en mil·lisegons, amb l'identificador del proveïdor com a clau. Utilitza'ls quan alguns proveïdors enviïn fragments de missatges amb més freqüència que d'altres.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Retard d'agrupació de missatges entrants (ms)`},help:{"v1-1616yo2-7w":`Interval de silenci (ms) per agrupar missatges entrants ràpids d'un mateix remitent. Telegram utilitza 300 ms per defecte quan no s'ha establert cap valor específic global ni de canal; els altres canals utilitzen 0 per defecte. El valor zero desactiva l'agrupació ordinària de ràfegues, però Telegram continua reunint els fragments de missatges llargs propers al límit.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Cua d'entrada`},help:{"v1-hm2o31-48":`Estratègia de cua per als missatges entrants que arriben mentre hi ha una execució de sessió activa. Utilitza-la per ajustar la reorientació, els seguiments ajornats, l'agrupació o la interrupció.`}},"messages%2Equeue%2EallowCollaborativeSteering":{label:{"v1-95t3u6-s":`Permet la reorientació col·laborativa`},help:{"v1-1pyzwb-ip":`Permet que les aportacions humanes admeses a la mateixa conversa reorientin el torn actiu mantenint-ne la identitat i els permisos preparats, fins i tot quan l'autor té menys permisos (per defecte: true). Les aportacions de la WebUI amb credencials compartides i dels canals també poden continuar exactament la mateixa sessió activa. Quan el valor és false, aquesta excepció requereix autoritat vigent d'administrador de la WebUI i de propietari del canal; la continuïtat personal verificada també continua disponible. En cas contrari, collaborativeSteeringFallback selecciona un torn en cua sense notificació i propietat del sol·licitant (queue) o un rebuig estricte (reject). Es continuen aplicant l'accés actual, l'autoritat d'execució en temps real, les comprovacions de la configuració d'execució, els modes de cua i l'autorització per reorientar entre sessions.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Mode de cua per canal`},help:{"v1-1vbyy4u-5q":`Substitucions del mode de cua per canal, identificades per l'ID del canal, inclosos els canals de connectors (per exemple, discord, telegram, x). Utilitzeu-ho quan el patró de trànsit d'un canal requereixi un comportament diferent del dels valors predeterminats globals.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Capacitat de la cua`},help:{"v1-16ql8c7-4j":`Nombre màxim d'elements entrants que es retenen a la cua abans d'aplicar la política de descart. El valor predeterminat és 20; manteniu límits acotats als canals amb molta activitat perquè l'ús de memòria sigui previsible.`}},"messages%2Equeue%2EcollaborativeSteeringFallback":{label:{"v1-3k0wft-v":`Alternativa a la reorientació col·laborativa`},help:{"v1-peu9fu-8i":`Què passa quan una altra persona no pot reorientar el torn perquè la reorientació col·laborativa està desactivada: "queue" (per defecte) executa la seva aportació com un torn independent sense cap avís d'estat; "reject" manté el rebuig estricte i requereix una nova sol·licitud /followup. No activa la reorientació col·laborativa ni eludeix les comprovacions d'accés.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Retard d'agrupació alternatiu de la cua per canal (ms)`},help:{"v1-1w7gk9b-54":`Valors de retard d'agrupació específics per canal per al comportament de la cua, indexats per l'ID del canal, inclosos els canals dels connectors. Utilitzeu-los per ajustar la gestió de ràfegues de manera independent en interfícies de xat amb ritmes diferents.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Estratègia de descart de la cua`},help:{"v1-ydb2rw-6m":`Estratègia de descart quan se supera el límit de la cua. "summarize" descarta les entrades més antigues, però en conserva resums compactes; "old" descarta les més antigues sense resums; "new" rebutja l'element més recent. Utilitzeu "summarize" per a xats de llarga durada en què el context sigui important.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Mode de la cua`},help:{"v1-19k7gy1-67":`Mode de la cua per a les execucions actives. Utilitzeu "steer" per inserir instruccions a l'execució activa, "followup" per executar-les més endavant, "collect" per agrupar missatges compatibles més endavant o "interrupt" per interrompre l'execució activa abans d'iniciar la instrucció més recent.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Prefix de les respostes de sortida`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Mode predeterminat del peu d'ús`},help:{"v1-l3shsx-dv":`Mode predeterminat del peu d'ús de cada resposta ("off"|"tokens"|"full"), que s'aplica inicialment a les sessions que no n'han triat cap mitjançant /usage. També accepta "on" com a àlies heretat de "tokens". Accepta un mode sol o un mapa per canal amb "default" com a valor alternatiu. Precedència: valor de la sessió -> entrada del canal -> default -> off; una selecció explícita de /usage (inclòs off) es desa i substitueix el valor predeterminat. Utilitzeu /usage reset (àlies: inherit, clear, default) per esborrar el valor específic d'una sessió i tornar a heretar aquest valor predeterminat configurat.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Reaccions d'estat`},help:{"v1-193764l-3s":`Reaccions d'estat del cicle de vida que actualitzen l'emoji del missatge desencadenant a mesura que l'agent avança (en cua → pensant → eina → completat/error).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Activa les reaccions d'estat`},help:{"v1-1qnmmnc-7x":`Activa les reaccions d'estat del cicle de vida als canals compatibles. Discord considera que l'opció està activada si no s'ha definit i les reaccions de confirmació estan actives; Slack, Signal, Telegram i WhatsApp requereixen que tingui el valor true per utilitzar les reaccions del cicle de vida. Slack utilitza per defecte l'estat natiu del fil de l'assistent per mostrar el progrés.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Plantilla del peu d'ús`},help:{"v1-1xibc23-47":`Plantilla personalitzada del peu de /usage full, com a objecte en línia o com a ruta d'un fitxer JSON. Si la plantilla no és vàlida o no està disponible, s'utilitza la línia d'ús integrada.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Respostes visibles`},help:{"v1-7yfwc2-8t":`Controla les respostes d'origen redactades pel model en converses directes, de grup i de canal. "message_tool" requereix message(action=send) per a la sortida normal de l'assistent i el contingut multimèdia genèric de les eines; la sortida en temps d'execució que pertany explícitament a l'amfitrió es pot continuar lliurant, excepte els esdeveniments ambientals de la sala. "automatic" publica les respostes normals com abans.`}},meta:{label:{"v1-1xpfxac-m":`Metadades de compatibilitat`},help:{"v1-1owqhgn-2w":`Metadades de compatibilitat llegibles per versions anteriors, conservades perquè els binaris antics puguin rebutjar canvis no segurs de la configuració a versions anteriors.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Versió que ha modificat la configuració per darrera vegada`},help:{"v1-qykpv1-1i":`Versió d'OpenClaw que ha escrit aquesta configuració per darrera vegada.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Marcadors de migració de la configuració`},help:{"v1-burt8q-1q":`Marcadors de compatibilitat d'abast limitat per a les migracions de configuració completades.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migració de la llista de permesos de la política de models`},help:{"v1-5psop1-1z":`Registra que les restriccions antigues del mapa de models s'han conservat o avaluat.`}},"meta%2Emigrations%2EskillLibraryToolSplit":{label:{"v1-1x6n7ed-y":`Migració de la separació de l’eina de biblioteca d’habilitats`},help:{"v1-jph48r-3s":`Registra que les polítiques d’eines que incloïen skill_workshop es van ampliar a skill_library quan la creació de contingut de la biblioteca personal es va traslladar a una eina pròpia.`}},"meta%2Emigrations%2EskillWorkshopPlugin":{label:{"v1-1703542-v":`Migració del connector Skill Workshop`},help:{"v1-1y4ur5t-2i":`Registra que s'ha eliminat la política del connector Skill Workshop escrita quan Workshop estava integrat.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migració de la separació dels models auxiliars`},help:{"v1-vzdfqx-2t":`Registra que els models principals implícits antics s'han conservat abans de separar la selecció dels models auxiliars.`}},models:{label:{"v1-hzmwb-6":`Models`},help:{"v1-1h1niol-5q":`Arrel del catàleg de models per a les definicions de proveïdors, el comportament de fusió o substitució i la integració opcional de la descoberta de Bedrock. Manteniu les definicions de proveïdors explícites i validades abans de confiar en les vies de commutació per error en producció.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Actualització del catàleg de models`},help:{"v1-1hess4t-40":`Controla les actualitzacions en segon pla del catàleg de models inclòs. Les files remotes poden actualitzar les metadades dels models, però no poden canviar els punts de connexió ni les capçaleres dels proveïdors.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Actualització del catàleg de models activada`},help:{"v1-1fogpjj-3j":`Obtén actualitzacions del catàleg de models allotjat en segon pla (valor per defecte: true). Establiu-ho a false per desactivar tot el trànsit remot del catàleg de models.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL d'actualització del catàleg de models`},help:{"v1-ai1thy-6o":`Substitueix l'URL del catàleg de models allotjat per la d'una rèplica HTTPS autoallotjada (es permet HTTP a localhost per fer proves). Una Passarel·la en execució deixa d'utilitzar el catàleg de la font anterior i adopta el de la rèplica en la comprovació següent del catàleg, sense reiniciar-se.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Mode del catàleg de models`},help:{"v1-1ofrnsp-es":`Controla el comportament del catàleg de proveïdors: "merge" conserva els proveïdors integrats i hi superposa els personalitzats, mentre que "replace" utilitza només els proveïdors que heu configurat. Amb "merge", els ID de proveïdor coincidents conserven els valors baseUrl no buits del fitxer models.json de l'agent, mentre que els valors apiKey només es conserven si el proveïdor no està gestionat per SecretRef en el context actual de configuració i perfil d'autenticació; els proveïdors gestionats per SecretRef actualitzen apiKey a partir dels marcadors d'origen actuals, i els valors contextWindow/maxTokens dels models coincidents utilitzen el valor més alt entre les entrades explícites i les implícites.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Proveïdors de models`},help:{"v1-7b5l2y-fo":`Configuracions dels punts de connexió dels models amb l'ID del proveïdor com a clau. Trieu un ID nou, com ara gpu-a o my-lab, per a un punt de connexió personalitzat independent. Els ID i els àlies integrats i els que pertanyen a extensions conserven la semàntica de la seva integració; configurar-ne un superposa la configuració a aquesta integració. L'ID no selecciona el protocol de comunicació: ho fa api. Diversos ID personalitzats poden utilitzar el mateix adaptador amb URL base, credencials i models diferents. Utilitzeu un ID diferent per a un servidor independent en lloc de reutilitzar openai només perquè sigui compatible amb OpenAI. Les entrades personalitzades han d'incloure baseUrl i models.`}},"models%2Eproviders%2E*":{help:{"v1-1sjqhly-54":`Una configuració de proveïdor amb nom. Substituïu * per l'ID que hàgiu triat o per un ID d'integració existent que vulgueu sobreescriure expressament. La consulta de l'esquema funciona abans de configurar un ID personalitzat.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Entorn d'execució del proveïdor de models`},help:{"v1-1luy4fb-5o":`Política opcional de baix nivell de l'entorn d'execució de l'agent per a aquest proveïdor. Utilitzeu una política d'entorn d'execució per proveïdor/model en lloc de fixar l'entorn d'execució per a tot l'agent; si s'omet o s'utilitza el valor per defecte, OpenClaw tria l'entorn d'execució per al proveïdor seleccionat.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`ID de l'entorn d'execució del proveïdor de models`},help:{"v1-1gusd9s-69":`ID de l'entorn d'execució de l'agent del proveïdor: "openclaw", "auto", un ID d'infraestructura d'execució d'un connector registrat, com ara "codex", o un àlies de backend CLI compatible, com ara "claude-cli". Si s'omet, OpenAI al punt de connexió oficial utilitza per defecte la infraestructura d'execució de Codex.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Adaptador d'API del proveïdor de models`},help:{"v1-jpi8x4-6e":`Adaptador del protocol de comunicació, independent de l'ID del proveïdor. Chat Completions: openai-completions; Responses: openai-responses; Messages: anthropic-messages. Trieu altres adaptadors entre els valors permesos perquè coincideixin amb el protocol del servei de destinació.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Clau d'API del proveïdor de models`},help:{"v1-1p84k96-54":`Credencial del proveïdor utilitzada per a l'autenticació basada en claus d'API quan el proveïdor requereix autenticació directa amb clau. Utilitzeu la substitució amb secrets o variables d'entorn i eviteu desar claus reals en fitxers de configuració incorporats al control de versions.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Mode d'autenticació del proveïdor de models`},help:{"v1-1g4jg7x-et":`Selecciona el tipus d'autenticació del proveïdor: "api-key" per a l'autenticació amb clau d'API, "token" per a l'autenticació amb testimoni de portador, "oauth" per a les credencials OAuth, "aws-sdk" per a la resolució de credencials AWS i "none" per als punts de connexió openai-completions personalitzats que no exigeixen autenticació. El valor explícit "none" omet les credencials i no envia cap capçalera Authorization; es rebutgen els altres adaptadors efectius. "native-command" delega les credencials a un entorn d'execució de Codex configurat explícitament per a un proveïdor Responses HTTPS personalitzat; no es pot combinar amb claus d'API, perfils ni sobreescriptures de sol·licituds.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Capçalera d'autorització del proveïdor de models`},help:{"v1-1gn3lt3-59":`Quan és true, les credencials s'envien mitjançant la capçalera HTTP Authorization encara que sigui possible utilitzar una autenticació alternativa. Utilitzeu aquesta opció només quan el proveïdor o el servidor intermediari requereixin explícitament el reenviament d'Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`URL base del proveïdor de models`},help:{"v1-1ku88v8-53":`URL base del punt de connexió del proveïdor que s'utilitza per atendre les sol·licituds de models d'aquesta entrada de proveïdor. Utilitzeu punts de connexió HTTPS i manteniu les URL específiques de cada entorn mitjançant plantilles de configuració quan calgui.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Capçaleres del proveïdor de models`},help:{"v1-chg59u-4x":`Capçaleres HTTP estàtiques que s'incorporen a les sol·licituds al proveïdor per a l'encaminament per inquilí, l'autenticació del servidor intermediari o requisits personalitzats de la passarel·la. Utilitzeu aquesta opció amb moderació i deseu els valors sensibles de les capçaleres com a secrets.`}},"models%2Eproviders%2E*%2Eicon":{label:{"v1-1cwoqcc-j":`Icona del proveïdor de models`},help:{"v1-opei4i-9m":`Imatge opcional del proveïdor: un fitxer local, un URL HTTPS públic d'una imatge o una icona inclosa. Les imatges d'origen PNG, JPEG, WebP i GIF tenen un límit de 2 MiB i 4096 píxels per costat i se serveixen com a PNG estàtic sanejat. Els camins relatius es resolen a partir del directori del fitxer de configuració actiu. Si la imatge no és vàlida, es fa servir la marca del proveïdor o la inicial del nom visible.`}},"models%2Eproviders%2E*%2Eicon%2Ename":{label:{"v1-btu3z4-r":`Icona inclosa del proveïdor de models`},help:{"v1-14mjg6a-3j":`Nom d'una icona inclosa a l'aplicació web, com ara server. Si el nom és desconegut, s'utilitza la icona de marca integrada del proveïdor o la inicial del seu nom visible.`}},"models%2Eproviders%2E*%2Eicon%2Epath":{label:{"v1-1pddy1u-o":`Fitxer de la icona del proveïdor de models`},help:{"v1-1fgtl8e-73":`Camí local a Gateway d'un fitxer PNG, JPEG, WebP o GIF. Els camins relatius es resolen a partir del directori que conté el fitxer de configuració actiu; ~/ s'expandeix al directori personal de l'usuari de Gateway. Només aquesta imatge configurada s'exposa mitjançant la ruta de recursos específica del proveïdor.`}},"models%2Eproviders%2E*%2Eicon%2Esource":{label:{"v1-13ahm5t-q":`Origen de la icona del proveïdor de models`},help:{"v1-173lyjy-3i":`Origen de la imatge: file per a una imatge local del Gateway, url per a una imatge HTTPS pública o builtin per a una icona inclosa a l’aplicació web.`}},"models%2Eproviders%2E*%2Eicon%2Eurl":{label:{"v1-1euf5yl-n":`URL de la icona del proveïdor de models`},help:{"v1-147pn2x-65":`URL HTTPS públic d'una imatge PNG, JPEG, WebP o GIF sense credencials incrustades ni fragment. Gateway obté i saneja la imatge amb proteccions contra l'accés a xarxes privades i les redireccions; el navegador no accedeix mai directament a aquest URL.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Injecció de num_ctx del proveïdor de models (compatibilitat amb OpenAI)`},help:{"v1-53rmcr-6n":"Controla si OpenClaw injecta `options.num_ctx` per als proveïdors Ollama configurats amb l'adaptador compatible amb OpenAI (`openai-completions`). El valor per defecte és true. Establiu-lo en false només si el servidor intermediari o el servidor d'origen rebutgen camps desconeguts d'`options` a la càrrega útil."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Servei local del proveïdor de models`},help:{"v1-9r1lm6-4y":`Procés opcional de servidor local de models sota demanda per a aquest proveïdor. OpenClaw comprova healthUrl, executa l'ordre quan cal, espera que el servei estigui a punt i després envia la sol·licitud del model.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Arguments del servei local del proveïdor de models`},help:{"v1-t12wib-27":`Llista d'arguments que es passen a l'ordre del servidor local de models sense expansió de l'intèrpret d'ordres.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Ordre del servei local del proveïdor de models`},help:{"v1-64k3ef-4h":`Camí absolut de l'executable del procés del servidor local de models. Manteniu aquest camí explícit perquè l'inici del proveïdor sigui previsible i no depengui de la cerca a PATH de l'intèrpret d'ordres.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Directori de treball del servei local del proveïdor de models`},help:{"v1-fi3xlx-1h":`Directori de treball del procés del servidor local de models.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Entorn del servei local del proveïdor de models`},help:{"v1-1lwb9k1-3k":`Variables d'entorn addicionals per al procés del servidor local de models. Els valors que semblen secrets s'oculten a les instantànies de la configuració.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL de comprovació de l'estat del servei local del proveïdor de models`},help:{"v1-12nvqxl-36":`URL que es comprova abans de les sol·licituds de models per verificar que el servei està a punt. Si s'omet, OpenClaw utilitza el baseUrl del proveïdor amb /models afegit al final.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Aturada per inactivitat del servei local del proveïdor de models`},help:{"v1-1efg054-3z":`Mil·lisegons durant els quals es manté actiu un servidor local de models iniciat per OpenClaw després que finalitzi l'última sol·licitud. Establiu-ho a 0 per mantenir-lo actiu fins que OpenClaw es tanqui.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Temps d'espera màxim perquè el servei local del proveïdor de models estigui a punt`},help:{"v1-bwmfqa-2r":`Temps màxim en mil·lisegons d'espera per a la comprovació de disponibilitat del servidor local de models després d'iniciar el procés.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Màxim de tòkens del proveïdor de models`},help:{"v1-fnj50y-38":`Límit màxim de tòkens de sortida per defecte que s'aplica als models d'aquest proveïdor quan l'entrada d'un model no defineix maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Llista de models del proveïdor`},help:{"v1-1vbm0gt-63":`Llista de models declarada per a un proveïdor, que inclou identificadors, metadades, paràmetres específics del proveïdor i indicacions opcionals de compatibilitat i cost. Manteniu els identificadors exactament iguals que els valors del catàleg del proveïdor perquè la selecció i el recurs a alternatives es resolguin correctament.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Entorn d'execució del model`},help:{"v1-1k70g2n-3g":`Política opcional de baix nivell de l'entorn d'execució de l'agent per a aquest model concret. La política de l'entorn d'execució del model preval sobre la del proveïdor.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Identificador de l'entorn d'execució del model`},help:{"v1-1llzv33-42":`Identificador de l'entorn d'execució de l'agent del model: "openclaw", "auto", un identificador registrat d'un entorn de control de connector, com ara "codex", o un àlies admès d'un backend CLI, com ara "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Entrada multimèdia del model`},help:{"v1-wxtj8e-2x":`Metadades opcionals sobre les capacitats multimèdia del model que les eines utilitzen per triar valors predeterminats conservadors de compressió d'imatges.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Entrada d'imatges del model`},help:{"v1-1nviirq-3c":`Límits opcionals d'entrada d'imatges per a aquest model, com ara la longitud màxima del costat, el nombre màxim de píxels i la mida de costat preferida per a la compressió.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Màxim de bytes d'imatge del model`},help:{"v1-c2469j-23":`Mida màxima de les dades d'imatge codificades que el proveïdor accepta per a aquest model.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Màxim de píxels d'imatge del model`},help:{"v1-9d6yqp-1u":`Nombre màxim de píxels d'imatge que el proveïdor accepta per a aquest model.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Costat màxim d'imatge del model`},help:{"v1-1gbci08-1y":`Amplada o alçada màxima d'imatge que el proveïdor accepta per a aquest model.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Costat preferit d'imatge del model`},help:{"v1-1u1mpcg-2x":`Mida de costat preferida per redimensionar la imatge amb una compressió equilibrada. Deixeu-la sense definir per utilitzar el valor predeterminat conservador d'OpenClaw.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Mode de tokens d'imatge del model`},help:{"v1-1oy6z7v-1z":`Mètode de recompte de tokens d'imatge del proveïdor: "tile", "detail" o "provider".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EresponseModelEquivalent":{help:{"v1-1hociw2-d7":`Establiu el valor true en una fila de proveïdor personalitzat creada per l'usuari quan un encaminador o intermediari resolgui aquest identificador de model per si mateix. Aleshores, qualsevol identificador de resposta comunicat pel punt final es considera equivalent, incloses les substitucions internes del punt final. L'identificador servit i l'ús es continuen registrant; els avisos d'OpenClaw sobre alternatives i substitucions es mantenen. No es pot anul·lar la política integrada o oficial. Les files de connectors o del catàleg, les files de models.json de l'agent i les files de models-add no poden concedir equivalència. Si s'omet o s'estableix en false, es manté la detecció normal de rutes.`}},"models%2Eproviders%2E*%2Ename":{label:{"v1-ioaceo-r":`Nom visible del proveïdor de models`},help:{"v1-jio82-3z":`Nom visible opcional que es mostra a la configuració del proveïdor i als selectors de models. No modifica l'ID del proveïdor, les referències dels models, les credencials ni l'encaminament.`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Paràmetres d'execució del proveïdor de models`},help:{"v1-464sgu-4t":`Paràmetres d'execució específics del proveïdor que interpreten els connectors del proveïdor. Manteniu les claus documentades pel proveïdor i prioritzeu la documentació explícita del proveïdor per sobre de les suposicions compartides ad hoc.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Regió del proveïdor de models`},help:{"v1-yq7rxk-5h":`Regió opcional de desplegament o de l'API del proveïdor, interpretada pels proveïdors que ofereixen punts finals regionals. Consulteu la documentació del proveïdor per conèixer els valors admesos; les substitucions de baseUrl solen tenir prioritat quan es configuren tots dos valors.`}},"models%2Eproviders%2E*%2Eremote":{label:{"v1-ih3vfx-11":`Temporització del vigilant per a serveis allotjats del proveïdor de models`},help:{"v1-bsr5s-9g":`Substitució de la temporització per la de serveis allotjats, només per als vigilants, destinada a retransmissors locals situats davant d'API allotjades. Quan el valor és true, els vigilants d'inactivitat i del primer esdeveniment de l'LLM utilitzen la temporització de serveis allotjats, fins i tot amb un baseUrl, un identificador de proveïdor, un localService o un marcador d'autenticació locals. Si s'omet o s'estableix en false, es manté la detecció del caràcter local. El valor explícit de timeoutSeconds i els límits d'execució o de l'agent mantenen la seva prioritat.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Substitucions de sol·licituds del proveïdor de models`},help:{"v1-1lkxryk-87":`Substitucions opcionals per a les sol·licituds al proveïdor de models, incloses capçaleres addicionals, substitucions d'autenticació, encaminament per servidor intermediari, configuració del client TLS i l'opció allowPrivateNetwork per a punts de connexió autoallotjats de confiança. Utilitzeu-les només quan el servei de destinació o la ruta de xarxa empresarial requereixin personalitzar el transport.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Permet la xarxa privada per a les sol·licituds al proveïdor de models`},help:{"v1-1nbtcjk-fo":`Quan és true, permet que les sol·licituds HTTP al proveïdor de models accedeixin a intervals privats, CGNAT o similars a través de la protecció d'obtenció HTTP del proveïdor (fetchWithSsrFGuard). Els URL base dels proveïdors personalitzats o locals ja confien en l'origen exacte configurat, excepte els orígens de metadades, d'enllaç local i NAT64 d'ús local (64:ff9b:1::/48); establiu aquesta opció a false per desactivar aquesta confiança. OpenAI Responses WebSocket reutilitza request per a les capçaleres i TLS, però no utilitza aquesta via d'obtenció amb protecció SSRF. Utilitzeu true només per a punts de connexió autoallotjats controlats per l'operador que hagin d'accedir a orígens privats fora de l'origen baseUrl configurat.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Substitució de l'autenticació de les sol·licituds al proveïdor de models`},help:{"v1-ucdgnf-1w":`Substitueix el comportament d'autenticació de les sol·licituds per a aquest proveïdor.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Nom de la capçalera d'autenticació de les sol·licituds al proveïdor de models`},help:{"v1-1881nqr-1i":`Nom de la capçalera d'autenticació personalitzada que s'utilitza quan el mode d'autenticació és header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Mode d'autenticació de les sol·licituds al proveïdor de models`},help:{"v1-1lhv8hs-24":`Mode de substitució de l'autenticació: "provider-default", "authorization-bearer" o "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Prefix de la capçalera d'autenticació de les sol·licituds al proveïdor de models`},help:{"v1-1rbm9lz-21":`Prefix opcional que s'anteposa a request.auth.value quan el mode d'autenticació és header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Testimoni Bearer de les sol·licituds al proveïdor de models`},help:{"v1-6rcasw-1l":`Testimoni Bearer que s'utilitza quan el mode d'autenticació és authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Valor de la capçalera d'autenticació de les sol·licituds al proveïdor de models`},help:{"v1-1v69ej-1j":`Valor personalitzat de la capçalera d'autenticació que s'utilitza quan el mode d'autenticació és header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Capçaleres de les sol·licituds al proveïdor de models`},help:{"v1-zj3orj-2i":`Capçaleres addicionals que s'incorporen a les sol·licituds al proveïdor després de resoldre l'atribució predeterminada i l'autenticació.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Servidor intermediari de les sol·licituds al proveïdor de models`},help:{"v1-md5uj8-4j":`Substitució opcional del servidor intermediari per a les sol·licituds al proveïdor de models. Utilitzeu "env-proxy" per respectar la configuració del servidor intermediari de l'entorn o "explicit-proxy" per encaminar-les a través de l'URL d'un servidor intermediari específic.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Mode del servidor intermediari de les sol·licituds al proveïdor de models`},help:{"v1-1dx0ozg-29":`Mode de substitució del servidor intermediari per a les sol·licituds al proveïdor de models: "env-proxy" o "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS del servidor intermediari de les sol·licituds al proveïdor de models`},help:{"v1-rdx62w-1v":`Configuració TLS opcional que s'utilitza en connectar-se al servidor intermediari configurat.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`CA TLS del servidor intermediari de sol·licituds del proveïdor de models`},help:{"v1-11pg2fd-1s":`Conjunt de certificats de CA personalitzat utilitzat per verificar la cadena de certificats TLS del servidor intermediari.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Certificat TLS del servidor intermediari de sol·licituds del proveïdor de models`},help:{"v1-x8nk2q-22":`Certificat TLS de client presentat al servidor intermediari quan es requereix TLS mutu.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Omet la verificació TLS del servidor intermediari de sol·licituds del proveïdor de models`},help:{"v1-12vjdm9-2j":`Omet la verificació del certificat TLS del servidor intermediari. Utilitzeu aquesta opció només en entorns de desenvolupament controlats.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Clau TLS del servidor intermediari de sol·licituds del proveïdor de models`},help:{"v1-1skyr56-1w":`Clau privada associada a request.proxy.tls.cert per al TLS mutu amb el servidor intermediari.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Frase de contrasenya TLS del servidor intermediari de sol·licituds del proveïdor de models`},help:{"v1-wjvoxd-1m":`Frase de contrasenya opcional utilitzada per desxifrar request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Nom del servidor TLS del servidor intermediari de sol·licituds del proveïdor de models`},help:{"v1-b4oabu-22":`Valor opcional que substitueix l'SNI o el nom del servidor en establir una connexió TLS amb el servidor intermediari.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`URL del servidor intermediari de sol·licituds del proveïdor de models`},help:{"v1-kvbgou-48":`URL del servidor intermediari explícit que s'utilitza quan request.proxy.mode és explicit-proxy. Les credencials incloses a l'URL es tracten com a dades sensibles i s'oculten a les instantànies.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS de les sol·licituds al proveïdor de models`},help:{"v1-16u7v7h-2b":`Configuració TLS opcional que s'utilitza en connectar directament amb el punt de connexió del model remot.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`CA TLS de les sol·licituds al proveïdor de models`},help:{"v1-ny8y3e-1v":`Paquet de CA personalitzat que s'utilitza per verificar la cadena de certificats TLS del servidor remot.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Certificat TLS de les sol·licituds al proveïdor de models`},help:{"v1-1lltmhw-2e":`Certificat TLS de client que es presenta al punt de connexió remot quan es requereix TLS mutu.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Omet la verificació TLS de les sol·licituds al proveïdor de models`},help:{"v1-1006cuy-2m":`Omet la verificació del certificat TLS del servidor remot. Utilitzeu aquesta opció només en entorns de desenvolupament controlats.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Clau TLS de les sol·licituds al proveïdor de models`},help:{"v1-w2agir-1t":`Clau privada associada a request.tls.cert per al TLS mutu amb el servidor remot.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Frase de contrasenya TLS de les sol·licituds al proveïdor de models`},help:{"v1-10ds42f-1g":`Frase de contrasenya opcional que s'utilitza per desxifrar request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Nom del servidor TLS de les sol·licituds al proveïdor de models`},help:{"v1-18yt7x9-1y":`Substitució opcional de l'SNI o del nom del servidor que s'utilitza en establir la connexió TLS amb el servidor de destinació.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Temps d'espera de les sol·licituds al proveïdor de models`},help:{"v1-t3yn8l-ih":`Temps d'espera opcional, en segons, de les sol·licituds de models per proveïdor. La configuració de les sol·licituds a nivell de proveïdor afecta les entrades de models explícites del proveïdor; no crea models implícits. Per als proveïdors personalitzats, definiu-lo juntament amb baseUrl i models del proveïdor. S'aplica a les peticions HTTP del proveïdor, incloent-hi la connexió, les capçaleres, el cos i la gestió de la cancel·lació de la sol·licitud completa, i també eleva el límit del temporitzador de supervisió d'inactivitat i de transmissió de l'LLM per a aquest proveïdor per sobre del valor implícit predeterminat de ~120s. Utilitzeu-lo per a servidors de models locals o autoallotjats lents, o per a proveïdors al núvol que emmagatzemen temporalment els tokens de raonament sense transmetre dades per la xarxa (Gemini preview, Claude/Opus amb càrregues de dades d'eines grans), en lloc de canviar els temps d'espera globals dels agents.`}},"models%2Eusage":{label:{"v1-1frhz6j-e":`Ús del proveïdor`},help:{"v1-hn2n9r-18":`Configuració de la memòria cau de l'ús del pla comunicat pel proveïdor.`}},"models%2Eusage%2EcacheTtlMs":{label:{"v1-1g6hvog-t":`TTL de la memòria cau d'ús del proveïdor (ms)`},help:{"v1-jltn3b-4j":`Reutilitza les instantànies d'ús del proveïdor durant aquest nombre de mil·lisegons (valor predeterminat: 60000). S'aplica a les lectures ordinàries i posteriors a l'execució; 0 desactiva la reutilització. No activa les consultes periòdiques durant la inactivitat.`}},nodeHost:{label:{"v1-nb8lk1-9":`Amfitrió del node`},help:{"v1-8recuz-4z":`Controls de l'amfitrió del node per a les funcions que aquest node de la passarel·la exposa a altres nodes o clients. Manteniu els valors predeterminats tret que vulgueu posar les capacitats locals a disposició de la xarxa de nodes mitjançant un servidor intermediari.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Execucions d'agents del node`},help:{"v1-4uz5ur-2k":`Activa els torns natius d'agent subjectes a aprovació en aquest amfitrió de node sense interfície gràfica. Desactivat per defecte.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Execucions de l'agent Claude al node`},help:{"v1-g8az5y-2l":`Controla si aquest amfitrió de node sense interfície gràfica pot anunciar torns d'agent de Claude CLI a la Passarel·la.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Execucions de l'agent Claude al node activades`},help:{"v1-1ke804l-44":`Anuncia la continuació de sessions de Claude en un node aparellat quan el binari local claude està disponible (per defecte: false). Les execucions continuen requerint l'aprovació d'execució del node.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Actualitzacions automàtiques del node`},help:{"v1-16xjk4e-5n":`Controla les actualitzacions automàtiques de l'entorn d'execució independent per als amfitrions de nodes empaquetats sense interfície gràfica. Comprova si hi ha actualitzacions cada hora i espera que acabin totes les tasques del node abans de reiniciar; els reinicis automàtics estan separats per un mínim de 12 hores.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Actualitzacions automàtiques del node activades`},help:{"v1-1sa0yeg-7w":`Activa les actualitzacions automàtiques estables o beta per als nodes empaquetats sense interfície gràfica que s'executen durant períodes llargs (per defecte: true). Estableix-ho a false per desactivar-les. També es desactiven amb update.checkOnStart=false o OPENCLAW_NO_AUTO_UPDATE=1; no s'apliquen automàticament a les còpies de treball del codi font, les aplicacions natives, els processos de treball privats, dev ni extended-stable.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Servidor intermediari del Navegador del node`},help:{"v1-2xrew7-4f":`Agrupa la configuració del servidor intermediari del navegador per exposar el control del navegador local mitjançant l'encaminament de nodes. Activa'l només quan els fluxos de treball dels nodes remots necessitin els teus perfils de navegador locals.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Perfils permesos del servidor intermediari del Navegador del node`},help:{"v1-1ew5dkm-8b":`Llista opcional de noms de perfils de navegador permesos exposats mitjançant l'encaminament del servidor intermediari del node. Deixeu-la buida per mantenir l'accés complet als perfils per defecte, incloses les rutes de creació i supressió de perfils. Si es configura, OpenClaw aplica el principi de privilegi mínim a l'accés als perfils i bloqueja la creació i la supressió de perfils persistents a través del servidor intermediari.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Servidor intermediari del navegador del node activat`},help:{"v1-pa04pd-5b":`Exposeu el servidor local de control del navegador mitjançant l'encaminament del servidor intermediari del node perquè els clients remots puguin utilitzar les capacitats de navegador d'aquest amfitrió. Manteniu-lo desactivat tret que l'automatització remota en depengui explícitament.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP de l'amfitrió del node`},help:{"v1-1mdhrwl-48":`Utilitzeu com a eines d'agent els servidors MCP iniciats per l'amfitrió del node sense interfície gràfica i publicats a la seva passarel·la vinculada. Reinicieu l'amfitrió del node després de modificar aquesta secció.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Servidors MCP de l'amfitrió del node`},help:{"v1-19m002f-3x":`Definicions amb nom de servidors MCP locals d'aquest node. Utilitza la mateixa estructura de servidor que mcp.servers; l'amfitrió del node no admet servidors OAuth.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Habilitats de l'amfitrió del node`},help:{"v1-v8txza-41":`Utilitzeu aquesta secció per publicar les habilitats instal·lades a ~/.openclaw/skills des de l'amfitrió del node sense interfície gràfica. Reinicieu l'amfitrió del node després de modificar els fitxers d'habilitats.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Habilitats de l'amfitrió del node activades`},help:{"v1-1ggpkqb-36":`Detecteu i publiqueu les habilitats allotjades al node després de connectar-vos (per defecte: true). Establiu-ho a false per desactivar la publicació d'habilitats del node.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Execucions dels processos de treball del node`},help:{"v1-1w83rox-2p":`Activa l'allotjament complet de sessions de processos de treball d'OpenClaw a partir de paquets gestionats per la Passarel·la. Desactivat per defecte.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Capacitat d'execució de processos de treball del node`},help:{"v1-10nvk8f-3w":`Nombre màxim de sessions simultànies de processos de treball allotjades en aquest node (per defecte: el nombre de nuclis de CPU disponibles). Ha de ser un enter entre 1 i 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Imatge de contenidor per a l'execució de processos de treball del node`},help:{"v1-1tmr1le-5y":`Imatge opcional de Node 24.22.1+ o 26.12.1+ per a processos de treball aïllats en contenidors (per defecte: "node:24.22.1-slim"). Quan calgui, utilitza una imatge fixada per resum criptogràfic, d'un registre privat o precarregada; les imatges que faltin es descarregaran en el primer ús.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Execucions de processos de treball del node activades`},help:{"v1-b3t0xp-2t":`Permet que aquest node aparellat allotgi sessions a partir dels paquets exactes instal·lats per la seva Passarel·la (per defecte: false).`}},"nodeHost%2EworkerRuns%2Efolders":{label:{"v1-1waimc-r":`Carpetes de sessions de processos de treball del node`},help:{"v1-ald547-9v":`Directoris arrel opcionals que restringeixen les sessions in situ a aquests directoris i als seus subdirectoris. Si no es defineixen, es permet qualsevol directori existent excepte les arrels del sistema de fitxers i l'emmagatzematge privat dels processos de treball; [] desactiva les sessions en carpetes del dispositiu. Utilitza camins absoluts o amb ~/. Els fitxers existents romanen al dispositiu; suprimir una sessió no elimina mai aquestes carpetes. Requereix workerRuns.enabled.`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Aïllament d'execució de processos de treball del node`},help:{"v1-19i6swo-58":`Selecciona el límit d'aïllament del procés de la sessió de treball: "none" l'executa directament a l'amfitrió del node (per defecte); "container" requereix un motor compatible amb Docker que funcioni i no recorre mai a l'execució a l'amfitrió com a alternativa.`}},plugins:{label:{"v1-10renyj-7":`Connectors`},help:{"v1-1qbev2k-5c":`Controls del sistema de connectors per activar extensions, limitar l'abast de la càrrega, configurar entrades i fer el seguiment de les instal·lacions. Manteniu una política de connectors explícita i de privilegis mínims en entorns de producció.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Llista de connectors permesos`},help:{"v1-1w1dsc3-ek":`Llista opcional d'ID de connectors permesos; una llista no buida restringeix la càrrega, excepte per al connector de memòria seleccionat (inclosa la selecció predeterminada memory-core), els connectors context-engine amb el mateix ID i els canals de xat integrats activats explícitament. Els connectors responsables de context-engine amb noms diferents s'han d'activar o autoritzar de manera independent i s'han d'incloure en qualsevol llista de permesos no buida. Les eines dels connectors que no figuren a la llista de permesos continuen sense estar disponibles. Feu servir plugins.deny o plugins.entries.<id>.enabled: false per bloquejar un connector independentment de la selecció de la ranura.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Llista de connectors bloquejats`},help:{"v1-4gyt4z-4i":`Llista opcional d'ID de connectors que es bloquegen encara que estiguin inclosos en llistes de permesos o rutes. Feu servir regles de denegació per a reversions d'emergència i bloquejos estrictes de connectors de risc.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Activa els connectors`},help:{"v1-pnygd7-50":`Activa o desactiva globalment la càrrega de connectors i extensions durant l'inici i la recàrrega de la configuració (valor predeterminat: true). Manteniu aquesta opció activada només quan el desplegament requereixi les funcionalitats de les extensions.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Entrades de connectors`},help:{"v1-cn74rf-54":`Configuració per connector indexada per l'ID del connector, incloent-hi l'activació i les dades de configuració d'execució específiques del connector. Feu-la servir per ajustar connectors de manera individual sense canviar la política global de càrrega.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Clau d'API del connector`},help:{"v1-ctytg2-53":`Camp opcional de clau d'API utilitzat pels connectors que admeten la configuració directa de claus a la configuració de l'entrada. Utilitzeu la substitució mitjançant secrets o variables d'entorn i eviteu desar credencials reals als fitxers de configuració.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Configuració del connector`},help:{"v1-1he672p-51":`Dades de configuració definides pel connector i interpretades segons el seu propi esquema i les seves regles de validació. Utilitzeu només els camps documentats del connector per evitar paràmetres ignorats o no vàlids.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Connector activat`},help:{"v1-12soc0h-9a":`Ajust d'activació per a una entrada de connector específica, que s'aplica per sobre de la política global de connectors. Amb el mode de recàrrega híbrid predeterminat, els canvis recarreguen en calent l'entorn d'execució del connector per als nous torns de l'agent sense reiniciar la Passarel·la, tret que el connector requereixi un reinici per a aquesta via. Utilitzeu aquest ajust per desplegar el connector gradualment en diferents entorns.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Variables d'entorn del connector`},help:{"v1-p39pu4-52":`Mapa de variables d'entorn per connector, injectat únicament al context d'execució d'aquest connector. Utilitzeu-lo per limitar les credencials del proveïdor a un sol connector en lloc de compartir l'entorn global del procés.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Política de punts d'extensió del connector`},help:{"v1-1oslnrf-4c":`Controls de política de punts d'extensió tipats per connector per a les comprovacions de seguretat imposades pel nucli. Utilitzeu-los per restringir les categories de punts d'extensió d'alt impacte sense desactivar tot el connector.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Permet els punts d'extensió d'accés a les converses`},help:{"v1-xqz31z-7e":"Controla si aquest connector pot llegir el contingut en brut de la conversa des de hooks tipats com ara `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` i `agent_end`. Els connectors no inclosos han d'activar aquesta opció explícitament."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptModification":{label:{"v1-1ufndoc-e":`Modificar les indicacions`},help:{"v1-10llywv-8b":`Permet que aquest connector afegeixi o modifiqui el context i les instruccions que s'envien al model, cosa que pot influir en les seves respostes. Permeteu-ho només als connectors en què confieu. Es permet per defecte. Establiu el valor a false per bloquejar els hooks que modifiquen les indicacions, les orientacions per a les indicacions de les eines, les aportacions a les indicacions del torn següent i la redirecció de l'execució en curs.`}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Temps d'espera dels hooks del connector (ms)`},help:{"v1-4ra6b7-74":`Temps d'espera predeterminat en mil·lisegons per als hooks tipats d'aquest connector, amb un límit de 600000. Si no s'estableix, cada hook utilitza el temps d'espera declarat pel connector o la política per hook de la Passarel·la; no hi ha cap valor predeterminat fix únic. Els valors per hook de hooks.timeouts tenen prioritat.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Substitucions dels temps d'espera dels hooks del connector`},help:{"v1-yphl9b-5s":`Substitucions del temps d'espera per hook en mil·lisegons, amb el nom del hook tipat com a clau i un límit de 600000. Utilitzeu substitucions específiques per als hooks que se sap que són lents, com ara before_prompt_build o agent_end, en lloc d'augmentar el temps d'espera de tots els hooks.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Política d'LLM del connector`},help:{"v1-dlca6c-4j":`Controls d'api.runtime.llm.complete per connector sobre la confiança en la substitució del model i de l'agent. Deixeu aquesta opció sense establir tret que un connector hagi de dirigir explícitament les crides de compleció gestionades per l'amfitrió.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Permet la substitució de l'agent de l'LLM pel connector`},help:{"v1-k8c08b-4n":`Permet explícitament que aquest connector sol·liciti api.runtime.llm.complete amb un identificador d'agent diferent del predeterminat. Manteniu el valor false tret que confieu en el connector per accedir als models d'altres agents.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Permet substituir el perfil d'autenticació de l'LLM del connector`},help:{"v1-9ityw9-4x":`Permet que aquest connector seleccioni un perfil d'autenticació diferent del predeterminat per a les complecions aïllades de l'entorn d'execució de l'agent. Manteniu el valor false tret que confieu en el connector per a l'encaminament explícit i aïllat de credencials.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Models de compleció permesos per a l'LLM del connector`},help:{"v1-1kgxs8j-55":`Destinacions permeses per a cada compleció de l'LLM del connector, com a referències completes "provider/model", inclosos els valors predeterminats resolts per l'amfitrió i les substitucions. Utilitzeu "*" només si voleu permetre expressament qualsevol model.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Models permesos per a l'LLM del connector`},help:{"v1-h9m5ew-48":`Destinacions de substitució permeses per a les crides a l'LLM de connectors de confiança, com a referències completes "provider/model". Utilitzeu "*" només si voleu permetre expressament qualsevol substitució de model.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Permet substituir el model de l'LLM del connector`},help:{"v1-uw4jmc-47":`Permet explícitament que aquest connector sol·liciti substitucions de model a api.runtime.llm.complete. Manteniu el valor false tret que confieu en el connector per dirigir la selecció del model.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Política de subagents del connector`},help:{"v1-wbf4m1-4d":`Controls d'execució dels subagents per a cada connector, relatius a la confiança per substituir models i a les llistes de models permesos. Deixeu-ho sense definir tret que un connector hagi de dirigir explícitament la selecció del model dels subagents.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Models permesos per als subagents del connector`},help:{"v1-hdzz51-43":`Models de substitució permesos per a les execucions de subagents de connectors de confiança, indicats com a referències completes "provider/model". Feu servir "*" només si voleu permetre expressament qualsevol model.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Permet la substitució del model dels subagents del connector`},help:{"v1-1r5tzm1-4g":`Permet explícitament que aquest connector sol·liciti substitucions de provider/model en les execucions de subagents en segon pla. Manteniu el valor false tret que confieu en el connector per dirigir la selecció del model.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Carregador de connectors`},help:{"v1-1myjwbi-52":`Grup de configuració del carregador de connectors per especificar les rutes del sistema de fitxers on es cerquen connectors. Manteniu les rutes de càrrega explícites i revisades per evitar la càrrega accidental d'extensions no fiables.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Rutes de càrrega de connectors`},help:{"v1-o689p1-4z":`Fitxers o directoris de connectors addicionals que el carregador examina, a més dels predeterminats integrats. Feu servir directoris dedicats a extensions i eviteu rutes massa àmplies amb contingut executable no relacionat.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Espais reservats per a connectors`},help:{"v1-zx6crl-5f":`Selecciona quins connectors ocupen espais exclusius durant l'execució, com ara el de memòria, perquè només un connector proporcioni aquesta funcionalitat. Assigneu explícitament aquests espais per evitar proveïdors superposats amb comportaments incompatibles.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-tp8do7-h":`ID del motor de context`},help:{"v1-1ww2hr0-4h":`Selecciona l'ID del motor de context registrat. Els connectors amb ID de connector i de motor diferents declaren contextEngineIds al seu manifest perquè OpenClaw pugui carregar el connector responsable.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Connector de memòria`},help:{"v1-6kb575-6d":`Selecciona el connector de memòria actiu per ID (per defecte: memory-core), o "none" per desactivar els connectors de memòria. El connector seleccionat es pot carregar encara que plugins.allow no l'inclogui; plugins.deny i la desactivació explícita de cada connector continuen tenint prioritat.`}},presence:{label:{"v1-10fdwo4-8":`Presència`}},proxy:{label:{"v1-ji57pa-d":`Servidor intermediari gestionat`},help:{"v1-vui6bx-58":`Encaminament mitjançant un servidor intermediari de sortida gestionat per l'operador per al trànsit HTTP, HTTPS, WebSocket i les vies de sortida directa compatibles d'OpenClaw en temps d'execució. Fes-lo servir quan el control centralitzat de sortida formi part del perímetre del desplegament.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Servidor intermediari gestionat activat`},help:{"v1-1456xdw-49":`Anul·lació explícita del comportament del servidor intermediari gestionat. La presència d'un URL activa l'encaminament per defecte; estableix false per ignorar els URL de servidor intermediari configurats o definits a l'entorn sense eliminar-los.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Mode de bucle local del servidor intermediari gestionat`},help:{"v1-1kaiuh0-3c":`Controla l'encaminament del pla de control de la Passarel·la per bucle local mentre el mode de servidor intermediari gestionat és actiu: "gateway-only", "proxy" o "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL del servidor intermediari gestionat`},help:{"v1-p36b5l-3v":`URL del servidor intermediari de sortida gestionat. Fes servir http:// per a un servidor intermediari CONNECT sense xifratge o https:// quan la connexió al mateix punt de connexió del servidor intermediari hagi d'utilitzar TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS del servidor intermediari gestionat`},help:{"v1-6i0vu-3q":`Configuració de TLS utilitzada en connectar-se al punt de connexió del servidor intermediari gestionat. Aquesta configuració s'aplica al TLS del servidor intermediari, no al TLS de la destinació després de CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Fitxer de CA TLS del servidor intermediari gestionat`},help:{"v1-1ntzjia-2p":`Camí del sistema de fitxers a un paquet de CA personalitzat que s'utilitza per verificar el certificat d'un punt de connexió HTTPS del servidor intermediari gestionat.`}},repositoryBranchPrefix:{label:{"v1-1sxh9u9-o":`Prefix de les branques del repositori`},help:{"v1-10w2bot-41":`Prefix per a les branques de sessió noves del repositori remot. El valor per defecte és openclaw; les branques utilitzen <prefix>/<workspace GUID>. Les branques existents no es modifiquen.`}},secrets:{label:{"v1-1sihgpy-7":`Secrets`},help:{"v1-jgn0o9-2l":`Proveïdors de referències a secrets, comportament del magatzem compartit i protecció opcional del trànsit de sortida dels subprocessos.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Servidor intermediari de sortida de secrets`},help:{"v1-1qfgid-4n":`Servidor intermediari de bucle local de la Passarel·la que substitueix els marcadors de secrets del magatzem compartit només en el moment d'enviar les sol·licituds. Reinicieu la Passarel·la després de modificar aquesta secció, que s'aplica durant l'inici.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Amfitrions permesos del servidor intermediari de sortida de secrets`},help:{"v1-9ypodl-6t":`Llista opcional de trànsit permès per a sol·licituds i túnels CONNECT. Si s'especifica, les destinacions han de figurar en aquesta llista, en una vinculació d'amfitrió específica del secret o a bypassHosts. Una llista buida només permet els amfitrions vinculats o exclosos. Reinicieu la Passarel·la després de modificar-la.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Amfitrions exclosos del servidor intermediari de sortida de secrets`},help:{"v1-1oiiomv-57":`Noms exactes dels amfitrions que utilitzen túnels CONNECT cecs autenticats per a clients amb fixació de certificats. Els marcadors es mantenen xifrats i faran que l'autenticació del proveïdor falli en lloc d'exposar text en clar.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Servidor intermediari de sortida de secrets activat`},help:{"v1-u99b1i-2h":`Activa la substitució de secrets en el trànsit de sortida dels subprocessos d'agents allotjats a la Passarel·la. Valor per defecte: false.`}},"security%2Eaudit":{label:{"v1-16w033o-e":`Auditoria de seguretat`}},"security%2Eaudit%2Esuppressions":{label:{"v1-1l4qjwk-i":`Exclusions de l'auditoria`},help:{"v1-1deyl5p-4f":`Troballes de l'auditoria de seguretat acceptades que s'ometran del resum actiu i de la llista de troballes. Les troballes coincidents continuen disponibles a suppressedFindings a la sortida JSON.`}},"security%2Eaudit%2Esuppressions%2E*%2EcheckId":{label:{"v1-pfzkxp-e":`ID de la comprovació d'auditoria`}},"security%2Eaudit%2Esuppressions%2E*%2EdetailIncludes":{label:{"v1-ykrpzg-n":`El detall de la troballa conté`}},"security%2Eaudit%2Esuppressions%2E*%2Ereason":{label:{"v1-1581z0k-i":`Motiu de l'exclusió`}},"security%2Eaudit%2Esuppressions%2E*%2EtitleIncludes":{label:{"v1-18y11at-m":`El títol de la troballa conté`}},"security%2EinstallPolicy":{label:{"v1-1dbuvhm-e":`Política d'instal·lació`}},"security%2EinstallPolicy%2Eenabled":{label:{"v1-bfdyp9-l":`Activa la política d'instal·lació`},help:{"v1-67yonn-4i":`Activa una ordre local de confiança que aplica la política a les instal·lacions i actualitzacions d'habilitats i connectors. Si s'activa sense cap ordre configurada, es bloquegen les destinacions d'instal·lació compatibles.`}},"security%2EinstallPolicy%2Eexec":{label:{"v1-433033-m":`Ordre de la política d'instal·lació`},help:{"v1-1hyg77m-46":`Ordre local de confiança que retorna una decisió d'instal·lació: "allow", "warn" o "block". Establiu un camí absolut a l'executable; OpenClaw l'executa sense un intèrpret d'ordres.`}},"security%2EinstallPolicy%2Eexec%2Eargs":{label:{"v1-17c9br2-o":`Arguments de l'ordre de la política`}},"security%2EinstallPolicy%2Eexec%2Ecommand":{label:{"v1-l86c0l-h":`Executable de la política`}},"security%2EinstallPolicy%2Eexec%2Eenv":{label:{"v1-f7gtc3-s":`Variables d'entorn de la política`}},"security%2EinstallPolicy%2Eexec%2EmaxOutputBytes":{label:{"v1-1jz3qk1-r":`Límit de sortida de la política (bytes)`}},"security%2EinstallPolicy%2Eexec%2EnoOutputTimeoutMs":{label:{"v1-bu8clf-o":`Temps límit d'inactivitat de la política (ms)`}},"security%2EinstallPolicy%2Eexec%2EpassEnv":{label:{"v1-uzu2wx-12":`Variables d'entorn heretades de la política`}},"security%2EinstallPolicy%2Eexec%2Esource":{label:{"v1-wv29f-l":`Origen de l'ordre de la política`}},"security%2EinstallPolicy%2Eexec%2EtimeoutMs":{label:{"v1-i9ag7r-j":`Temps límit de la política (ms)`}},"security%2EinstallPolicy%2Eexec%2EtrustedDirs":{label:{"v1-1kkqbtr-q":`Directoris de confiança de la política`}},"security%2EinstallPolicy%2Etargets":{label:{"v1-ss3w1g-m":`Destinataris de la política d'instal·lació`},help:{"v1-1ar6u6h-2v":`Aplica la política d'instal·lació a "skill", "plugin" o a tots dos. Omet aquesta llista per incloure tots els destinataris admesos.`}},session:{label:{"v1-8yh9jr-7":`Sessió`},help:{"v1-j86s32-5d":`Controls globals d'encaminament de sessions, reinicialització, política de lliurament i manteniment que regulen el comportament de l'historial de converses. Manteniu els valors per defecte tret que necessiteu restriccions més estrictes d'aïllament, retenció o lliurament.`}},"session%2Ecommunication":{label:{"v1-133tjjf-u":`Valors per defecte de la comunicació entre sessions`},help:{"v1-1y4eege-63":`Valors per defecte per als missatges nous entre sessions. Cada sentit accepta always, ask o never i té always com a valor per defecte. Les sessions hereten aquests valors fins que una persona els modifica explícitament; les restriccions d'accés existents continuen vigents.`}},"session%2Ecommunication%2Ereceive":{label:{"v1-efg2gh-10":`Recepció de missatges d'altres sessions`},help:{"v1-t6w901-5q":`Valor per defecte per acceptar missatges nous d'altres sessions: always ho permet, ask requereix aprovació humana abans d'introduir dades al model o iniciar feina nova, i never ho bloqueja. Això no modifica la visibilitat de l'historial ni l'accés humà.`}},"session%2Ecommunication%2Esend":{label:{"v1-1chq2bl-v":`Enviament de missatges a altres sessions`},help:{"v1-92cfz7-65":`Valor per defecte per iniciar l'enviament de missatges a altres sessions: always ho permet, ask requereix aprovació humana abans d'enviar-los, i never ho bloqueja. Les respostes sol·licitades i la comunicació autoritzada de tasques delegades conserven els permisos existents.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Àmbit de les sessions de missatges directes`},help:{"v1-ql362c-5l":`Delimitació de l'àmbit de les sessions de missatges directes: "main" manté la continuïtat, mentre que "per-peer", "per-channel-peer" i "per-account-channel-peer" augmenten l'aïllament. Utilitzeu modes aïllats per a safates d'entrada compartides o desplegaments amb diversos comptes.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Àmbit de les sessions de grup`},help:{"v1-1fdezx2-6i":`Àmbit de les sessions de grup/canal: "per-group" manté les sales separades mentre la sessió principal de l'agent les observa en segon pla, independentment de dmScope; "main" integra el context de les sales a la sessió principal i no requereix observació. Utilitzeu "main" només per a sales de confiança.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Enllaços d'identitat de les sessions`},help:{"v1-4mwmyr-5k":`Associa identitats compartides amb identificadors d'interlocutors amb prefix de proveïdor perquè els usuaris equivalents es resolguin en un únic fil de missatges directes (exemple: telegram:123456). Utilitzeu-ho quan la mateixa persona aparegui en diversos canals o comptes.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Clau de la sessió principal`},help:{"v1-18p638h-3q":`S'accepta però s'ignora: el sufix de la sessió principal de cada agent sempre és "main". Ometeu aquest camp; l'àmbit de sessió global utilitza "global" en lloc seu.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Manteniment de les sessions`},help:{"v1-hdyrb-68":`Controls de manteniment automàtic del magatzem de sessions per a l’arxivament de sessions de l’aplicació, la supressió per antiguitat, els límits d’entrades, la conservació d’arxius de sessions reinicialitzades i la neteja segons la quota de disc. Comenceu en mode warn per observar-ne l’impacte i passeu a enforce un cop hàgiu ajustat els llindars.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Arxiva les sessions inactives del tauler després de`},help:{"v1-1krn130-60":"Arxiva les sessions inactives iniciades a l’aplicació OpenClaw un cop transcorregut aquest període (per exemple, `7d`), de manera que continuïn disponibles sense saturar la llista de sessions actives. Establiu-hi `false` o `0` per desactivar aquest arxivament automàtic."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-ogfwwy-h":`Emmagatzematge en fred de xats`},help:{"v1-kqjx1d-5m":`Mou els xats inactius a arxius JSONL comprimits i conserva les metadades de la sessió. Els fitxers d'arxiu esdevenen una part necessària de l'historial i s'han d'incloure a les còpies de seguretat. Els canvis s'apliquen sense reiniciar el Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Dies d'inactivitat abans d'arxivar`},help:{"v1-1f9pk9f-55":`Arxiva els xats després d'aquest nombre de dies d'inactivitat (enter positiu, 30 per defecte). La feina en curs està protegida; els canvis al llindar s'apliquen en la següent execució del procés en segon pla sense reiniciar el Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-17fys4q-v":`Arxiva automàticament els xats antics`},help:{"v1-1sdhnti-5s":`Activa l'arxivament de xats en segon pla (true per defecte). Establiu-lo a false per desactivar les extraccions futures. Un procés de treball comprova cada minut si hi ha xats que compleixin els requisits. Aquesta política d'arxivament és independent de la supressió i de la neteja segons el límit d'espai en disc.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Llindar superior d'espai en disc de les sessions`},help:{"v1-143vh09-7z":`Mida objectiu després de la neteja per límit d'espai en disc (llindar superior). Per defecte és el 80% de maxDiskBytes; definiu-la explícitament per controlar més estrictament l'alliberament d'espai en discos amb capacitat limitada. Si el valor resultant és zero, s'utilitza el valor per defecte; els valors negatius no són vàlids. Per desactivar el límit, utilitzeu maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Límit màxim d'espai en disc de les sessions`},help:{"v1-ocx4rx-cl":'Quota de disc físic per agent que inclou el fitxer principal i el WAL de SQLite, així com els artefactes comptabilitzats del directori de sessions (per exemple, `500mb`). El valor per defecte és `10gb`; les dades protegides poden mantenir l’ús per sobre de l’objectiu. Si se supera, el mode warn informa de la pressió sobre l’espai i el mode enforce elimina els artefactes antics de reinicialització o supressió, l’historial sense referències i, després, els arxius creats en aplicar els límits. Els arxius manuals, de conservació per antiguitat, de sessions de l’aplicació, de recuperació i heretats continuen protegits. Establiu-hi `false`, `0` o `"0"` per desactivar aquesta quota.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Màxim d'entrades de sessió`},help:{"v1-1w2egrh-7u":`Limita les entrades de sessió no arxivades (5000 per defecte). Les converses persistents que superen el límit i compleixen els requisits s'arxiven amb el seu historial; les entrades d'automatització prescindibles s'eliminen. Els arxius existents no compten per al límit. Les entrades actives protegides continuen comptant i poden mantenir el magatzem per sobre del límit.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Mode de manteniment de sessions`},help:{"v1-qhc707-7c":`Determina si les polítiques de purga i de límit d'espai en disc només es notifiquen ("warn") o s'apliquen activament ("enforce"). Manteniu "warn" durant el desplegament i canvieu a "enforce" després de validar uns llindars segurs. L'emmagatzematge en fred està activat per defecte i té una opció pròpia per desactivar-lo.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Conserva les sessions recents`},help:{"v1-138q5wx-89":"Protegeix les sessions interactives actives durant aquest període (per exemple, `7d`) contra l'eliminació automàtica de l'historial per antiguitat, nombre d'entrades i límit d'espai en disc. Si no s'estableix o es configura com a `false`, es manté la política habitual d'eliminar primer les més antigues. Les files sintètiques d'execució de models, cron, hook, polset, ACP i subagents continuen sent aptes per a una neteja limitada."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Purga les sessions després de`},help:{"v1-1xn50w7-76":"Arxiva les converses persistents que compleixen els requisits i elimina les entrades d'automatització prescindibles més antigues que aquesta durada (per defecte, `30d`; per exemple, `12h`). Les converses arxivades conserven l'historial i es poden restaurar; les converses protegides o encaminables continuen actives."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Retenció dels arxius de reinicialització de sessions`},help:{"v1-3rw301-7l":"Retenció basada en l'antiguitat dels xats arxivats (`*.reset.<timestamp>` i `*.deleted.<timestamp>`). Per defecte, els arxius es conserven fins que el límit d'espai en disc obliga a eliminar-los, començant pels més antics; definiu una durada (per exemple, `30d`) per activar l'eliminació segons el temps transcorregut, o `false` per desactivar-la explícitament."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Notifica a la sessió d'inici la creació de sessions`},help:{"v1-14mr1ov-8m":`Posa a la cua un avís del sistema a la sessió d'inici de l'agent propietari quan es crea una sessió (per defecte: true). Els avisos inclouen el títol i les metadades del creador disponibles i es llegeixen al següent torn de la sessió d'inici o en una automatització programada. Establiu false per desactivar-ho; se n'exclouen els esborranys, les sessions d'incògnit, les sessions internes i les execucions cron programades.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Política de reinicialització de sessions`},help:{"v1-1hmt7n3-6r":`Defineix l'objecte de política de reinicialització per defecte que s'utilitza quan no s'aplica cap substitució específica de tipus o de canal. Per defecte, les sessions no es reinicialitzen automàticament; feu servir programacions diàries o per inactivitat per activar-ho, mentre que /new i /reset continuen disponibles en qualsevol moment.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Hora de reinicialització diària de sessions`},help:{"v1-wry8cv-59":`Estableix l'hora local (0-23) del canvi en el mode de reinicialització diària perquè les sessions es renovin en moments previsibles. Feu-la servir amb mode=daily i ajusteu-la al fus horari que espera l'operador per obtenir un comportament fàcil d'interpretar.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Minuts d'inactivitat per al reinici de la sessió`},help:{"v1-1kzj0id-5e":`Estableix el període d'inactivitat abans del reinici en el mode d'inactivitat i també pot actuar com a protecció secundària en el mode diari. Utilitzeu valors més alts per preservar la continuïtat o valors més baixos per tenir fils més recents i de curta durada.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Mode de reinici de la sessió`},help:{"v1-e5ie4w-5b":`Selecciona l'estratègia de reinici: "none" desactiva el reinici automàtic (opció per defecte), "daily" reinicia a una hora configurada i "idle" reinicia després d'un període d'inactivitat. /new i /reset continuen disponibles en tots els modes.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Reinici de la sessió per canal`},help:{"v1-1uxsulx-5h":`Permet definir excepcions de reinici específiques de cada canal, amb l'identificador del proveïdor/canal com a clau, per controlar-ne el comportament amb precisió. Utilitzeu aquesta opció només quan un canal necessiti un comportament de reinici excepcional més enllà de les polítiques per tipus.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Reinici de la sessió per tipus de xat`},help:{"v1-ypdr7u-52":`Sobreescriu el comportament de reinici segons el tipus de xat (directe, grup, fil) quan els valors per defecte no són suficients. Utilitzeu aquesta opció quan l'activitat dels grups o fils necessiti una freqüència de reinici diferent de la dels missatges directes.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Reinici de la sessió (directe)`},help:{"v1-22e702-54":`Defineix la política de reinici dels xats directes i té prioritat sobre la configuració base session.reset per a aquest tipus. Utilitzeu aquesta opció com a configuració específica actual dels missatges directes en lloc de l'àlies antic dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Reinici de la sessió (grup)`},help:{"v1-hl1200-4u":`Defineix la política de reinicialització de les sessions de xat de grup, on els patrons de continuïtat i soroll difereixen dels dels missatges directes. Feu servir períodes d'inactivitat més curts per als grups amb molta activitat si la deriva del context esdevé un problema.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Reinicialització de la sessió (fil)`},help:{"v1-1hgpeke-4w":`Defineix la política de reinicialització de les sessions limitades a un fil, inclosos els fluxos de treball centrats en fils de canals. Feu-la servir quan les sessions de fil hagin de caducar abans o després que les d'altres tipus de xat.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Activadors de reinicialització de la sessió`},help:{"v1-rcabsw-5a":`Enumera els activadors de missatge que forcen la reinicialització d'una sessió quan es detecten al contingut entrant. Feu-los servir amb moderació per a frases de reinicialització explícites, de manera que el context no es perdi inesperadament durant una conversa normal.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Àmbit de la sessió`},help:{"v1-axt4ds-5z":`Estableix l'estratègia bàsica d'agrupació de sessions: "per-sender" les aïlla per remitent i "global" comparteix una sessió per context de canal. Manteniu "per-sender" per a un comportament multiusuari més segur, tret que es requereixi expressament un context compartit.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Política d'enviament de la sessió`},help:{"v1-17zdvww-61":`Controla el lliurament de les sessions mitjançant regles de permís o denegació avaluades segons channel, chatType i els prefixos de clau. Això és independent de l'admissió de missatges entrants i sortints entre interlocutors; feu servir session.communication per a aquests valors per defecte.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Acció per defecte de la política d'enviament de la sessió`},help:{"v1-15plhut-53":`Estableix l'acció alternativa quan no coincideix cap regla de sendPolicy: "allow" o "deny". Manteniu "allow" per a configuracions més senzilles, o trieu "deny" quan necessiteu regles de permís explícites per a cada destinació.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Regles de la política d'enviament de la sessió`},help:{"v1-o217za-5h":`Regles ordenades de permís o denegació que s'avaluen abans de l'acció predeterminada, per exemple \`{ action: "deny", match: { channel: "discord" } }\`. Poseu primer les regles més específiques perquè les regles generals no ocultin les excepcions.`}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Acció de la regla d'enviament de la sessió`},help:{"v1-178vm80-54":`Defineix la decisió de la regla com a "allow" o "deny" quan es compleixen els criteris de coincidència corresponents. Doneu prioritat a les regles de denegació quan apliqueu límits estrictes amb excepcions explícites de permís.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Coincidència de la regla d'enviament de la sessió`},help:{"v1-18qh5qg-5d":`Defineix condicions opcionals de coincidència de la regla que poden combinar restriccions de channel, chatType i prefix de clau. Manteniu les coincidències específiques perquè la intenció de la política sigui clara i la depuració continuï sent senzilla.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Canal de la regla d'enviament de la sessió`},help:{"v1-u5erwx-50":`Aplica la regla quan coincideix amb un identificador de canal o proveïdor específic (per exemple, discord, telegram, slack). Feu servir aquesta opció quan un canal hagi de permetre o denegar el lliurament independentment dels altres.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Tipus de xat de la regla d'enviament de la sessió`},help:{"v1-7cv4f9-4z":`Aplica la regla segons el tipus de xat (direct, group, thread) perquè el comportament variï segons la forma de conversa. Feu servir aquesta opció quan les destinacions de missatges directes i de grup requereixin límits de seguretat diferents.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Prefix de clau de la regla d'enviament de la sessió`},help:{"v1-ac4dee-5n":`Comprova la coincidència amb un prefix normalitzat de clau de sessió després dels passos interns de normalització de claus dels components que apliquen la política. Feu-lo servir per a controls generals de prefix i prioritzeu rawKeyPrefix quan calgui una coincidència exacta amb la clau completa.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Prefix de clau sense normalitzar de la regla d'enviament de sessió`},help:{"v1-1g9w044-5e":`Comprova la coincidència amb el prefix original, sense normalitzar, de la clau de sessió per aplicar la política a claus completes exactes. Feu-lo servir quan el keyPrefix normalitzat sigui massa ampli i calgui precisió amb prefixos d'agent o específica del transport.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Modes de compartició de sessions`},help:{"v1-xbh52d-5a":`Controla quins modes de col·laboració poden seleccionar els propietaris de les sessions i els administradors. Els booleans omesos es consideren activats per defecte; establiu un mode a false per eliminar-lo del selector i rebutjar-ne noves seleccions.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Permet sessions d'esborrany`},help:{"v1-1lzap27-2p":`Permet la visibilitat d'esborrany, que oculta les sessions als operadors que no en són propietaris ni administradors. Valor per defecte: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Permet sessions de només lectura`},help:{"v1-upl3nu-21":`Permet establir les sessions com a només lectura per a les persones que no hi participen. Valor per defecte: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Permet sessions amb suggeriments`},help:{"v1-4i8owu-4g":`Permet la visibilitat amb suggeriments. En aquesta fase aplica la mateixa política d'admissió que el mode de només lectura; les cues de suggeriments es configuren mitjançant una funcionalitat posterior. Valor per defecte: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Camí del magatzem de sessions`},help:{"v1-hreznz-56":`Defineix el camí del fitxer d'emmagatzematge de sessions que s'utilitza per conservar els registres de sessió entre reinicis. Utilitzeu un camí explícit només si necessiteu una disposició de disc personalitzada, una destinació específica per a les còpies de seguretat o emmagatzematge en un volum muntat.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Vinculacions de sessions a fils`},help:{"v1-zbzihu-4s":`Valors predeterminats compartits per a la creació i l'encaminament de sessions vinculades a fils als canals compatibles. Configureu aquí els valors predeterminats globals i sobreescriviu-los per canal només quan el comportament sigui diferent.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Context de creació en fils`},help:{"v1-gnhqsg-46":`Context natiu predeterminat del subagent per a les instàncies creades vinculades a un fil. Feu servir "fork" per partir del xat del sol·licitant o "isolated" per crear una instància filla sense context previ. Valor predeterminat: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Vinculació a fils activada`},help:{"v1-foomtc-3f":`Interruptor general per a la creació, l'encaminament i el lliurament de sessions vinculades a fils. Desactiveu-lo per desactivar globalment la vinculació a fils.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Temps límit d'inactivitat de la vinculació a fils (hores)`},help:{"v1-gffnx3-3h":`Període d'inactivitat predeterminat en hores per a les sessions vinculades a fils entre proveïdors i canals (0 desactiva la caducitat per inactivitat). Valor predeterminat: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Durada màxima de la vinculació a fils (hores)`},help:{"v1-1xfcyhw-39":`Límit màxim absolut opcional de durada en hores per a les sessions vinculades a fils entre proveïdors i canals (0 desactiva el límit absolut). Valor predeterminat: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Creació de sessions vinculades a fils`},help:{"v1-1lqwbdl-46":`Control global per defecte per crear sessions de treball vinculades a fils des de sessions_spawn i les creacions de fils ACP. Valor per defecte: true quan els vincles a fils estan habilitats.`}},skills:{label:{"v1-1bk7xrz-6":`Habilitats`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Destinacions permeses dels enllaços simbòlics d'habilitats`},help:{"v1-xzybiq-4t":`Directoris arrel de destinació reals i de confiança als quals poden apuntar els enllaços simbòlics d'habilitats quan són fora del directori arrel d'origen configurat. Limiteu-ne l'abast, per exemple, a un directori d'habilitats d'un repositori veí.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Directoris addicionals d'habilitats`},help:{"v1-11o7opu-53":`Directoris arrel addicionals d'habilitats compartides que s'exploraran amb la prioritat més baixa. Feu-los servir per a repositoris veïns o paquets d'habilitats compartits que hagin d'estar disponibles sense copiar-los a l'espai de treball d'OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Supervisa les habilitats`},help:{"v1-1g8a3b0-8g":`Habilita la descoberta d'habilitats activada pel sistema de fitxers, amb una exploració de seguretat cada 30 minuts per detectar esdeveniments omesos. Si es deshabilita, els canvis explícits en les habilitats d'OpenClaw, els canvis de configuració rellevants i l'inici de la Passarel·la continuen actualitzant les habilitats immediatament. Les sessions existents fan servir les instantànies modificades en el torn següent de l'agent.`}},storage:{label:{"v1-eop0jq-7":`Emmagatzematge`},help:{"v1-j0mwbg-4w":`Ubicacions d'emmagatzematge reutilitzables per als artefactes d'OpenClaw. El nucli d'emmagatzematge gestiona la identitat, el xifratge i l'estat de les ubicacions; els proveïdors transporten els objectes i els consumidors decideixen què cal conservar.`}},"storage%2Elocations":{label:{"v1-uok3ae-h":`Ubicacions d'emmagatzematge`},help:{"v1-1ipmwky-5k":`Destinacions d'emmagatzematge amb nom. Els noms contenen entre 1 i 63 lletres minúscules, dígits o guionets i comencen amb una lletra o un dígit. Cada destinació conserva un marcador d'inicialització que les escriptures en temps d'execució no creen mai.`}},"storage%2Elocations%2E*":{label:{"v1-1pbn8xd-g":`Ubicació d'emmagatzematge`},help:{"v1-7yhxyl-4n":`Una destinació d'emmagatzematge amb nom, amb la configuració del proveïdor i una opció de xifratge explícita. Inicialitza una destinació nova amb openclaw storage init abans d'escriure-hi objectes.`}},"storage%2Elocations%2E*%2Eencryption":{label:{"v1-1qp46kf-i":`Xifratge de l'emmagatzematge`},help:{"v1-19oj6cx-6d":`Opció de xifratge obligatòria: un objecte amb frase de contrasenya xifra els objectes abans de pujar-los; "none" desactiva explícitament el xifratge. Les còpies de seguretat poden contenir credencials, així que utilitza "none" només quan la destinació ja ofereixi una protecció adequada.`}},"storage%2Elocations%2E*%2Eencryption%2Epassphrase":{label:{"v1-1x3jq0t-t":`Frase de contrasenya del xifratge de l'emmagatzematge`},help:{"v1-1o63v7d-4o":`Frase de pas utilitzada per xifrar aquesta ubicació. És preferible utilitzar un SecretRef i conservar-ne una còpia recuperable: perdre o canviar la frase de pas fa que els objectes xifrats existents siguin il·legibles.`}},"storage%2Elocations%2E*%2Eprovider":{label:{"v1-1dujppr-g":`Proveïdor d'emmagatzematge`},help:{"v1-16srbor-3w":`Identificador del proveïdor d'emmagatzematge, com ara "filesystem". Fer referència a un proveïdor inclòs activa automàticament el seu connector, tret que la política de connectors el desactivi.`}},"storage%2Elocations%2E*%2Esettings":{label:{"v1-268wio-p":`Configuració del proveïdor d'emmagatzematge`},help:{"v1-drbso5-5t":`Configuració JSON delimitada i gestionada pel proveïdor. Els valors que contenen secrets han d'utilitzar objectes SecretRef, que el proveïdor resol només quan cal. El proveïdor filesystem requereix un camí absolut a un directori existent.`}},surfaces:{label:{"v1-exl2ye-g":`Polítiques de superfície`},help:{"v1-vgtjbs-50":`Excepcions a la política de missatges per superfície, indexades per l'identificador resolt de la superfície de lliurament. Utilitzeu-les només quan una superfície desplegada necessiti una gestió de les respostes silencioses més estricta que la predeterminada de l'agent.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Política de resposta silenciosa de la superfície`},help:{"v1-1un880p-4z":`Substitueix la política de resposta silenciosa de grup per a una superfície de lliurament resolta. Els camps sense definir hereten agents.defaults.silentReply. Els xats directes i les sessions internes sempre requereixen una resposta.`}},talk:{label:{"v1-15ukbjj-4":`Conversa`},help:{"v1-1gx10xa-5g":`Configuració de síntesi de veu del mode de conversa per a la identitat de la veu, la selecció del model, el format de sortida i el comportament davant d'interrupcions. Utilitzeu aquesta secció per ajustar l'experiència de veu de l'usuari tot controlant la latència i el cost.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Agent de conversa`},help:{"v1-iee5l9-2b":`Agent al qual pertanyen les sessions de Talk creades sense una clau de sessió explícita vinculada a un agent.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Mode ràpid de consulta de Talk`},help:{"v1-syf3xk-2o":`Permet establir el mode ràpid a true o false per a l'execució habitual de l'agent que hi ha darrere de les consultes en temps real de Talk.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Nivell de raonament de consulta de Talk`},help:{"v1-1ft5njw-2o":`Permet substituir el nivell de raonament per a l'execució habitual de l'agent que hi ha darrere de les consultes en temps real de Talk.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Interrupció de Talk en parlar`},help:{"v1-8n9q4o-3l":`Si és true (per defecte), atura la veu de l'assistent quan l'usuari comença a parlar en mode Talk. Manteniu aquesta opció activada per alternar els torns de conversa.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Proveïdor actiu de Talk`},help:{"v1-wgnxhg-1g":`Identificador del proveïdor actiu de Talk (per exemple, "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Configuració dels proveïdors de Talk`},help:{"v1-oh0yuv-30":`Configuració de Talk específica de cada proveïdor, indexada per l'identificador del proveïdor. Durant la migració, prioritzeu aquesta configuració respecte de les claus antigues talk.*.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Configuració del proveïdor de Talk`},help:{"v1-36pblg-1r":`Camps de configuració de Talk propis del proveïdor amb l'identificador corresponent.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Clau d'API del proveïdor de Talk`},help:{"v1-1a1p9wp-v":`Clau d'API del proveïdor per al mode Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk en temps real`},help:{"v1-c2re7j-3z":`Proveïdor, model, veu, mode, transport i estratègia de raonament de Talk en temps real. Manteniu la configuració del proveïdor de veu/TTS a talk.provider i talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Cervell de Talk en temps real`},help:{"v1-opsatw-37":`Estratègia de raonament de Talk: agent-consult per obtenir ajuda d'un agent mitjançant la Passarel·la, direct-tools per a crides locals a eines, o none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Encaminament de consultes de Talk en temps real`},help:{"v1-10qjcvk-5f":`Retransmissió alternativa a través de la Passarel·la per a les transcripcions finals de l'usuari quan el proveïdor en temps real omet openclaw_agent_consult. provider-direct conserva les respostes del proveïdor; force-agent-consult les encamina a través d'OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Instruccions de Talk en temps real`},help:{"v1-1jaaj84-5p":`Instruccions de sistema addicionals que s'afegeixen a la indicació integrada de Talk en temps real d'OpenClaw. Feu-les servir per definir l'estil de veu, el to i altres comportaments en temps real del proveïdor, tot mantenint intactes les directrius d'agent-consult.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Mode de Talk en temps real`},help:{"v1-1u2xui1-1l":`Mode d'execució de Talk: realtime, stt-tts o transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Model de Talk en temps real`},help:{"v1-amou5a-27":`Substitució de l'identificador del model del proveïdor en temps real per a les sessions de Talk del navegador o gestionades per la Passarel·la.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Marge previ de Talk en temps real (ms)`},help:{"v1-1cwg07n-22":`Mil·lisegons d'àudio conservats abans que es detecti activitat de veu en temps real.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Proveïdor de Talk en temps real`},help:{"v1-wwsmpt-1o":`Identificador del proveïdor de veu en temps real actiu, com ara openai o google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Configuració dels proveïdors de Talk en temps real`},help:{"v1-ruagcu-1r":`Configuració de veu en temps real específica de cada proveïdor, indexada per l'identificador del proveïdor.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Configuració del proveïdor de Talk en temps real`},help:{"v1-edfpxm-1u":`Configuració de veu en temps real pròpia del proveïdor amb l'identificador corresponent.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Clau d'API del proveïdor de Talk en temps real`},help:{"v1-1fbmgpx-z":`Clau d'API del proveïdor per a Talk en temps real.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Esforç de raonament de Talk en temps real`},help:{"v1-157xd3e-2t":`Esforç de raonament específic del proveïdor per a les sessions de Talk en temps real, com ara mínim, baix, mitjà o alt.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Durada del silenci de Talk en temps real (ms)`},help:{"v1-1grnu06-1y":`Mil·lisegons de silenci abans de confirmar un torn de l'usuari de Talk en temps real.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Veu del parlant de Talk en temps real`},help:{"v1-1kgb166-2h":`Substitució del nom de la veu del parlant del proveïdor en temps real per a les sessions de Talk del navegador o gestionades per la Passarel·la.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Identificador de la veu del parlant de Talk en temps real`},help:{"v1-1k8w6vk-2f":`Substitució de l'identificador de la veu del parlant del proveïdor en temps real per a les sessions de Talk del navegador o gestionades per la Passarel·la.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Transport de Talk en temps real`},help:{"v1-2otjgn-2g":`Transport de bytes/sessions de Talk: webrtc, provider-websocket, gateway-relay o managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Llindar de VAD de Talk en temps real`},help:{"v1-nf5l2t-2j":`Llindar de detecció d'activitat de veu en temps real, de 0 (màxima sensibilitat) a 1 (mínima sensibilitat).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Temps d'espera de silenci de Talk (ms)`},help:{"v1-1kim32f-59":`Mil·lisegons de silenci de l'usuari abans que el mode Talk finalitzi i enviï la transcripció actual. Deixeu-ho sense definir per mantenir l'interval de pausa predeterminat de la plataforma (700 ms a macOS i Android, 900 ms a iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Configuració regional de veu de Talk`},help:{"v1-1un3x4l-4c":`Identificador de configuració regional BCP 47 per al reconeixement de veu de Talk als nodes de dispositiu i per a la veu del sistema d'iOS utilitzada com a alternativa, per exemple "ru-RU". Deixeu-ho sense definir per utilitzar el valor predeterminat de cada dispositiu.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetria`},help:{"v1-1o5tru3-55":`Consentiment explícit per a les estadístiques anònimes d'ús de funcions que s'adjunten a la comprovació diària d'actualitzacions. Les estadístiques d'ús de funcions estan desactivades per defecte i no inclouen mai missatges, credencials ni identificadors.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Marca de temps del consentiment per a les estadístiques d'ús de funcions`},help:{"v1-1t051az-3t":`Marca de temps ISO que registra quan l'operador ha acceptat o rebutjat les estadístiques anònimes d'ús de funcions. Evita que l'assistent de configuració ho torni a preguntar.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Estadístiques anònimes d'ús de funcions`},help:{"v1-1ptrwuq-4r":`Comparteix els noms dels canals i proveïdors activats, el nombre de connectors i el nombre de sessions recents amb la comprovació diària d'actualitzacions. Està desactivat per defecte i sempre que DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Eines`},help:{"v1-1el54kl-5h":`Infraestructura d'eines i valors predeterminats compartits entre agents. Les entrades del mateix nivell de l'arrel gestionen la infraestructura i els valors predeterminats compartits entre agents; agents.defaults gestiona el comportament del bucle de l'agent; les entrades dels agents poden sobreescriure qualsevol dels dos quan s'admeti.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Accés a eines entre agents`},help:{"v1-1ynpa5f-cf":`Política per a les crides a eines de sessió entre agents: enviaments, llistat, historial, cerca i lectures d'estat (per defecte: activada). Utilitzeu allow per restringir les parelles d'agents; enabled=false bloqueja l'accés ordinari entre agents. Les sessions de subagents natius i les sessions filles ACP que pertanyen al sol·licitant continuen sent accessibles amb la visibilitat tree o all. Per a una separació estricta, establiu tools.sessions.visibility a agent o self (tree encara admet les sessions filles natives/ACP del sol·licitant), o utilitzeu passarel·les separades.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Llista de destinataris permesos entre agents`},help:{"v1-1jt2ari-76":`Identificadors d'agents o patrons amb * que poden participar en crides entre agents; tant l'agent sol·licitant com el destinatari han de coincidir amb algun dels valors. L'accés entre agents està activat per defecte, i si allow s'omet o és buit, es permet qualsevol parella. Definiu una llista explícita per restringir l'accés; les entrades en blanc el deneguen.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Activa l'eina entre agents`},help:{"v1-w950oq-ba":`Activa l'accés a eines de sessió entre agents (per defecte: true); si allow s'omet o és buit, es permet qualsevol parella d'agents. Establiu false per bloquejar l'accés ordinari entre agents; les sessions de subagents natius i les sessions filles ACP que pertanyen al sol·licitant continuen sent accessibles amb la visibilitat tree o all. Per a una separació estricta, establiu tools.sessions.visibility a agent o self (tree encara admet les sessions filles natives/ACP del sol·licitant), o utilitzeu passarel·les separades.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Llista d'eines permeses`},help:{"v1-1is3eaq-4v":`Llista absoluta d'eines permeses que substitueix els valors predeterminats derivats del perfil per a entorns estrictes. Utilitzeu-la només quan vulgueu executar deliberadament un subconjunt de funcionalitats de les eines seleccionat amb cura.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Addicions a la llista d'eines permeses`},help:{"v1-1xw9zp8-57":`Entrades addicionals de la llista d'eines permeses que es combinen amb el perfil d'eines seleccionat i la política predeterminada. Manteniu aquesta llista curta i explícita perquè les auditories puguin identificar ràpidament les excepcions intencionades a la política.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Política d'eines per proveïdor`},help:{"v1-c1lj2f-bh":`Excepcions per proveïdor als permisos i les denegacions d'eines, indexades per l'ID de canal/proveïdor, per adaptar les capacitats a cada interfície. Feu-les servir quan un proveïdor necessiti controls més estrictes que la política global d'eines. exec.mode estableix un límit d'execució a l'amfitrió que només pot afegir restriccions per als torns d'aquest proveïdor o d'aquesta combinació de proveïdor/model (mai no elimina les aprovacions obligatòries ni relaxa un mode més estricte), de manera que el mode "auto" sotmet al revisor d'execucions només les execucions d'aquest model que no coincideixen amb les regles.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Mode de codi`},help:{"v1-1ecc39k-6k":"Mode de codi genèric d'OpenClaw. Si s'omet globalment, el valor predeterminat és `\"auto\"`; un objecte definit sense `enabled` es manté desactivat. Les execucions d'agents amb aquest mode activat només exposen `exec` i `wait` al model i accedeixen a les eines habituals a través del pont del catàleg."}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Activa el mode de codi`},help:{"v1-c7oqjw-ah":"Activació global del mode de codi d'OpenClaw. Si la configuració global és completament absent, el valor predeterminat és `\"auto\"`; un objecte definit sense `enabled` es manté desactivat. `\"auto\"` activa el mode per als models preferits pel catàleg, mentre que `true` l'activa per a les execucions amb capacitat d'utilitzar eines. Les excepcions d'activació per agent i model tenen prioritat. Si l'entorn d'execució no està disponible, es bloqueja l'execució amb el mode activat en lloc d'exposar la llista completa d'eines."}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Executor del mode de codi`},help:{"v1-4tbmdg-7h":`Executor de JavaScript: "node" (predeterminat) utilitza Node vm per a codi de confiança i no és un entorn aïllat de seguretat; "quickjs" utilitza el connector QuickJS WASM inclòs per executar codi convidat amb seguretat reforçada. Els permisos d'eines s'apliquen a tots dos. El mode de codi no es pot executar si l'executor seleccionat no està disponible.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Límit de sortida del mode de codi`},help:{"v1-1hmij9q-1n":`Nombre màxim de bytes serialitzats retornats a través de la sortida del mode de codi.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Límit de crides pendents a eines del mode de codi`},help:{"v1-3b5tyd-2i":`Nombre màxim de crides imbricades simultànies a eines que una màquina virtual del mode de codi pot iniciar abans d'haver de reprendre l'execució més tard.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Nombre màxim de resultats de cerca del mode de codi`},help:{"v1-1gpue5r-28":`Nombre màxim de resultats de cerca del catàleg ocult que un programa del mode de codi pot sol·licitar.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Límit de les instantànies del mode de codi`},help:{"v1-1mmgkqy-1x":`Nombre màxim de bytes serialitzats conservats per a una instantània suspesa de QuickJS.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Límit de memòria del mode de codi`},help:{"v1-xetora-6n":`Límit de memòria dinàmica del convidat QuickJS o pressupost aproximat de memòria dinàmica V8 del procés de treball de Node, en bytes. La sobrecàrrega de l'entorn d'execució de Node i les assignacions mínimes del motor afecten el pressupost efectiu; se n'exclouen els búfers externs i la memòria resident (RSS) del procés. Això no és una garantia de seguretat.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Interfície del mode de codi`},help:{"v1-dsp2b9-2x":'Interfície exposada al model. Només s\'admet "only": exposa `exec` i `wait` del mode de codi i amaga les eines normals.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Nombre predeterminat de resultats de cerca del mode de codi`},help:{"v1-1io42lu-2m":"Nombre predeterminat de resultats de cerca del catàleg ocult retornats per `catalog.search` dins del mode de codi."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`TTL de les instantànies del mode de codi`},help:{"v1-1nxfczz-28":"Temps durant el qual es poden reprendre les execucions suspeses del mode de codi amb `wait` abans que caduquin."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Temps d'espera del mode de codi`},help:{"v1-8csycm-1p":"Nombre màxim de mil·lisegons per a una crida `exec` o `wait` del mode de codi."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Llista d'eines denegades`},help:{"v1-wilr1b-4p":`Llista global d'eines denegades que bloqueja les eines incloses encara que les regles del perfil o del proveïdor les permetin. Feu servir regles de denegació per a bloquejos d'emergència i per a una defensa en profunditat a llarg termini.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Accés elevat a les eines`},help:{"v1-ehcm0r-5a":`Controls d'accés elevat a les eines per a interfícies d'ordres privilegiades que només haurien de ser accessibles per a remitents de confiança. Manteniu aquest accés desactivat tret que els fluxos de treball de l'operador requereixin explícitament accions amb privilegis elevats.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Regles d'autorització d'eines amb privilegis elevats`},help:{"v1-1u9bhih-54":`Regles d'autorització de remitents per a eines amb privilegis elevats, normalment amb claus basades en els formats d'identitat del canal o del proveïdor. Feu servir identitats explícites i ben delimitades perquè els usuaris no previstos no puguin activar ordres amb privilegis elevats.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Activa l'accés elevat a les eines`},help:{"v1-1n8oyal-4l":`Habilita la via d'execució d'eines amb privilegis elevats quan se superen les comprovacions del remitent i de les polítiques. Manteniu-la desactivada en canals públics o compartits i activeu-la només en contextos de confiança gestionats pel propietari.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Eina exec`},help:{"v1-p5piic-56":`Agrupació de polítiques de l'eina exec per a l'amfitrió d'execució de l'intèrpret d'ordres, el mode de seguretat, el comportament d'aprovació i les vinculacions en temps d'execució. Manteniu valors predeterminats conservadors en producció i restringiu les vies d'execució amb privilegis elevats.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Llista de models permesos per a apply_patch`},help:{"v1-4q5ovf-1x":`Llista opcional d'identificadors de models permesos (p. ex., "gpt-5.4" o "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Activa apply_patch`},help:{"v1-1erkir4-31":`Activa o desactiva apply_patch per als models d'OpenAI i OpenAI Codex quan la política d'eines ho permeti (per defecte: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch només a l'Espai de treball`},help:{"v1-1m4u5cn-4l":`Restringeix els camins d'apply_patch de l'amfitrió al directori de l'espai de treball (per defecte: false). Estableix-ho a true per limitar l'accés a l'espai de treball; els directoris arrel obligatoris i les restriccions de sessió es continuen aplicant.`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Avís d'execució en curs després de l'aprovació d'exec (ms)`},help:{"v1-1gwwann-4z":`Retard en mil·lisegons abans de mostrar un avís d'execució en curs després de concedir una aprovació d'exec. Augmenta'l per reduir el parpelleig en ordres ràpides o redueix-lo per informar l'operador més aviat.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Sol·licitud de confirmació d'exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Ressaltat d'ordres d'exec`},help:{"v1-kyxd4o-4n":`Mostra el ressaltat d'ordres generat per l'analitzador a les sol·licituds d'aprovació d'exec (per defecte: false). Activa aquesta opció per mostrar el text de les ordres ressaltat sense canviar la política d'aprovació d'exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Caducitat de l'autorització permanent (dies)`},help:{"v1-5uxe2j-6r":`Durada predeterminada, en dies (1-3650), de les autoritzacions permanents creades per allow-always en les aprovacions d'automatitzacions. Si no es defineix, les autoritzacions continuen sent vàlides fins que es revoquen o es modifica l'automatització a la qual pertanyen. Les condicions es fixen en crear-les, de manera que els canvis només afecten les autoritzacions futures.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Destinació d'execució`},help:{"v1-rno1mf-5q":`Selecciona l'estratègia de destinació d'execució per a les ordres de l'intèrpret. Utilitzeu "auto" per adaptar el comportament a l'entorn d'execució (entorn aïllat quan estigui disponible; en cas contrari, passarel·la), o fixeu explícitament sandbox/gateway/node quan necessiteu un entorn fix.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Mode d'execució`},help:{"v1-1qscgnt-5q":`Selector normalitzat de la política d'execució. Utilitzeu "auto" perquè un classificador revisi els casos sense aprovació, "ask" perquè els revisi una persona, "allowlist" per a les ordres aprovades mitjançant regles fixes, o "full" per a operacions locals de confiança.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Vinculació del node d'execució`},help:{"v1-rfnz54-4s":`Configuració de la vinculació de nodes per a les eines d'execució quan l'execució d'ordres es delega a través de nodes connectats. Utilitzeu una vinculació explícita de nodes només quan calgui encaminament entre diversos nodes.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Notificació en finalitzar l'execució`},help:{"v1-eyedrx-3r":`Quan és true (valor predeterminat), la finalització de les sessions d'execució en segon pla i els esdeveniments del cicle de vida de l'execució en nodes posen a la cua un seguiment per a la sessió d'origen.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Notificació d'execució correcta sense sortida`},help:{"v1-l4v70o-6g":`Quan és true (valor per defecte), les execucions d'exec en segon pla que finalitzen correctament amb una sortida buida també reactiven la sessió d'origen, de manera que un procés en espera silenciós informa del resultat. Establiu-ho a false per no notificar les finalitzacions correctes sense sortida; aleshores l'agent les recull amb process poll.`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Anteposició a PATH per a l'execució`},help:{"v1-s1aimc-1r":`Directoris que s'han d'afegir al principi de PATH per a les execucions d'exec (passarel·la/entorn aïllat).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Revisor d'exec`},help:{"v1-12y548k-4x":`Revisor d'exec basat en un model que s'utilitza en mode automàtic abans de recórrer a l'aprovació humana. Configureu aquí un model alternatiu específic si voleu aïllar la revisió d'exec del model de l'agent principal.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Mode ràpid del revisor d'exec`},help:{"v1-175bx14-8u":`Mode ràpid opcional per a les revisions d'aprovació d'OpenClaw: true sol·licita processament prioritari a les rutes compatibles d'OpenAI Responses i ChatGPT/OAuth; false sol·licita processament estàndard. Ometeu-lo per conservar els valors predeterminats del proveïdor. El mode ràpid pot tenir un cost superior i està subjecte a la disponibilitat del proveïdor. No configura el Codex Guardian natiu.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Model del revisor d'exec`},help:{"v1-1lltiy5-3i":`Proveïdor/model alternatiu opcional per a l'agent revisor d'exec. Ometeu-lo per reutilitzar el model principal configurat per a l'agent de destinació.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Raonament del revisor d'exec`},help:{"v1-yg2gby-6u":`Esforç de raonament opcional per a les revisions d'aprovació d'OpenClaw basades en models: minimal, low, medium, high, xhigh o max. Ometeu-lo per conservar els valors predeterminats del proveïdor. Els nivells compatibles es normalitzen per al model seleccionat. No configura el Codex Guardian natiu.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Temps d'espera del revisor d'exec (ms)`},help:{"v1-1o30chi-3w":`Temps d'espera del revisor d'exec per etapa, en mil·lisegons, per a la preparació del model i la generació de la resposta abans de recórrer a l'aprovació humana (valor predeterminat: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Perfils de binaris segurs per a l'execució`},help:{"v1-4cdcwe-29":`Perfils opcionals de binaris segurs per a cada binari (límits posicionals + opcions permeses/denegades).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Binaris segurs per a l'execució`},help:{"v1-1of1m2s-21":`Permet executar binaris segurs que només utilitzen stdin sense entrades explícites a la llista de permesos.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Directoris de confiança dels binaris segurs per a l'execució`},help:{"v1-zljbcn-2v":`Directoris addicionals designats explícitament com a fiables per a les comprovacions de camins dels binaris segurs (les entrades de PATH mai no es consideren fiables automàticament).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Seguretat de l'execució`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Requereix aprovació per a l'avaluació de codi en línia`},help:{"v1-jkmgo7-5z":"Requereix aprovació explícita per a les formes d'avaluació de codi en línia dels intèrprets, com ara `python -c`, `node -e`, `ruby -e` o `osascript -e`. Impedeix la reutilització silenciosa de la llista de permesos i, per a aquestes formes, substitueix el permís permanent per una sol·licitud d'aprovació cada vegada."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Temps d'espera de l'execució (segons)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Eines del sistema de fitxers limitades a l'espai de treball`},help:{"v1-1mhuvka-2s":`Restringeix les eines del sistema de fitxers (read/write/edit/apply_patch) al directori de l'espai de treball (per defecte: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Identitat de GitHub CLI i autor de Git`},help:{"v1-1fl77im-5s":`Perfil local gestionat de GitHub CLI i autor de Git opcional per a les eines de l'agent. Ometeu aquest objecte per conservar el compte i l'autor natius de l'usuari que executa la Passarel·la; les credencials remotes del repositori no se sobreescriuen mai.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Correu electrònic de l'autor de Git`},help:{"v1-kol5g6-1i":`Adreça electrònica opcional de l'autor i del confirmador de Git, local al procés.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Nom de l'autor de Git`},help:{"v1-z5bl1f-1h":`Nom opcional de l'autor i del confirmador de Git, local al procés.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Tipus de credencial de GitHub`},help:{"v1-qi3qun-3q":`Marca un perfil OAuth gestionat amb una credencial de renovació rotativa que és propietat de la Passarel·la. Els perfils que ometen aquest camp utilitzen un testimoni d'accés personal.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Versió del perfil de GitHub`},help:{"v1-4lzl0-27":`Versió de perfil generada i opaca que s'utilitza per canviar les credencials gestionades de manera atòmica.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Activa la comprensió d'enllaços`},help:{"v1-23t2io-59":`Activa el preprocessament automàtic de comprensió d'enllaços perquè es pugui resumir el contingut dels URL abans del raonament de l'agent. Mantén-lo activat per obtenir un context més ric i desactiva'l quan calgui limitar el processament al mínim estricte.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Nombre màxim d'enllaços per a la comprensió d'enllaços`},help:{"v1-ksxmcv-52":`Nombre màxim d'enllaços ampliats per torn durant la comprensió d'enllaços. Utilitza valors més baixos per controlar la latència i el cost en fils amb molts missatges, i valors més alts quan el context de diversos enllaços sigui essencial.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Models de comprensió d'enllaços`},help:{"v1-6j3mnw-5a":`Llista de models preferits per a les tasques de comprensió d'enllaços, avaluats per ordre com a alternatives quan s'admeti. Utilitza primer models lleugers per als resums habituals i models més pesants només quan calgui.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Abast de la comprensió d'enllaços`},help:{"v1-183cwpa-55":`Controla quan s'executa la comprensió d'enllaços segons el context de la conversa i el tipus de missatge. Manteniu un abast restringit per evitar consultes innecessàries en missatges amb enllaços que no requereixen cap acció.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Temps d'espera de la comprensió d'enllaços (s)`},help:{"v1-61v30o-4p":`Temps màxim d'espera en segons per a la comprensió de cada enllaç abans d'ometre els enllaços no resolts. Manteniu aquest límit acotat per evitar esperes llargues quan els llocs externs són lents o inaccessibles.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-108r5c7-h":`Protecció contra la repetició d'eines`},help:{"v1-wrvlew-5k":`Controla la protecció contra la repetició d'eines. Aquesta protecció afegeix una nota de redirecció a la tercera crida consecutiva idèntica a una eina i finalitza el torn a la vintena. Ometeu aquesta opció o establiu-la en true per mantenir-la activada; establiu-la en false per desactivar-la.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Política de fitxers adjunts per a la comprensió d'àudio`},help:{"v1-1s3t9s5-3o":`Trieu quins fitxers d'àudio adjunts que compleixen els criteris es processen. Processeu només el primer, tret que vulgueu transcriure diversos fitxers adjunts.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Format de reproducció de la transcripció`},help:{"v1-glpdzh-3i":`Doneu format a la transcripció reproduïda amb el marcador {transcript}. Manteniu el marcador intacte perquè el missatge enviat inclogui la transcripció.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Reprodueix la transcripció al xat`},help:{"v1-1dedp8c-3r":`Reprodueix la transcripció de l'àudio al xat d'origen abans que l'agent la processi. Activeu aquesta opció quan els usuaris necessitin verificar què ha sentit el sistema.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Activa la comprensió d'àudio`},help:{"v1-1v0x7te-2m":`Activa la comprensió d'àudio perquè les notes de veu o els clips d'àudio es puguin transcriure per al context de l'agent.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Idioma de la comprensió d'àudio`},help:{"v1-1ruqt97-3z":`Indicació d'idioma per defecte per als proveïdors de transcripció d'àudio. Estableix-la quan es conegui l'idioma principal parlat i la detecció del proveïdor no sigui fiable.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Màxim de bytes de la comprensió d'àudio`},help:{"v1-1mcckc8-43":`Límit de mida de l'àudio d'entrada per defecte per als models configurats i detectats automàticament. Estableix-lo segons la gravació més gran que els proveïdors i la xarxa hagin d'acceptar.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Màxim de caràcters de la comprensió d'àudio`},help:{"v1-eo1dp-43":`Longitud màxima de transcripció per defecte per als models configurats i detectats automàticament. Utilitza un valor més baix per evitar que les notes de veu llargues ampliïn el context de l'agent.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Model preferit de comprensió d'àudio`},help:{"v1-1n5zya1-3c":`Dona preferència a una entrada de tools.media.models etiquetada per capacitat per a la transcripció d'àudio abans de recórrer a la resta d'alternatives compatibles.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Instrucció de comprensió d'àudio`},help:{"v1-1v5jtay-4b":`Instrucció de transcripció d'àudio per defecte quan una entrada de model no la substitueix. Mantén la instrucció estable quan els fluxos de treball posteriors depenguin de l'estil de la transcripció.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Abast de la comprensió d'àudio`},help:{"v1-1pptfg0-3w":`Restringiu la comprensió d'àudio per canal, tipus de xat o clau d'origen. Manteniu un abast limitat quan la transcripció automàtica sigui delicada o costosa.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Temps d'espera de la comprensió d'àudio (s)`},help:{"v1-n8wc6c-3b":`Temps d'espera predeterminat per a les sol·licituds de comprensió d'àudio. Augmenteu-lo per a enregistraments llargs o models locals de transcripció més lents.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Concurrència de la comprensió multimèdia`},help:{"v1-13kr9np-58":`Nombre màxim d'operacions simultànies de comprensió multimèdia per torn entre les tasques d'imatge, àudio i vídeo. Reduïu-lo en desplegaments amb recursos limitats per evitar la saturació de la CPU o de la xarxa.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Política d'adjunts de la comprensió d'imatges`},help:{"v1-11hofbw-3e":`Trieu quines imatges adjuntes que compleixin els criteris es processen. Processeu només la primera, tret que vulgueu analitzar diverses imatges.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Activa la comprensió d'imatges`},help:{"v1-1b2zw34-50":`Activeu la comprensió d'imatges perquè les imatges adjuntes o referenciades es puguin interpretar com a context textual. Desactiveu-la si necessiteu treballar només amb text o voleu evitar el cost del processament d'imatges.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Màxim de bytes de la comprensió d'imatges`},help:{"v1-jwwpd1-3v":`Límit predeterminat de mida de les imatges d'entrada per als models configurats i detectats automàticament. Ajusteu-lo als límits de càrrega útil del proveïdor i a l'amplada de banda del desplegament.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Màxim de caràcters de la comprensió d'imatges`},help:{"v1-ebnxhk-3q":`Longitud màxima per defecte de la descripció d'imatges. Utilitzeu un valor més baix per a un context compacte o un valor més alt per a un OCR i una anàlisi d'escenes detallats.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Model preferit de comprensió d'imatges`},help:{"v1-1o2uwo6-3c":`Doneu preferència a una entrada de tools.media.models etiquetada amb la capacitat de comprensió d'imatges abans de recórrer a la resta d'alternatives compatibles.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Instrucció de comprensió d'imatges`},help:{"v1-3a7piy-3p":`Instrucció de comprensió d'imatges per defecte quan una entrada no la substitueix. Utilitzeu una instrucció fixa quan els consumidors depenguin de descripcions estables.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Àmbit de comprensió d'imatges`},help:{"v1-tievo1-3s":`Restringiu la comprensió d'imatges per canal, tipus de xat o clau d'origen. Manteniu aquest àmbit limitat en canals amb molta activitat o no fiables per controlar el processament.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Temps d'espera de comprensió d'imatges (s)`},help:{"v1-1wcm84x-31":`Temps d'espera per defecte per a les sol·licituds de comprensió d'imatges. Augmenteu-lo per a imatges grans o models de visió locals més lents.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Models compartits de comprensió multimèdia`},help:{"v1-1bbsp4f-3x":`Llista de models de comprensió multimèdia. Utilitzeu etiquetes de capacitat d'imatge, àudio o vídeo a cada entrada perquè cada flux de processament seleccioni només alternatives compatibles.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Política de fitxers adjunts per a la comprensió de vídeos`},help:{"v1-1qm1qrc-3e":`Trieu quins fitxers de vídeo adjunts coincidents es processen. Processeu només el primer, tret que vulgueu analitzar diversos vídeos expressament.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Activa la comprensió de vídeo`},help:{"v1-1ltx5gl-58":`Activa la comprensió de vídeo perquè els clips es puguin resumir en text per al raonament i les respostes posteriors. Desactiva-la quan el processament de vídeo no estigui permès per les polítiques o sigui massa costós per al teu desplegament.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Màxim de bytes per a la comprensió de vídeo`},help:{"v1-2mp77v-3v":`Límit de mida predeterminat del vídeo d'entrada per als models configurats i detectats automàticament. Ajusta'l als límits de càrrega útil del proveïdor i a l'amplada de banda del desplegament.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Màxim de caràcters per a la comprensió de vídeo`},help:{"v1-1j0x40b-3j":`Longitud màxima predeterminada de la descripció del vídeo. Utilitza un valor més baix per a un context compacte o un valor més alt per a resums detallats de les escenes.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Model preferit per a la comprensió de vídeo`},help:{"v1-1cygq5k-3c":`Dona preferència a una entrada de tools.media.models amb etiquetes de capacitat per a la comprensió de vídeo abans de les altres alternatives compatibles.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Instrucció per a la comprensió de vídeo`},help:{"v1-692dhv-3m":`Instrucció predeterminada per a la comprensió de vídeo quan una entrada no la substitueix. Utilitza una instrucció fixa quan els consumidors depenguin de resums estables.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Àmbit de la comprensió de vídeo`},help:{"v1-7gfrx3-3s":`Restringeix la comprensió de vídeo segons el canal, el tipus de xat o la clau d'origen. Mantén aquest àmbit limitat en canals amb molta activitat o no fiables per controlar el processament.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Temps d'espera de la comprensió de vídeo (s)`},help:{"v1-e8rzsy-33":`Temps d'espera predeterminat per a les sol·licituds de comprensió de vídeo. Augmenteu-lo per a clips més llargs o models d'anàlisi locals més lents.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Llista d'accions de missatge permeses`},help:{"v1-1iceqwa-5c":`Llista global d'accions permeses per a l'eina de missatges. Feu-la servir només quan tot l'entorn d'execució hagi d'oferir i acceptar un conjunt reduït d'accions; per als agents públics o aïllats, és preferible fer servir llistes d'accions permeses per agent.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Activa la difusió de missatges`},help:{"v1-1ms74z7-14":`Activa l'acció de difusió (valor predeterminat: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Permet l'enviament entre contextos (entre proveïdors)`},help:{"v1-276qxo-2s":`Permet els enviaments entre proveïdors diferents (valor predeterminat: true). Establiu-ho a false per bloquejar la missatgeria entre proveïdors.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Permet l'enviament entre contextos (mateix proveïdor)`},help:{"v1-1sg4x49-1z":`Permet els enviaments a altres canals del mateix proveïdor (valor predeterminat: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Marcador d'enviament entre contextos`},help:{"v1-1fg6jrp-1z":`Afegeix un marcador d'origen visible en enviar entre contextos (valor predeterminat: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Prefix del marcador d'enviament entre contextos`},help:{"v1-eblsru-1p":`Prefix de text per als marcadors d'enviament entre contextos (admet "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Sufix del marcador d'enviament entre contextos`},help:{"v1-1nk0jub-1p":`Sufix de text per als marcadors entre contextos (admet "{channel}").`}},"tools%2Eopenclaw":{label:{"v1-m2tz7g-j":`Delegació a OpenClaw`},help:{"v1-4bdi5v-26":`Política d'aprovació dels canvis persistents delegats a l'agent de sistema OpenClaw.`}},"tools%2Eopenclaw%2EautoApproveChanges":{label:{"v1-1arx74u-u":`Aprovació automàtica dels canvis delegats`},help:{"v1-1gy96r5-br":`Autorització permanent per a l'administració delegada permesa, inclosa la configuració que pot executar codi a l'amfitrió de Gateway. El valor true autoritza els canvis sense aprovació individual, fins i tot quan les eines d'execució directa estan denegades; el valor false sempre requereix aprovació. Si s'omet, s'utilitza l'accés complet explícit o l'execució sense restriccions a Gateway verificada de manera independent. Les restriccions del sistema de fitxers, de l'entorn aïllat, de les operacions i de l'execució actual continuen aplicant-se.`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Perfil d'eines`},help:{"v1-h6k98q-5k":`Nom del perfil global d'eines que s'utilitza per seleccionar una política base d'eines predefinida abans d'aplicar les excepcions de permís o denegació. Utilitzeu-lo per mantenir una configuració coherent de l'entorn entre agents i manteniu estables els noms dels perfils.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Política d'eines de l'entorn aïllat`},help:{"v1-ea7awo-4k":`Capa de política d'eines per a les execucions d'agents en entorns aïllats, perquè aquestes execucions puguin tenir límits de capacitats diferenciats. Utilitzeu-la per reforçar la seguretat en contextos aïllats.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Política de permís o denegació d'eines de l'entorn aïllat`},help:{"v1-ub701o-4t":`Política de permís o denegació d'eines que s'aplica quan els agents s'executen en entorns d'execució aïllats. Manteniu les polítiques al mínim perquè les tasques de l'entorn aïllat no puguin derivar en accions externes innecessàries.`}},"tools%2Esessions%2EallowThreadTargets":{label:{"v1-1o1dl7e-p":`Permet fils com a destinacions d'enviament`},help:{"v1-1ppcmoz-6v":`Permet que sessions_send tingui com a destinació sessions de xat limitades a un fil o tema, com ara els temes de fòrums de Telegram o els fils de Slack/Discord (per defecte: false). La destinació s'executa en aquella sessió; tot el que envia amb l'eina message arriba al fil visible per als usuaris.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Visibilitat de les eines de sessió`},help:{"v1-1p13n9k-fm":`Controla a quines sessions es pot accedir amb sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all", valor per defecte = qualsevol sessió de la Passarel·la, incloses les d'altres agents i usuaris; "agent" = qualsevol sessió de l'identificador d'agent actual; "self" = només l'actual; "tree" = sessió actual + sessions de subagents creats). L'accés entre agents està activat per defecte i el seu abast es defineix amb tools.agentToAgent; utilitzeu una visibilitat més restringida per limitar les lectures i els enviaments ordinaris. Les destinacions explícites d'agents.entries.<id>.tools.agentToAgent.send poden permetre enviaments sense ampliar l'accés de lectura.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Política d'eines dels subagents`},help:{"v1-1xoug01-4z":`Capa de política d'eines per als subagents creats que permet restringir o ampliar la disponibilitat d'eines respecte dels valors per defecte de l'agent principal. Utilitzeu-la per limitar les capacitats dels agents delegats a l'objectiu de la tasca.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Política d'eines permeses i denegades dels subagents`},help:{"v1-7vxsbf-5d":`Política d'eines permeses i denegades aplicada als entorns d'execució dels subagents creats. Manteniu-la més restringida que l'abast de l'agent principal. Les eines pròpies de l'agent principal, com ara progress_card, sempre es deneguen, fins i tot mitjançant allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Eixam`},help:{"v1-1q96vvs-45":`Orquestració de subagents en mode de recopilació. Activada per defecte; establiu el valor false per desactivar-la. Els permisos d'eines continuen aplicant-se a agents_wait i a les opcions de creació de l'eixam.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Agent per defecte de l'eixam`},help:{"v1-p4alpg-2m":`Agent de destinació per defecte per a les creacions de l'eixam que ometen agentId. La llista de subagents permesos continua sent aplicable.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Activa l'eixam`},help:{"v1-1nnnrq9-2e":`Activa els subagents en mode recol·lector i agents_wait. Està activat per defecte; establiu false per desactivar-lo.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Fills vius per grup d'eixam`},help:{"v1-kfx6qp-1c":`Nombre màxim de fills recol·lectors vius per grup d'eixam.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1a16wrf-z":`Fills simultanis per grup d'eixam`},help:{"v1-1ednj37-70":`Nombre màxim de fills recol·lectors en execució al carril d'execució independent de cada grup d'eixam (per defecte: 32), independentment de la concurrència dels subagents ordinaris. Cada fill en execució utilitza un flux de model i una instància aïllada de treballador de Code Mode. Els límits d'admissió del grup continuen aplicant-se.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Total de fills per grup d'eixam`},help:{"v1-1gc9vl1-1e":`Nombre màxim de recol·lectors creats durant tota la vida de cada grup d'eixam.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Temps d'espera màxim de l'eixam`},help:{"v1-bog18y-1g":`Temps d'espera màxim acceptat per agents_wait, en segons.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Cerca d'eines`},help:{"v1-g2rpl8-80":`Compacta els catàlegs grans d'eines d'OpenClaw, d'MCP i del client. Quan no es configura, els entorns d'execució d'OpenClaw utilitzen automàticament la cerca estructurada d'eines; Code Mode té prioritat quan està activat i Codex utilitza la seva cerca nativa. Establiu false per desactivar-la, true per utilitzar la cerca estructurada o feu servir el format d'objecte per triar un mode.`}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Activa la cerca d'eines`},help:{"v1-1naa8jz-3v":`Activa la cerca d'eines. Quan està activada, OpenClaw amaga els catàlegs grans d'eines darrere d'eines estructurades de cerca, descripció i crida durant les execucions de l'entorn integrat.`}},"tools%2EtoolSearch%2Eexclude":{label:{"v1-1040rv9-t":`Selectors d'exclusió de la cerca d'eines`},help:{"v1-pmx6vl-60":`Eines que es mantindran directament visibles en lloc de catalogar-les. Utilitza els mateixos selectors que include; l'exclusió té prioritat. Si s'omet o és [], no s'exclou res. No atorga permisos ni modifica les restriccions de les eines només d'accés directe o necessàries en temps d'execució.`}},"tools%2EtoolSearch%2Eexclude%5B%5D%2Ename":{label:{"v1-7sh15i-i":`Nom de l'eina exclosa`},help:{"v1-ke0ysb-4v":`Nom registrat de l'eina o patró amb comodí * per mantenir-la accessible directament, amb la normalització de la política d'eines. Els selectors que només especifiquen el nom cerquen coincidències en tots els orígens; especifiqueu l'origen per evitar coincidències no desitjades.`}},"tools%2EtoolSearch%2Eexclude%5B%5D%2Esource":{label:{"v1-1u3p208-k":`Origen de l'eina exclosa`},help:{"v1-1r3h9ad-2x":`Origen que s'exclourà de la catalogació: "openclaw", "mcp" o "client". Es combina amb name mitjançant AND quan tots dos són presents.`}},"tools%2EtoolSearch%2Einclude":{label:{"v1-130v30b-t":`Selectors d'inclusió de la cerca d'eines`},help:{"v1-1567ter-7t":`Selectors de presentació per a eines aptes per al catàleg i aprovades per la política. Si s'omet, se seleccionen totes les eines aptes; [] no en selecciona cap. Els camps d'un selector es combinen amb AND; els selectors es combinen amb OR. Les eines no seleccionades continuen sent invocables directament. No afecta el Code Mode independent ni la cerca nativa de Codex.`}},"tools%2EtoolSearch%2Einclude%5B%5D%2Ename":{label:{"v1-ewc3qk-i":`Nom de l'eina inclosa`},help:{"v1-8gy1xg-4o":`Nom registrat de l'eina o patró amb comodí *, amb la normalització de la política d'eines (inclosos els àlies). Els selectors que només especifiquen el nom cerquen coincidències en tots els orígens. No s'admeten expressions regulars ni l'expansió de grups d'eines.`}},"tools%2EtoolSearch%2Einclude%5B%5D%2Esource":{label:{"v1-31fgve-k":`Origen de l'eina inclosa`},help:{"v1-19ewj5n-52":`Origen de l'eina: "openclaw" per a les eines del nucli i els connectors que no són MCP, "mcp" per a les eines MCP registrades o "client" per a les eines proporcionades pel client. Especifiqueu l'origen dels noms per evitar coincidències amb noms semblants.`}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Nombre màxim de resultats de la cerca d'eines`},help:{"v1-7du4kh-32":`Nombre màxim de resultats de la cerca d'eines que pot sol·licitar un model. En temps d'execució, els valors es limiten a l'interval admès d'1 a 50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Interfície de cerca d'eines`},help:{"v1-1uvcg7i-6z":`Trieu la interfície que es presenta al model: "tools" (per defecte) ofereix eines estructurades de cerca, descripció i crida; "directory" manté visible un directori limitat d'eines, exposa un conjunt limitat d'esquemes probables o necessaris i deixa la resta accessibles mitjançant la cerca, la descripció i la crida.`}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Nombre de resultats per defecte de la cerca d'eines`},help:{"v1-1uchq7t-39":"Nombre de resultats de la cerca d'eines que es retornen per defecte quan el model omet el límit. En temps d'execució, aquest valor es limita a `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Activa l'eina de plans estructurats`},help:{"v1-1xgegme-4o":"Eina d'estat unificada `progress_card` per a plans persistents i notes narratives a les sessions pare. Activada per defecte; establiu-la a false per desactivar-la. Mai no està disponible per als subagents."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Eines web`},help:{"v1-fpsy5-4y":`Agrupació de polítiques d'eines web per ajustar els proveïdors de cerca i obtenció de contingut, els límits i el comportament alternatiu. Manteniu les opcions activades en consonància amb la disponibilitat de claus d'API i la política de connexions de xarxa sortints.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL de la memòria cau d'obtenció de contingut web (min)`},help:{"v1-1hk89qp-17":`TTL de la memòria cau en minuts per als resultats de web_fetch.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Activa l'eina d'obtenció web`},help:{"v1-yrswld-1f":`Activa l'eina web_fetch (obtenció HTTP lleugera).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Capçaleres de les sol·licituds d'obtenció web`},help:{"v1-16bjkv5-me":"Capçaleres addicionals que s'envien amb les sol·licituds directes de web_fetch, com ara capçaleres d'encaminament de la passarel·la o d'autenticació. Tots els valors configurats es tracten com a sensibles i s'oculten a la configuració exposada i a les captures de depuració. Els valors són cadenes de text simples, admeten la substitució ${VAR} i l'escapament literal global $${VAR}, i s'envien a URL triats pel model. Les entrades es validen quan es construeix la sol·licitud, no quan es carrega la configuració; per tant, un nom incorrecte o un valor que no es pot enviar es descarta i es registra en lloc de desactivar la funcionalitat. També es descarten Accept, Accept-Language, User-Agent i les capçaleres de delimitació com ara Transfer-Encoding. Utilitzeu tools.web.fetch.userAgent per canviar l'agent d'usuari. Les redireccions entre orígens només conserven les capçaleres de la llista de capçaleres segures permeses de guarded-fetch, i els canvis en les capçaleres enviades efectivament particionen la memòria cau d'obtenció."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Màxim de caràcters de l'obtenció web`},help:{"v1-12d1fw7-1d":`Màxim de caràcters retornats per web_fetch (amb truncament).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Límit màxim absolut de caràcters de l'obtenció web`},help:{"v1-cl2mf1-1v":`Límit absolut per a maxChars de web_fetch (s'aplica a la configuració i a les crides a l'eina).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Màxim de redireccions de l'obtenció web`},help:{"v1-t6eak9-1h":`Nombre màxim de redireccions permeses per a web_fetch (per defecte: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Mida màxima de descàrrega de l'obtenció web (bytes)`},help:{"v1-q6ld9c-10":`Mida màxima de descàrrega abans del truncament.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Proveïdor d'obtenció web`},help:{"v1-6pb3nv-v":`Identificador del proveïdor alternatiu d'obtenció web.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Extracció amb Readability per a l'obtenció web`},help:{"v1-19exqzx-2c":`Utilitza Readability per extreure el contingut principal de l'HTML (recorre a una neteja bàsica de l'HTML com a alternativa).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Política SSRF de l'obtenció web`},help:{"v1-qtn7zx-3c":`Excepcions d'abast limitat a la política SSRF per a web_fetch. Manteniu-ne l'abast restringit i activeu-les només en entorns coneguts de servidor intermediari de xarxa local.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Noms d'amfitrió permesos per a l'obtenció web`},help:{"v1-1j9ctya-35":`Noms d'amfitrió exactes o adreces IP literals permesos per a web_fetch, incloses les destinacions que altrament estarien bloquejades. Manteniu la llista al mínim.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Permet l'interval local únic d'IPv6 per a l'obtenció web`},help:{"v1-1eyz55i-3b":`Permet adreces locals úniques d'IPv6 (fc00::/7) per garantir la compatibilitat amb servidors intermediaris de confiança que utilitzen IP fictícies, com ara sing-box, Clash o Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Permet l'interval de proves de rendiment de l'RFC 2544 per a l'obtenció web`},help:{"v1-u5asdb-2y":`Permet les IP de l'interval de proves de rendiment de l'RFC 2544 (198.18.0.0/15) per garantir la compatibilitat amb servidors intermediaris que utilitzen IP fictícies, com ara Clash o Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Noms d'amfitrió bloquejats per a l'obtenció web`},help:{"v1-1164vvk-66":`Patrons de noms d'amfitrió que es deneguen abans de la resolució DNS i de les regles de permís en cada redirecció de web_fetch. Admet amfitrions exactes i "*.example.com" només per als subdominis; afegiu "example.com" per separat per bloquejar el domini arrel. Si és buit o no està definit, no s'afegeix cap denegació.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Permetre l'accés a la xarxa privada per a l'obtenció web (perillós)`},help:{"v1-2s6mv7-3t":`Permet que web_fetch accedeixi a destinacions de xarxes privades i internes. Manteniu aquesta opció desactivada tret que els URL seleccionats pel model siguin de confiança en aquest desplegament.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Temps d'espera de l'obtenció web (s)`},help:{"v1-1c3yfr4-16":`Temps d'espera en segons per a les sol·licituds de web_fetch.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent de l'obtenció web`},help:{"v1-s7pe8j-1e":`Substitueix la capçalera User-Agent de les sol·licituds de web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Servidor intermediari d'entorn de confiança per a l'obtenció web`},help:{"v1-1ypkqj7-54":`Encamina web_fetch a través d'un servidor intermediari HTTP(S) de confiança configurat a l'entorn i deixa que aquest resolgui el DNS. Activeu aquesta opció només si l'operador controla aquest servidor intermediari i si aquest aplica la política de trànsit de sortida després de la resolució DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL de la memòria cau de la cerca web (min)`},help:{"v1-6trzlf-18":`TTL de la memòria cau en minuts per als resultats de web_search.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Activa l'eina de cerca web`},help:{"v1-n1cm4y-27":`Activa web_search gestionat i la cerca nativa opcional de Codex per als models compatibles.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Nombre màxim de resultats de la cerca web`},help:{"v1-mrw7mi-z":`Nombre de resultats que es retornaran (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Dominis permesos de Codex`},help:{"v1-1cv4y44-43":`Llista de dominis permesos per a web_search natiu de Codex. En els torns de cerca allotjada nativa, també restringeix web_fetch gestionat; els torns amb proveïdor gestionat no canvien.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Mida del context de cerca de Codex`},help:{"v1-antack-1u":`Indicació de la mida del context de cerca nativa de Codex: "low", "medium" o "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Activa la cerca web nativa de Codex`},help:{"v1-ek2jzd-1k":`Activa la cerca web nativa de Codex per als models compatibles amb Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Mode de cerca web de Codex`},help:{"v1-1ahyq9f-32":`Preferència de cerca web nativa de Codex: "cached" (per defecte; els torns de Codex sense restriccions ho resolen com a "live") o "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Ciutat de l'usuari de Codex`},help:{"v1-1y95orp-1d":`Ciutat aproximada enviada a la cerca web nativa de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`País de l'usuari de Codex`},help:{"v1-1xkm5ms-1g":`País aproximat enviat a la cerca web nativa de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Regió de l'usuari de Codex`},help:{"v1-lhar02-1l":`Regió o estat aproximat enviat a la cerca web nativa de Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Fus horari de l'usuari de Codex`},help:{"v1-fgv9fh-1h":`Fus horari aproximat enviat a la cerca web nativa de Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Proveïdor de cerca web`},help:{"v1-10omglr-1x":`Identificador del proveïdor de cerca. Si s'omet, es detecta automàticament a partir de les claus d'API disponibles.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Temps d'espera de la cerca web (s)`},help:{"v1-i0egvw-17":`Temps d'espera en segons per a les sol·licituds de web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transcripcions`},help:{"v1-1i0sc09-66":`Configuració bàsica de captura de transcripcions per a notes de reunions, eines d'agent amb capacitat de gravació i fonts configurades d'inici automàtic de reunions en directe. Els connectors de reunions capturen notes persistents per defecte; establiu enabled a false per desactivar-ho globalment.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Fonts d'inici automàtic de transcripcions`},help:{"v1-1mzsl79-5s":`Fonts de transcripció en directe gestionades automàticament des de l'inici de la Passarel·la. Cada entrada s'activa pel fet de ser-hi present; elimineu una entrada per desactivar aquella font. Les fonts capturen contínuament tret que whenOccupied estigui activat.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Identificador del compte de transcripció`},help:{"v1-6g2kjj-4b":`Identificador opcional del compte o de l'espai de treball del proveïdor per a fonts de transcripció que requereixen distingir entre comptes. Utilitzeu el format d'identificador de compte documentat pel proveïdor.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`ID del canal de transcripció`},help:{"v1-1lk9d5o-4u":`Identificador del canal del proveïdor per a la font de transcripció en directe, com ara un canal de veu de Discord o un canal de reunions ràpides de Slack. Verifiqueu la semàntica dels identificadors específica del proveïdor abans d'activar l'inici automàtic.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`ID del servidor de Discord`},help:{"v1-fyfgnk-4l":`Identificador opcional del servidor de Discord per a fonts de transcripció de veu de Discord. Configureu-lo amb el channelId corresponent quan el proveïdor necessiti cercar canals de veu dins d'un servidor.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`URL de la reunió de transcripció`},help:{"v1-1xtt9ci-4f":`URL de reunió opcional per a proveïdors que s'hi uneixen mitjançant un URL en lloc d'un identificador de canal. Utilitzeu només enllaços de reunió de confiança, ja que l'inici automàtic pot unir-se a la reunió i capturar-ne el contingut.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`ID del proveïdor de la font de transcripció`},help:{"v1-1uur06p-3s":`Identificador del proveïdor de la font de transcripció, com ara un proveïdor de veu de Discord o un futur proveïdor de reunions ràpides de Slack. Utilitzeu l'identificador exacte que exposa el connector del proveïdor.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`ID de la sessió de transcripció`},help:{"v1-xyo4x5-5o":`Identificador fix opcional de sessió de transcripció per a aquesta font d'inici automàtic. S'ignora quan whenOccupied és true. Deixeu-lo sense definir perquè es generin identificadors, tret que necessiteu un selector diari estable i pugueu evitar col·lisions dins del mateix dia.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Títol de la transcripció`},help:{"v1-ycjnmp-5y":`Títol opcional per a futures captures de transcripcions. Canviar només els títols manté les captures actuals en execució i no canvia el títol assignat ni les notes desades. Els altres canvis de la font mantenen el comportament habitual de reinici.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Captura de transcripcions quan hi ha participants`},help:{"v1-34jid4-78":`Inicia una nova sessió de transcripció cada vegada que hi ha persones presents a la font i l'atura (generant notes) quan marxa l'última persona. Requereix un proveïdor que informi de la presència de participants, com ara discord-voice. Valor per defecte: false (captura contínua des de l'inici de la Passarel·la).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transcripcions habilitades`},help:{"v1-fyqqr0-6d":`Habilita les notes automàtiques persistents de reunions, l'eina de transcripcions de l'agent i les fonts d'inici automàtic configurades. Valor per defecte: true. Establiu-lo a false per desactivar la persistència i l'eina; el mode explícit de transcripció de reunions conserva el seu tram final limitat en directe.`}},tts:{label:{"v1-bmxkk9-e":`Síntesi de veu`},help:{"v1-1o27tk2-4n":`Política de síntesi de veu per llegir en veu alta les respostes de l'agent en interfícies de veu o àudio compatibles. Manteniu-la desactivada tret que la reproducció de veu formi part del vostre flux de treball com a operador o usuari.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Perfil de veu TTS`},help:{"v1-1r0opcb-29":`Identificador del perfil de veu TTS per defecte. Les preferències locals del perfil de veu TTS poden substituir aquest valor per a cada amfitrió.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Perfils de veu TTS`},help:{"v1-19aybhl-2l":`Perfils de veu TTS amb nom que defineixen una identitat vocal estable i vinculacions de veu específiques de cada proveïdor.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Perfil de veu TTS`},help:{"v1-10s52ah-2l":`Una personalitat TTS. Utilitzeu vinculacions específiques del proveïdor per definir veus i models concrets i plantilles d'instruccions.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Vinculacions de proveïdor de la personalitat TTS`},help:{"v1-993jop-3e":`Vinculacions de personalitat TTS específiques del proveïdor, indexades per l'identificador del proveïdor de veu. Es combinen amb tts.providers i en sobreescriuen els valors per a la personalitat activa.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Configuració del proveïdor TTS`},help:{"v1-1k80nl4-4y":`Configuració TTS específica del proveïdor, indexada per l'identificador del proveïdor de veu. Utilitzeu-la en lloc de les claus de nivell superior específiques dels proveïdors integrats perquè els connectors de veu es mantinguin desacoblats de l'esquema de configuració principal.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Configuració del proveïdor TTS`},help:{"v1-dwapva-3d":`Configuració TTS específica del proveïdor per a un identificador de proveïdor de veu. Manteniu els camps dins de l'àmbit del connector al qual pertany aquest proveïdor.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Clau d'API del proveïdor TTS`},help:{"v1-1m2fj0i-2o":`Clau d'API del proveïdor que utilitza aquest proveïdor de veu quan el seu connector requereix accés autenticat a TTS.`}},tui:{label:{"v1-c8hus1-b":`Interfície del Terminal`},help:{"v1-1fg9vw2-3s":`Configuració de visualització de la interfície del Terminal. Utilitzeu aquesta secció per a les preferències de presentació exclusives del terminal sense canviar el comportament de la Passarel·la ni d'altres interfícies.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Peu de la interfície del Terminal`},help:{"v1-6e12l3-3k":`Configuració de visualització del peu de la interfície del Terminal. Manteniu el context opcional compacte perquè la informació sobre la sessió, el model, l'objectiu i els tòkens continuï sent llegible.`}},ui:{label:{"v1-ye4dff-2":`Interfície d'usuari`},help:{"v1-dt1924-42":`Configuració de presentació de la interfície d'usuari per als elements destacats i les preferències de visualització de l'operador. Utilitzeu-la per personalitzar la llegibilitat sense canviar el comportament en temps d'execució.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Color d'accent de l'usuari`},help:{"v1-mpxaka-4y":`Color d’accent de l’aplicació web: #RRGGBB per a un color personalitzat o 'theme' per a la paleta del tema seleccionat. Substitueix ui.seamColor; deixeu-lo buit per heretar el color d’accent configurat o el valor per defecte del tema.`}},"ui%2Eprefs%2Elocale":{label:{"v1-sk0cbe-i":`Llengua de la interfície`},help:{"v1-6mqtbz-6x":`Idioma de l’aplicació web, indicat amb un identificador de configuració regional admès, com ara en, de o zh-CN. Deixeu-lo sense definir per utilitzar l’idioma del navegador o del sistema. Configureu-lo a Configuració → Aparença → Idioma. No estableix la zona horària de l’assistent (agents.defaults.userTimezone).`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Color d'accent`},help:{"v1-14q3r4h-4g":`Color d'accent principal que utilitzen les superfícies de la interfície per ressaltar elements, mostrar distintius i aportar indicacions d'identitat visual. Utilitzeu valors d'alt contrast que mantinguin la llegibilitat tant en temes clars com foscos.`}},update:{label:{"v1-k12u1x-7":`Actualitzacions`},help:{"v1-11c5k8v-5c":`Comportament del canal d'actualització i de la comprovació en iniciar per mantenir al dia les versions de l'entorn d'execució d'OpenClaw. Utilitzeu canals conservadors en producció i canals més experimentals només en entorns controlats.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Actualització automàtica activada`},help:{"v1-49xs2h-3c":`Activa l'actualització automàtica en segon pla per a instal·lacions de paquets stable i beta; extended-stable mai no s'aplica automàticament (valor predeterminat: false).`}},"update%2Eauto%2Eschedule":{label:{"v1-1t6cr06-p":`Programació de les actualitzacions automàtiques`},help:{"v1-zuf1kc-5y":`Expressió cron opcional per a l'inici de les campanyes d'actualització automàtica de Gateway, segons el fus horari de l'amfitrió de Gateway. Ometeu-la per mantenir la freqüència actual d'una vegada per hora. Els retards de desplegament i els comptes enrere d'inactivitat continuen aplicant-se; s'ometen les franges horàries que ja han passat.`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Canal d'actualització`},help:{"v1-lqtdvf-5b":`Canal d'actualització per a instal·lacions amb git + npm ("stable", "extended-stable", "beta" o "dev"). El canal extended-stable només està disponible per a paquets: la instal·lació es fa exclusivament en primer pla, amb avisos opcionals de només lectura en iniciar.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Comprovació d'actualitzacions en iniciar`},help:{"v1-qy3q9g-5v":`Comprova si hi ha actualitzacions quan s'inicia la Passarel·la, inclosos els avisos d'extended-stable de només lectura (per defecte: true). Establiu-ho a false per desactivar la comprovació i l'aplicació automàtiques d'actualitzacions de la Passarel·la i dels nodes sense interfície, així com els senyals anònims d'actualització.`}},voicewake:{label:{"v1-txt1wb-a":`Activació per veu`}},web:{label:{"v1-1ae9z56-b":`Canal web`}},wizard:{label:{"v1-28jonk-h":`Preferències de configuració`},help:{"v1-14jh6rm-3b":`Preferències de configuració pròpies de l'usuari. L'historial de l'assistent i l'estat de confirmació propis de la màquina es desen a la base de dades d'estat compartida.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Accés de detecció durant la configuració`},help:{"v1-1nqxt0w-38":`Consentiment de detecció per a la configuració guiada: "full" explora sense avisar, mentre que "guarded" demana permís abans d'inspeccionar les aplicacions locals.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Recomanacions d'aplicacions durant la configuració`},help:{"v1-ub8uoi-30":`Controla si la configuració guiada pot utilitzar les etiquetes de les aplicacions instal·lades per recomanar connectors i habilitats rellevants.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Marca de temps de l'última execució de l'assistent`},help:{"v1-1y0fbk-1k":`Marca de temps de l'última execució de l'assistent desada correctament.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Ordre de l'última execució de l'assistent`},help:{"v1-x2pfkk-15":`Ordre que va invocar l'última execució de l'assistent.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit de l'última execució de l'assistent`},help:{"v1-h0jkmt-1i":`Commit del codi font utilitzat en l'última execució de l'assistent en desenvolupament.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Mode de l'última execució de l'assistent`},help:{"v1-16508qy-1r":`Indica si l'última execució de l'assistent tenia com a destinació una configuració "local" o "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Versió de l'última execució de l'assistent`},help:{"v1-1tr4z9d-19":`Versió d'OpenClaw utilitzada en l'última execució de l'assistent.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Marca de temps de la confirmació de seguretat de l'assistent`},help:{"v1-86i182-2a":`Marca de temps de la confirmació de seguretat durant la configuració, desada amb la configuració de destinació.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Acceleració dels arbres de treball`},help:{"v1-9es3gc-4r":`Utilitza l'acceleració del sistema de fitxers per als arbres de treball gestionats nous quan sigui compatible (valor per defecte: true). Establiu-ho a false per utilitzar el checkout habitual de Git i la còpia de fitxers. Només s'aplica als arbres de treball nous.`}},worktreeMaxCount:{label:{"v1-1gj5fhm-p":`Nombre màxim d'arbres de treball gestionats`},help:{"v1-6z5l36-7q":`Nombre màxim d'arbres de treball gestionats existents entre tots els agents i repositoris (valor per defecte: 4096). Primer elimina les branques fusionades o amb les confirmacions comprimides, i després els arbres de treball inactius més antics, incloses les dades no desades. Les execucions en curs estan protegides; augmenteu aquest valor si arriben al límit. El control d'admissió segons l'espai en disc continua aplicant-se.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Arrel dels arbres de treball`},help:{"v1-1tgti9j-5d":`Directori global per als arbres de treball gestionats nous. Utilitzeu un camí absolut o ~ per al vostre directori d'inici; el valor per defecte és <state-dir>/worktrees. Els arbres de treball existents conserven els camins registrats quan es modifica aquest valor.`}}}}})))()}export{i as n,n as t};